-- ------------------------------------------------------------
IF OBJECT_ID('dbo.Categories','U') IS NOT NULL DROP TABLE dbo.Categories;
GO
CREATE TABLE dbo.Categories (
    CategoryNo    INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Categories PRIMARY KEY,
    CategoryName  NVARCHAR(100) NOT NULL,
    CategoryCode  VARCHAR(20)  NOT NULL,
    Description   NVARCHAR(300) NULL,
    IsMandatory   BIT          NOT NULL CONSTRAINT DF_Cat_Mandatory DEFAULT 0,
    -- 1 = document must be uploaded before employee record can be submitted
    ParentCategoryNo INT       NULL,   -- supports 2-level hierarchy (optional)
    Status        TINYINT      NOT NULL CONSTRAINT DF_Cat_Status DEFAULT 1,
    CreatedAt     DATETIME2(0) NOT NULL CONSTRAINT DF_Cat_CreatedAt DEFAULT GETDATE(),
    UpdatedAt     DATETIME2(0) NULL,
    CreatedBy     INT          NULL,   -- FK to dbo.Users added later
    CONSTRAINT UQ_Cat_Code   UNIQUE (CategoryCode),
    CONSTRAINT CK_Cat_Status CHECK (Status IN (0,1)),
    CONSTRAINT FK_Cat_Parent FOREIGN KEY (ParentCategoryNo)
        REFERENCES dbo.Categories (CategoryNo)
);
GO
CREATE NONCLUSTERED INDEX IX_Cat_Parent ON dbo.Categories (ParentCategoryNo) WHERE ParentCategoryNo IS NOT NULL;
GO

