    RoleName     NVARCHAR(60) NOT NULL,
    RoleCode     VARCHAR(20)  NOT NULL,
    -- Valid codes: Employee / Manager / Admin / HR_Manager / Recruiter /
    --              Payroll_Exec / Finance_Head / Director / Store_Manager / Dept_Head
    Description  NVARCHAR(300) NULL,
    IsSystemRole BIT          NOT NULL CONSTRAINT DF_Role_System DEFAULT 0,
    -- IsSystemRole = 1 means the role cannot be deleted
    Status       TINYINT      NOT NULL CONSTRAINT DF_Role_Status DEFAULT 1,
    CreatedAt    DATETIME2(0) NOT NULL CONSTRAINT DF_Role_CreatedAt DEFAULT GETDATE(),
    UpdatedAt    DATETIME2(0) NULL,
    CONSTRAINT UQ_Role_Code   UNIQUE (RoleCode),
    CONSTRAINT CK_Role_Status CHECK (Status IN (0,1))
);
GO

-- ============================================================
-- SECTION 5 — USERS   (one of the 5 required tables)
-- Covers both employee login accounts and non-employee users
-- (recruiters, finance, etc.).
-- ============================================================
IF OBJECT_ID('dbo.Users','U') IS NOT NULL DROP TABLE dbo.Users;
GO
CREATE TABLE dbo.Users (
    UserNo           INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Users PRIMARY KEY,
    UserGUID         UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Users_GUID DEFAULT NEWID(),
    Username         NVARCHAR(60)  NOT NULL,
    Email            NVARCHAR(150) NOT NULL,
    PasswordHash     NVARCHAR(256) NOT NULL,   -- bcrypt / PBKDF2 hash — never plain text
    PasswordSalt     NVARCHAR(100) NULL,
    RoleNo           INT           NOT NULL,
    -- FK to dbo.Roles — determines portal access level
    EmployeeNo       INT           NULL,
    -- NULL for non-employee system users (e.g. pure-recruiter accounts)
    -- Populated once the employee record is linked
    IsActive         BIT           NOT NULL CONSTRAINT DF_Users_Active  DEFAULT 1,
    IsEmailVerified  BIT           NOT NULL CONSTRAINT DF_Users_EV      DEFAULT 0,
    LastLoginAt      DATETIME2(0)  NULL,
    FailedLoginCount TINYINT       NOT NULL CONSTRAINT DF_Users_FLC     DEFAULT 0,
    IsLocked         BIT           NOT NULL CONSTRAINT DF_Users_Locked  DEFAULT 0,
    LockReason       NVARCHAR(200) NULL,
    -- Session management
    RefreshToken     NVARCHAR(512) NULL,
    RefreshTokenExpiry DATETIME2(0) NULL,
    -- Audit columns
    CreatedAt        DATETIME2(0)  NOT NULL CONSTRAINT DF_Users_CreatedAt DEFAULT GETDATE(),
    UpdatedAt        DATETIME2(0)  NULL,
    CreatedBy        INT           NULL,
    -- Self-referential: which admin created this user (NULL for seed data)
    CONSTRAINT UQ_Users_Email    UNIQUE (Email),
    CONSTRAINT UQ_Users_Username UNIQUE (Username),
    CONSTRAINT UQ_Users_GUID     UNIQUE (UserGUID),
    CONSTRAINT CK_Users_FL  CHECK (FailedLoginCount >= 0 AND FailedLoginCount <= 10),
    CONSTRAINT FK_Users_Role FOREIGN KEY (RoleNo) REFERENCES dbo.Roles (RoleNo)
);
GO
CREATE NONCLUSTERED INDEX IX_Users_RoleNo   ON dbo.Users (RoleNo);
CREATE NONCLUSTERED INDEX IX_Users_EmpNo    ON dbo.Users (EmployeeNo) WHERE EmployeeNo IS NOT NULL;
GO

-- ============================================================
-- SECTION 6 — GRADE  (needed by Department, Designation, etc.)
-- ============================================================
IF OBJECT_ID('dbo.Grade','U') IS NOT NULL DROP TABLE dbo.Grade;
GO
CREATE TABLE dbo.Grade (
    GradeNo          INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Grade PRIMARY KEY,
    GradeName        NVARCHAR(40) NOT NULL,
    GradeShortName   VARCHAR(10)  NOT NULL,
    StateNo          SMALLINT     NULL,   -- NULL = nationwide; set for state-specific bands
    MinBasicSalary   DECIMAL(12,2) NOT NULL CONSTRAINT DF_Grade_MinBasic DEFAULT 0,
    MaxBasicSalary   DECIMAL(12,2) NOT NULL,
    FixedBasicSalary DECIMAL(12,2) NULL,  -- overrides min/max when not NULL
    HolidayBenefit   VARCHAR(20)  NOT NULL CONSTRAINT DF_Grade_HolBen DEFAULT 'No Benefit',
    LeavesToCancelBenefitOfAllowedLeaves INT NOT NULL CONSTRAINT DF_Grade_LCBA DEFAULT 0,
    Status           TINYINT      NOT NULL CONSTRAINT DF_Grade_Status DEFAULT 1,
    CreatedAt        DATETIME2(0) NOT NULL CONSTRAINT DF_Grade_CreatedAt DEFAULT GETDATE(),
    UpdatedAt        DATETIME2(0) NULL,
    CONSTRAINT CK_Grade_Sal     CHECK (MaxBasicSalary >= MinBasicSalary),
    CONSTRAINT CK_Grade_HolBen  CHECK (HolidayBenefit IN ('No Benefit','Full Day','Half Day','1.5 Day','2 Day','2.5 Day')),
    CONSTRAINT CK_Grade_Status  CHECK (Status IN (0,1)),
    CONSTRAINT FK_Grade_State   FOREIGN KEY (StateNo) REFERENCES dbo.State (StateNo)
);
GO

