-- ============================================================
-- SECTION 10 — EMPLOYEE  (central entity)
-- ============================================================
IF OBJECT_ID('dbo.Employee','U') IS NOT NULL DROP TABLE dbo.Employee;
GO
CREATE TABLE dbo.Employee (
    EmployeeNo            INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Employee PRIMARY KEY,
    EmployeeCode          VARCHAR(20)   NOT NULL,   -- EMP-001 format
    EmployeeShortID       VARCHAR(10)   NULL,
    FirstName             NVARCHAR(60)  NOT NULL,
    LastName              NVARCHAR(60)  NOT NULL,
    ProfilePhoto          NVARCHAR(500) NULL,       -- URL / file path; max 2 MB enforced at app layer
    OfficialEmail         NVARCHAR(150) NULL,
    OfficialMobile        VARCHAR(15)   NULL,
    PersonalEmail         NVARCHAR(150) NULL,
    PersonalMobile        VARCHAR(15)   NULL,
    DateOfBirth           DATE          NOT NULL,   -- mandatory; no future dates
    DateOfJoining         DATE          NOT NULL,
    StatutoryJoiningDate  DATE          NULL,
    RetirementDate        DATE          NULL,

    -- Demographics (FKs to master tables)
    GenderNo              TINYINT       NOT NULL,
    BloodGroupNo          TINYINT       NOT NULL,
    MaritalStatusNo       TINYINT       NOT NULL,
    ReligionNo            TINYINT       NULL,
    NationalityNo         TINYINT       NOT NULL,

    -- Family basics (denormalised for performance; detail in EmployeeFamilyDetail)
    FatherHusbandName     NVARCHAR(100) NOT NULL,
    FatherOccupationNo    SMALLINT      NULL,
    MotherName            NVARCHAR(100) NOT NULL,
    MotherOccupationNo    SMALLINT      NULL,

    -- Statutory / identity (encrypted at rest in production)
    PANNumber             VARCHAR(10)   NOT NULL,
    AadhaarEIDNumber      VARCHAR(12)   NOT NULL,   -- 12 digits
    VoterID               VARCHAR(20)   NULL,
    UANNumber             VARCHAR(12)   NULL,       -- 12 digits
    EPFNumber             VARCHAR(30)   NULL,
    ESINumber             VARCHAR(17)   NULL,       -- 17 digits

    -- Organisation
    DepartmentNo          INT           NOT NULL,
    SubDepartmentNo       INT           NULL,       -- references Department row that has SubDepartment set
    DesignationNo         INT           NOT NULL,
    DivisionNo            INT           NULL,
    GradeNo               INT           NULL,
    ReportingManagerNo    INT           NULL,       -- self-ref FK

    -- Status
    EmployeeStatus        VARCHAR(10)   NOT NULL CONSTRAINT DF_Emp_Status DEFAULT 'Active',
    ExcludeFromPayroll    BIT           NOT NULL CONSTRAINT DF_Emp_ExclPayroll DEFAULT 0,
    DefaultDependents     TINYINT       NOT NULL CONSTRAINT DF_Emp_Dep DEFAULT 0,
    AllowFamilyBenefits   BIT           NOT NULL CONSTRAINT DF_Emp_FB  DEFAULT 0,
    QRCode                NVARCHAR(500) NULL,       -- server-generated on INSERT
    PaymentType           VARCHAR(20)   NULL,

    -- Audit
    CreatedAt  DATETIME2(0) NOT NULL CONSTRAINT DF_Emp_CreatedAt DEFAULT GETDATE(),
    UpdatedAt  DATETIME2(0) NULL,
    CreatedBy  INT          NULL,

    CONSTRAINT UQ_Emp_Code      UNIQUE (EmployeeCode),
    CONSTRAINT CK_Emp_Status    CHECK (EmployeeStatus IN ('Active','On Leave','Inactive')),
    CONSTRAINT CK_Emp_DOB       CHECK (DateOfBirth < GETDATE()),   -- no future birth dates
    CONSTRAINT CK_Emp_PAN       CHECK (PANNumber LIKE '[A-Z][A-Z][A-Z][A-Z][A-Z][0-9][0-9][0-9][0-9][A-Z]'),
    CONSTRAINT CK_Emp_Aadhaar   CHECK (AadhaarEIDNumber LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]'),

    -- Foreign Keys
    CONSTRAINT FK_Emp_Gender    FOREIGN KEY (GenderNo)         REFERENCES dbo.Gender       (GenderNo),
