    UpdatedAt    DATETIME2(0)  NULL,
    CONSTRAINT CK_EmpAddr_Type  CHECK (AddressType IN ('Permanent','Local')),
    CONSTRAINT UQ_EmpAddr_Type  UNIQUE (EmployeeNo, AddressType),   -- one permanent + one local per employee
    CONSTRAINT FK_EmpAddr_Emp   FOREIGN KEY (EmployeeNo) REFERENCES dbo.Employee (EmployeeNo) ON DELETE CASCADE,
    CONSTRAINT FK_EmpAddr_City  FOREIGN KEY (CityNo)     REFERENCES dbo.City (CityNo),
