    EducationLevelNo   TINYINT       NULL,
    InstituteName      NVARCHAR(200) NOT NULL,
    BoardUniversity    NVARCHAR(200) NULL,
    PassingYear        SMALLINT      NOT NULL,   -- 4-digit; <= current year
