    CONSTRAINT CK_EmpEdu_Year  CHECK (PassingYear BETWEEN 1950 AND 2100),
    CONSTRAINT CK_EmpEdu_Pct   CHECK (Percentage IS NULL OR (Percentage >= 0 AND Percentage <= 100)),
    CONSTRAINT FK_EmpEdu_Emp   FOREIGN KEY (EmployeeNo)       REFERENCES dbo.Employee      (EmployeeNo) ON DELETE CASCADE,
    CONSTRAINT FK_EmpEdu_Qual  FOREIGN KEY (QualificationNo)  REFERENCES dbo.Qualification (QualificationNo),
    CONSTRAINT FK_EmpEdu_Lvl   FOREIGN KEY (EducationLevelNo) REFERENCES dbo.EducationLevel(EducationLevelNo)
);
