    IFSCCode       VARCHAR(11)   NOT NULL,   -- 4 alpha + '0' + 6 alnum
    AccountType    VARCHAR(10)   NOT NULL CONSTRAINT DF_EmpBank_AccType DEFAULT 'Saving',
    IsReadOnly     BIT           NOT NULL CONSTRAINT DF_EmpBank_RO DEFAULT 0,
    -- Set to 1 after Submit; cleared only via mobile change request
    IsActive       BIT           NOT NULL CONSTRAINT DF_EmpBank_Active DEFAULT 1,
    CreatedAt      DATETIME2(0)  NOT NULL CONSTRAINT DF_EmpBank_CA DEFAULT GETDATE(),
    UpdatedAt      DATETIME2(0)  NULL,
    CONSTRAINT CK_EmpBank_AccNo   CHECK (AccountNumber LIKE '%[0-9]%' AND LEN(AccountNumber) BETWEEN 9 AND 18),
    CONSTRAINT CK_EmpBank_IFSC    CHECK (IFSCCode LIKE '[A-Z][A-Z][A-Z][A-Z]0[A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9]'),
    CONSTRAINT CK_EmpBank_AccType CHECK (AccountType IN ('Saving','Current')),
    CONSTRAINT UQ_EmpBank_AccNo   UNIQUE (BankName, AccountNumber),
    CONSTRAINT FK_EmpBank_Emp     FOREIGN KEY (EmployeeNo) REFERENCES dbo.Employee (EmployeeNo) ON DELETE CASCADE
