-- ============================================================
-- SECTION 12 — DOCUMENTS   (one of the 5 required tables)
-- Covers all file uploads: identity docs, education certificates,
-- policy uploads, etc.  CategoryNo links to dbo.Categories.
-- ============================================================
IF OBJECT_ID('dbo.Documents','U') IS NOT NULL DROP TABLE dbo.Documents;
GO
CREATE TABLE dbo.Documents (
    DocumentNo     INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Documents PRIMARY KEY,
    DocumentGUID   UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Doc_GUID DEFAULT NEWID(),
    CategoryNo     INT           NOT NULL,   -- FK to dbo.Categories
    EmployeeNo     INT           NULL,       -- NULL for company-level docs (e.g. policy files)
    DocumentTitle  NVARCHAR(200) NOT NULL,
    DocumentCode   VARCHAR(50)   NULL,
    FileURL        NVARCHAR(1000) NOT NULL,  -- storage path or CDN URL
    FileType       VARCHAR(10)   NOT NULL,   -- PDF / JPG / PNG
    FileSizeKB     INT           NULL,       -- max 5120 KB enforced at app layer
    -- Document metadata
    IssuedBy       NVARCHAR(100) NULL,       -- e.g. UIDAI / CBSE / Bank name
    IssuedDate     DATE          NULL,
    ExpiryDate     DATE          NULL,
    ReferenceNumber NVARCHAR(100) NULL,      -- document reference / ID number
    -- Workflow
    VerificationStatus VARCHAR(20) NOT NULL CONSTRAINT DF_Doc_VerStatus DEFAULT 'Pending',
    -- Pending / Verified / Rejected
    VerifiedByID   INT           NULL,       -- FK to Users
    VerifiedAt     DATETIME2(0)  NULL,
    RejectionReason NVARCHAR(300) NULL,
    -- Audit
    UploadedByID   INT           NULL,
    IsActive       BIT           NOT NULL CONSTRAINT DF_Doc_Active DEFAULT 1,
    CreatedAt      DATETIME2(0)  NOT NULL CONSTRAINT DF_Doc_CreatedAt DEFAULT GETDATE(),
    UpdatedAt      DATETIME2(0)  NULL,
    CONSTRAINT UQ_Doc_GUID        UNIQUE (DocumentGUID),
    CONSTRAINT CK_Doc_FileType    CHECK (FileType IN ('PDF','JPG','PNG','JPEG')),
    CONSTRAINT CK_Doc_VerStatus   CHECK (VerificationStatus IN ('Pending','Verified','Rejected')),
    CONSTRAINT CK_Doc_FileSize    CHECK (FileSizeKB IS NULL OR FileSizeKB <= 5120),
    CONSTRAINT FK_Doc_Category    FOREIGN KEY (CategoryNo)   REFERENCES dbo.Categories (CategoryNo),
    CONSTRAINT FK_Doc_Employee    FOREIGN KEY (EmployeeNo)   REFERENCES dbo.Employee   (EmployeeNo),
    CONSTRAINT FK_Doc_VerifiedBy  FOREIGN KEY (VerifiedByID) REFERENCES dbo.Users      (UserNo),
    CONSTRAINT FK_Doc_UploadedBy  FOREIGN KEY (UploadedByID) REFERENCES dbo.Users      (UserNo)
);
GO
CREATE NONCLUSTERED INDEX IX_Doc_Employee   ON dbo.Documents (EmployeeNo)  WHERE EmployeeNo IS NOT NULL;
CREATE NONCLUSTERED INDEX IX_Doc_Category   ON dbo.Documents (CategoryNo);
CREATE NONCLUSTERED INDEX IX_Doc_VerStatus  ON dbo.Documents (VerificationStatus);
GO

-- ============================================================
-- SECTION 13 — AUDIT LOG   (one of the 5 required tables)
-- Placed in the [audit] schema.
-- Populated by DML triggers on major tables.
-- ============================================================
IF OBJECT_ID('audit.AuditLog','U') IS NOT NULL DROP TABLE audit.AuditLog;
GO
CREATE TABLE audit.AuditLog (
    AuditLogNo   BIGINT        NOT NULL IDENTITY(1,1) CONSTRAINT PK_AuditLog PRIMARY KEY,
    -- What changed
    SchemaName   NVARCHAR(50)  NOT NULL,
    TableName    NVARCHAR(100) NOT NULL,
    EntityID     NVARCHAR(50)  NOT NULL,   -- PK value of the changed row (stored as string for flexibility)
    Action       CHAR(1)       NOT NULL,   -- I=Insert  U=Update  D=Delete
    -- Before / after values (JSON for multi-column changes)
    OldValue     NVARCHAR(MAX) NULL,
    NewValue     NVARCHAR(MAX) NULL,
    -- Who and when
    ChangedByUserID INT        NULL,
    ChangedByUsername NVARCHAR(60) NULL,   -- denormalised — preserved even if user deleted
    ChangedAt    DATETIME2(3)  NOT NULL CONSTRAINT DF_AL_ChangedAt DEFAULT SYSDATETIME(),
    -- Network context
    IPAddress    VARCHAR(45)   NULL,
    SessionToken NVARCHAR(200) NULL,
    -- Application context
    AppModule    NVARCHAR(100) NULL,       -- e.g. 'Employee Onboarding' / 'Payroll' / 'Recruitment'
    ChangeReason NVARCHAR(500) NULL,
    CONSTRAINT CK_AL_Action CHECK (Action IN ('I','U','D'))
);
GO
-- Clustered index is on IDENTITY PK; add a covering index for common query patterns
CREATE NONCLUSTERED INDEX IX_AL_Table_Entity ON audit.AuditLog (TableName, EntityID, ChangedAt DESC);
CREATE NONCLUSTERED INDEX IX_AL_User_Date    ON audit.AuditLog (ChangedByUserID, ChangedAt DESC) WHERE ChangedByUserID IS NOT NULL;
GO

