CREATE TABLE dbo.LeaveType (
    LeaveTypeNo          INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_LeaveType PRIMARY KEY,
    LeaveName            NVARCHAR(60) NOT NULL,
    LeaveCode            VARCHAR(5)   NOT NULL,   -- CL SL EL ML PL
    Description          NVARCHAR(300) NULL,
    DaysAllowedPerYear   DECIMAL(5,1) NOT NULL CONSTRAINT DF_LT_Days DEFAULT 0,
    CarryForwardDays     DECIMAL(5,1) NOT NULL CONSTRAINT DF_LT_CF   DEFAULT 0,
    ApplicableGender     VARCHAR(6)   NOT NULL CONSTRAINT DF_LT_Gender DEFAULT 'Both',
    RequiresApproval     BIT          NOT NULL CONSTRAINT DF_LT_Approval DEFAULT 1,
    HRVerificationThresholdDays DECIMAL(5,1) NULL,  -- leaves > this trigger HR verification
    Status               TINYINT      NOT NULL CONSTRAINT DF_LT_Status DEFAULT 1,
    CreatedAt            DATETIME2(0) NOT NULL CONSTRAINT DF_LT_CA DEFAULT GETDATE(),
    CONSTRAINT UQ_LT_Code     UNIQUE (LeaveCode),
    CONSTRAINT CK_LT_Gender   CHECK (ApplicableGender IN ('Both','Male','Female')),
    CONSTRAINT CK_LT_Status   CHECK (Status IN (0,1)),
    CONSTRAINT CK_LT_Days     CHECK (DaysAllowedPerYear >= 0),
    CONSTRAINT CK_LT_CF       CHECK (CarryForwardDays >= 0 AND CarryForwardDays <= DaysAllowedPerYear)
);
GO

