IF OBJECT_ID('dbo.LeaveBalance','U') IS NOT NULL DROP TABLE dbo.LeaveBalance;
GO
CREATE TABLE dbo.LeaveBalance (
    LeaveBalanceNo INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_LeaveBalance PRIMARY KEY,
    EmployeeNo     INT          NOT NULL,
    LeaveTypeNo    INT          NOT NULL,
    FiscalYear     SMALLINT     NOT NULL,   -- e.g. 2026
    Entitled       DECIMAL(5,1) NOT NULL CONSTRAINT DF_LB_Entitled DEFAULT 0,
    Used           DECIMAL(5,1) NOT NULL CONSTRAINT DF_LB_Used     DEFAULT 0,
    CarriedForward DECIMAL(5,1) NOT NULL CONSTRAINT DF_LB_CF       DEFAULT 0,
    Encashed       DECIMAL(5,1) NOT NULL CONSTRAINT DF_LB_Enc      DEFAULT 0,
    Lapsed         DECIMAL(5,1) NOT NULL CONSTRAINT DF_LB_Lapsed   DEFAULT 0,
    CONSTRAINT UQ_LB_EmpTypYear  UNIQUE (EmployeeNo, LeaveTypeNo, FiscalYear),
    CONSTRAINT CK_LB_Used   CHECK (Used >= 0),
    CONSTRAINT FK_LB_Emp    FOREIGN KEY (EmployeeNo)  REFERENCES dbo.Employee  (EmployeeNo),
    CONSTRAINT FK_LB_Type   FOREIGN KEY (LeaveTypeNo) REFERENCES dbo.LeaveType (LeaveTypeNo)
);
