-- 14.03  LeaveApplication
IF OBJECT_ID('dbo.LeaveApplication','U') IS NOT NULL DROP TABLE dbo.LeaveApplication;
GO
CREATE TABLE dbo.LeaveApplication (
    LeaveAppNo           INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_LeaveApp PRIMARY KEY,
    EmployeeNo           INT          NOT NULL,
    LeaveTypeNo          INT          NOT NULL,
    FromDate             DATE         NOT NULL,
    ToDate               DATE         NOT NULL,
    Days                 DECIMAL(5,1) NOT NULL,   -- computed at app layer
    Reason               NVARCHAR(500) NULL,
    LeaveStatus          VARCHAR(10)  NOT NULL CONSTRAINT DF_LA_Status DEFAULT 'Pending',
    ApprovedByID         INT          NULL,
    ApprovalDate         DATETIME2(0) NULL,
    ManagerComment       NVARCHAR(500) NULL,   -- mandatory when Rejected
    NeedsHRVerification  BIT          NOT NULL CONSTRAINT DF_LA_HRV DEFAULT 0,
    HRVerifiedByID       INT          NULL,
    HRVerificationDate   DATETIME2(0) NULL,
    CreatedAt            DATETIME2(0) NOT NULL CONSTRAINT DF_LA_CA DEFAULT GETDATE(),
    UpdatedAt            DATETIME2(0) NULL,
    CONSTRAINT CK_LA_Status  CHECK (LeaveStatus IN ('Pending','Approved','Rejected','Cancelled')),
    CONSTRAINT CK_LA_Dates   CHECK (ToDate >= FromDate),
    CONSTRAINT CK_LA_Days    CHECK (Days > 0),
    CONSTRAINT CK_LA_Comment CHECK (LeaveStatus <> 'Rejected' OR ManagerComment IS NOT NULL),
    CONSTRAINT FK_LA_Emp        FOREIGN KEY (EmployeeNo)       REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_LA_Type       FOREIGN KEY (LeaveTypeNo)      REFERENCES dbo.LeaveType(LeaveTypeNo),
    CONSTRAINT FK_LA_Approver   FOREIGN KEY (ApprovedByID)     REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_LA_HRVerifier FOREIGN KEY (HRVerifiedByID)   REFERENCES dbo.Employee (EmployeeNo)
);
GO
CREATE NONCLUSTERED INDEX IX_LA_Emp    ON dbo.LeaveApplication (EmployeeNo, FromDate DESC);
CREATE NONCLUSTERED INDEX IX_LA_Status ON dbo.LeaveApplication (LeaveStatus, FromDate DESC);
