    ApprovalDate  DATETIME2(0) NULL,
    ManagerRemark NVARCHAR(300) NULL,
    CreatedAt     DATETIME2(0) NOT NULL CONSTRAINT DF_MP_CA DEFAULT GETDATE(),
    CONSTRAINT CK_MP_Type   CHECK (PunchType IN ('Check In','Check Out')),
    CONSTRAINT CK_MP_Status CHECK (RequestStatus IN ('Pending','Approved','Rejected')),
    CONSTRAINT FK_MP_Emp      FOREIGN KEY (EmployeeNo)   REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_MP_Approver FOREIGN KEY (ApprovedByID) REFERENCES dbo.Employee (EmployeeNo)
);
GO

-- 15.05  GatePass
IF OBJECT_ID('dbo.GatePass','U') IS NOT NULL DROP TABLE dbo.GatePass;
GO
CREATE TABLE dbo.GatePass (
    GatePassNo    INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_GatePass PRIMARY KEY,
    EmployeeNo    INT          NOT NULL,
    PassType      VARCHAR(15)  NOT NULL,   -- 'Early Exit' | 'Late Entry' | 'Both'
    PassCategory  VARCHAR(20)  NOT NULL,   -- 'Single Day Pass' | 'Multi-Day Pass' | 'Hourly Pass'
    Purpose       NVARCHAR(300) NULL,
    RequestedDate DATE         NOT NULL,
    PassTime      TIME(0)      NULL,
    GatePassStatus VARCHAR(10) NOT NULL CONSTRAINT DF_GP_Status DEFAULT 'Pending',
    ApprovedByID  INT          NULL,
    ApprovalDate  DATETIME2(0) NULL,
    CreatedAt     DATETIME2(0) NOT NULL CONSTRAINT DF_GP_CA DEFAULT GETDATE(),
    CONSTRAINT CK_GP_Type   CHECK (PassType     IN ('Early Exit','Late Entry','Both')),
    CONSTRAINT CK_GP_Cat    CHECK (PassCategory IN ('Single Day Pass','Multi-Day Pass','Hourly Pass')),
    CONSTRAINT CK_GP_Status CHECK (GatePassStatus IN ('Pending','Approved','Rejected','Cancelled')),
    CONSTRAINT FK_GP_Emp      FOREIGN KEY (EmployeeNo)   REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_GP_Approver FOREIGN KEY (ApprovedByID) REFERENCES dbo.Employee (EmployeeNo)
);
GO

-- 15.06  OnDutyRequest
IF OBJECT_ID('dbo.OnDutyRequest','U') IS NOT NULL DROP TABLE dbo.OnDutyRequest;
GO
CREATE TABLE dbo.OnDutyRequest (
    OnDutyNo      INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_OnDuty PRIMARY KEY,
    EmployeeNo    INT          NOT NULL,
    OnDutyPurpose NVARCHAR(300) NOT NULL,
    FromDate      DATE         NOT NULL,
    ToDate        DATE         NOT NULL,
    Location      NVARCHAR(200) NULL,
    Reason        NVARCHAR(500) NULL,
    RequestStatus VARCHAR(10)  NOT NULL CONSTRAINT DF_OD_Status DEFAULT 'Pending',
    ApprovedByID  INT          NULL,
    ApprovalDate  DATETIME2(0) NULL,
    ManagerRemark NVARCHAR(300) NULL,
    CreatedAt     DATETIME2(0) NOT NULL CONSTRAINT DF_OD_CA DEFAULT GETDATE(),
    CONSTRAINT CK_OD_Dates  CHECK (ToDate >= FromDate),
    CONSTRAINT CK_OD_Status CHECK (RequestStatus IN ('Pending','Approved','Rejected','Cancelled')),
    CONSTRAINT FK_OD_Emp      FOREIGN KEY (EmployeeNo)   REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_OD_Approver FOREIGN KEY (ApprovedByID) REFERENCES dbo.Employee (EmployeeNo)
);
GO

-- 15.07  Holiday
IF OBJECT_ID('dbo.Holiday','U') IS NOT NULL DROP TABLE dbo.Holiday;
GO
CREATE TABLE dbo.Holiday (
    HolidayNo    INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Holiday PRIMARY KEY,
    HolidayName  NVARCHAR(100) NOT NULL,
    HolidayDate  DATE         NOT NULL,
    HolidayType  VARCHAR(15)  NOT NULL,   -- National / Regional / Religious / Company
    Description  NVARCHAR(300) NULL,
    Status       TINYINT      NOT NULL CONSTRAINT DF_Hol_Status DEFAULT 1,
    CONSTRAINT UQ_Holiday_Date    UNIQUE (HolidayDate),
    CONSTRAINT CK_Holiday_Type    CHECK (HolidayType IN ('National','Regional','Religious','Company')),
    CONSTRAINT CK_Holiday_Status  CHECK (Status IN (0,1))
);
GO

-- ============================================================
-- SECTION 16 — PAYROLL
-- ============================================================

-- 16.01  AllowanceDeduction  (pay components master)
IF OBJECT_ID('dbo.AllowanceDeduction','U') IS NOT NULL DROP TABLE dbo.AllowanceDeduction;
GO
CREATE TABLE dbo.AllowanceDeduction (
    AllowanceDeductionNo         INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_AD PRIMARY KEY,
    ADName       NVARCHAR(80) NOT NULL,
    AccountType  CHAR(1)      NOT NULL,   -- A=Allowance  D=Deduction
    SubType      NVARCHAR(40) NULL,
    RoundingMode VARCHAR(25)  NOT NULL CONSTRAINT DF_AD_Rounding DEFAULT 'Normal Rounding',
    ApplyMaxLimit BIT         NOT NULL CONSTRAINT DF_AD_MaxLim DEFAULT 0,
    ForPresentDays BIT        NOT NULL CONSTRAINT DF_AD_PD     DEFAULT 0,
    Status       TINYINT      NOT NULL CONSTRAINT DF_AD_Status DEFAULT 1,
    DisplayOrder SMALLINT     NOT NULL CONSTRAINT DF_AD_Ord    DEFAULT 99,
    CONSTRAINT UQ_AD_Name     UNIQUE (ADName),
    CONSTRAINT CK_AD_AccType  CHECK (AccountType IN ('A','D')),
    CONSTRAINT CK_AD_Rounding CHECK (RoundingMode IN ('Normal Rounding','Round to Next Number','Floor','Ceiling')),
    CONSTRAINT CK_AD_Status   CHECK (Status IN (0,1))
);
GO

-- 16.02  SalaryStructure  (per-employee, per-grade)
IF OBJECT_ID('dbo.SalaryStructure','U') IS NOT NULL DROP TABLE dbo.SalaryStructure;
GO
CREATE TABLE dbo.SalaryStructure (
    SalaryStructureNo               INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_SalStruct PRIMARY KEY,
    EmployeeNo                      INT           NOT NULL,
    GradeNo                         INT           NULL,
    BasicSalary                     DECIMAL(12,2) NOT NULL,
    ApplyAllowancesOnMaxLimit       BIT           NOT NULL CONSTRAINT DF_SS_MaxLim DEFAULT 0,
    ApplyEPFEmployerShareOn         VARCHAR(15)   NOT NULL CONSTRAINT DF_SS_EPFOn DEFAULT 'Actual',
    EPFOnBasicOnly                  BIT           NOT NULL CONSTRAINT DF_SS_EPFBasic DEFAULT 0,
    ExcludeFromPayrollProcessing    BIT           NOT NULL CONSTRAINT DF_SS_ExclPay DEFAULT 0,
    EffectiveFrom                   DATE          NOT NULL,
    EffectiveTo                     DATE          NULL,
    Status                          TINYINT       NOT NULL CONSTRAINT DF_SS_Status DEFAULT 1,
    CreatedAt                       DATETIME2(0)  NOT NULL CONSTRAINT DF_SS_CA DEFAULT GETDATE(),
    CONSTRAINT CK_SS_EPFOn   CHECK (ApplyEPFEmployerShareOn IN ('Max Limit','Actual')),
    CONSTRAINT CK_SS_Basic   CHECK (BasicSalary > 0),
    CONSTRAINT CK_SS_Status  CHECK (Status IN (0,1)),
    CONSTRAINT FK_SS_Emp     FOREIGN KEY (EmployeeNo) REFERENCES dbo.Employee (EmployeeNo),
    CONSTRAINT FK_SS_Grade   FOREIGN KEY (GradeNo)    REFERENCES dbo.Grade    (GradeNo)
);
GO
CREATE NONCLUSTERED INDEX IX_SS_Emp ON dbo.SalaryStructure (EmployeeNo, EffectiveFrom DESC);
GO

-- 16.03  SalaryStructureLine  (one row per allowance/deduction in a structure)
IF OBJECT_ID('dbo.SalaryStructureLine','U') IS NOT NULL DROP TABLE dbo.SalaryStructureLine;
GO
CREATE TABLE dbo.SalaryStructureLine (
    SalaryStructureLineNo             INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_SSLine PRIMARY KEY,
    SalaryStructureNo  INT           NOT NULL,
    AllowanceDeductionNo               INT           NOT NULL,   -- FK AllowanceDeduction
    CalculationOn      VARCHAR(10)   NOT NULL,   -- 'Salary' | 'Amount'
    Amount             DECIMAL(12,2) NOT NULL CONSTRAINT DF_SSL_Amt DEFAULT 0,
    OnBasicOrGross     VARCHAR(10)   NULL,       -- 'Basic' | 'Gross' (when CalculationOn = 'Salary')
    IsPercentage       BIT           NOT NULL CONSTRAINT DF_SSL_Pct DEFAULT 0,
    VaryOnDays         BIT           NOT NULL CONSTRAINT DF_SSL_VD  DEFAULT 0,
    CONSTRAINT CK_SSL_CalcOn CHECK (CalculationOn IN ('Salary','Amount')),
    CONSTRAINT FK_SSL_Struct  FOREIGN KEY (SalaryStructureNo) REFERENCES dbo.SalaryStructure  (SalaryStructureNo) ON DELETE CASCADE,
    CONSTRAINT FK_SSL_AD      FOREIGN KEY (AllowanceDeductionNo)              REFERENCES dbo.AllowanceDeduction(AllowanceDeductionNo)
);
GO

-- 16.04  SalaryGeneration  (monthly payroll run)
IF OBJECT_ID('dbo.SalaryGeneration','U') IS NOT NULL DROP TABLE dbo.SalaryGeneration;
GO
CREATE TABLE dbo.SalaryGeneration (
    SalaryGenNo   INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_SalGen PRIMARY KEY,
    PayMonth      TINYINT      NOT NULL,   -- 1–12
    PayYear       SMALLINT     NOT NULL,
    SalaryType    NVARCHAR(40) NOT NULL CONSTRAINT DF_SG_Type DEFAULT 'Monthly Salary',
    DivisionNo    INT          NULL,
    DepartmentNo  INT          NULL,
    GeneratedAt   DATETIME2(0) NOT NULL CONSTRAINT DF_SG_GA DEFAULT GETDATE(),
    GeneratedByID INT          NULL,
    ApprovedAt    DATETIME2(0) NULL,
    ApprovedByID  INT          NULL,
    GenStatus     VARCHAR(15)  NOT NULL CONSTRAINT DF_SG_Status DEFAULT 'Generated',
    CONSTRAINT CK_SG_Month  CHECK (PayMonth BETWEEN 1 AND 12),
    CONSTRAINT CK_SG_Status CHECK (GenStatus IN ('Generated','Pending','Approved','Transferred','Cancelled')),
    CONSTRAINT FK_SG_Div    FOREIGN KEY (DivisionNo)    REFERENCES dbo.Division   (DivisionNo),
    CONSTRAINT FK_SG_Dept   FOREIGN KEY (DepartmentNo)  REFERENCES dbo.Department (DepartmentNo),
    CONSTRAINT FK_SG_GenBy  FOREIGN KEY (GeneratedByID) REFERENCES dbo.Users      (UserNo),
    CONSTRAINT FK_SG_AppBy  FOREIGN KEY (ApprovedByID)  REFERENCES dbo.Users      (UserNo)
);
GO

-- 16.05  PayslipLine  (individual earnings / deductions per payroll run per employee)
IF OBJECT_ID('dbo.PayslipLine','U') IS NOT NULL DROP TABLE dbo.PayslipLine;
GO
CREATE TABLE dbo.PayslipLine (
    PayslipLineNo   BIGINT        NOT NULL IDENTITY(1,1) CONSTRAINT PK_PayslipLine PRIMARY KEY,
    SalaryGenNo     INT           NOT NULL,
    EmployeeNo      INT           NOT NULL,
    AllowanceDeductionNo            INT           NOT NULL,
    Amount          DECIMAL(12,2) NOT NULL CONSTRAINT DF_PL_Amt DEFAULT 0,
    ComputedDays    DECIMAL(5,1)  NULL,
    LineStatus      VARCHAR(10)   NOT NULL CONSTRAINT DF_PL_Status DEFAULT 'Generated',
    -- Generated / Pending (manual override needed) / Approved / Transferred
    Remarks         NVARCHAR(200) NULL,
    CONSTRAINT CK_PL_Status  CHECK (LineStatus IN ('Generated','Pending','Approved','Transferred')),
    CONSTRAINT FK_PL_Gen     FOREIGN KEY (SalaryGenNo) REFERENCES dbo.SalaryGeneration   (SalaryGenNo),
    CONSTRAINT FK_PL_Emp     FOREIGN KEY (EmployeeNo)  REFERENCES dbo.Employee           (EmployeeNo),
    CONSTRAINT FK_PL_AD      FOREIGN KEY (AllowanceDeductionNo)        REFERENCES dbo.AllowanceDeduction (AllowanceDeductionNo)
);
GO
CREATE NONCLUSTERED INDEX IX_PL_GenEmp ON dbo.PayslipLine (SalaryGenNo, EmployeeNo);
GO

-- ============================================================
-- SECTION 17 — LOAN & ADVANCE
-- ============================================================

-- 17.01  LoanAdvanceVoucher
IF OBJECT_ID('dbo.LoanAdvanceVoucher','U') IS NOT NULL DROP TABLE dbo.LoanAdvanceVoucher;
GO
CREATE TABLE dbo.LoanAdvanceVoucher (
    VoucherNo            INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Voucher PRIMARY KEY,
    ReferenceNo          VARCHAR(20)   NOT NULL,   -- auto-generated e.g. G37-G37-9
    ApplicationDate      DATE          NOT NULL CONSTRAINT DF_Vch_AppDate DEFAULT CAST(GETDATE() AS DATE),
    EmployeeNo           INT           NOT NULL,
    AppliedFor           VARCHAR(10)   NOT NULL,   -- 'Loan' | 'Advance'
    AmountAppliedForINR  DECIMAL(12,2) NOT NULL,
    PurposeJSON          NVARCHAR(500) NULL,       -- JSON array of selected purpose chips
    MonthlyInstalment    INT           NULL,
    TotalInstalmentAmount DECIMAL(12,2) NULL,
    VoucherStatus        VARCHAR(15)   NOT NULL CONSTRAINT DF_Vch_Status DEFAULT 'Pending',
    OutstandingAmount    DECIMAL(12,2) NULL,
    CreatedAt            DATETIME2(0)  NOT NULL CONSTRAINT DF_Vch_CA DEFAULT GETDATE(),
    UpdatedAt            DATETIME2(0)  NULL,
    CONSTRAINT UQ_Vch_Ref      UNIQUE (ReferenceNo),
    CONSTRAINT CK_Vch_Type     CHECK (AppliedFor IN ('Loan','Advance')),
    CONSTRAINT CK_Vch_Amt      CHECK (AmountAppliedForINR > 0),
    CONSTRAINT CK_Vch_Status   CHECK (VoucherStatus IN ('Pending','Approved','In Progress','Completed','Rejected')),
    CONSTRAINT FK_Vch_Emp      FOREIGN KEY (EmployeeNo) REFERENCES dbo.Employee (EmployeeNo)
);
GO

-- 17.02  LoanSuretyPerson
IF OBJECT_ID('dbo.LoanSuretyPerson','U') IS NOT NULL DROP TABLE dbo.LoanSuretyPerson;
GO
CREATE TABLE dbo.LoanSuretyPerson (
    SuretyNo    INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Surety PRIMARY KEY,
    VoucherNo   INT          NOT NULL,
    SuretyName  NVARCHAR(100) NOT NULL,
    Relation    NVARCHAR(50) NULL,
    PhoneNumber VARCHAR(15)  NULL,
    Address     NVARCHAR(300) NULL,
    IsPrimary   BIT          NOT NULL CONSTRAINT DF_Sur_Primary DEFAULT 1,
    CONSTRAINT FK_Sur_Vch FOREIGN KEY (VoucherNo) REFERENCES dbo.LoanAdvanceVoucher (VoucherNo) ON DELETE CASCADE
);
GO

-- 17.03  LoanApprovalAction
IF OBJECT_ID('dbo.LoanApprovalAction','U') IS NOT NULL DROP TABLE dbo.LoanApprovalAction;
GO
CREATE TABLE dbo.LoanApprovalAction (
    ApprovalActionNo    INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_LoanApproval PRIMARY KEY,
    VoucherNo           INT          NOT NULL,
    ApprovalLevel       TINYINT      NOT NULL,   -- 1=HR Manager  2=Finance Head  3=Director
    ApproverID          INT          NOT NULL,   -- FK to Users
    Decision            VARCHAR(20)  NOT NULL,
    RemarksAndConditions NVARCHAR(500) NULL,     -- mandatory on Reject
    ActionTimestamp     DATETIME2(0) NOT NULL CONSTRAINT DF_LA2_TS DEFAULT GETDATE(),
    CONSTRAINT CK_LA2_Level    CHECK (ApprovalLevel BETWEEN 1 AND 3),
    CONSTRAINT CK_LA2_Decision CHECK (Decision IN ('Approve','Reject','Forward','Need More Info')),
    CONSTRAINT CK_LA2_Remark   CHECK (Decision <> 'Reject' OR RemarksAndConditions IS NOT NULL),
    CONSTRAINT FK_LA2_Vch      FOREIGN KEY (VoucherNo)  REFERENCES dbo.LoanAdvanceVoucher (VoucherNo),
    CONSTRAINT FK_LA2_Approver FOREIGN KEY (ApproverID) REFERENCES dbo.Users              (UserNo)
);
GO

-- 17.04  LoanClearanceRecord
IF OBJECT_ID('dbo.LoanClearanceRecord','U') IS NOT NULL DROP TABLE dbo.LoanClearanceRecord;
GO
CREATE TABLE dbo.LoanClearanceRecord (
    ClearanceNo      INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_LoanClear PRIMARY KEY,
    VoucherNo        INT           NOT NULL,
    AmountPaidINR    DECIMAL(12,2) NOT NULL,
    PaymentDate      DATE          NOT NULL,
    PaymentMethod    VARCHAR(20)   NOT NULL,   -- Cash / Cheque / Bank Transfer / Salary Adjustment
    ReferenceChequeNo VARCHAR(50)  NULL,       -- mandatory for Cheque / Bank Transfer
    RemarksAndNotes  NVARCHAR(500) NULL,
    RecordedByID     INT           NULL,
    RecordedAt       DATETIME2(0)  NOT NULL CONSTRAINT DF_LC_CA DEFAULT GETDATE(),
    CONSTRAINT CK_LC_Amt     CHECK (AmountPaidINR > 0),
    CONSTRAINT CK_LC_Method  CHECK (PaymentMethod IN ('Cash','Cheque','Bank Transfer','Salary Adjustment')),
    CONSTRAINT CK_LC_CheqRef CHECK (PaymentMethod NOT IN ('Cheque','Bank Transfer') OR ReferenceChequeNo IS NOT NULL),
    CONSTRAINT FK_LC_Vch     FOREIGN KEY (VoucherNo)    REFERENCES dbo.LoanAdvanceVoucher (VoucherNo),
    CONSTRAINT FK_LC_Rec     FOREIGN KEY (RecordedByID) REFERENCES dbo.Users              (UserNo)
);
GO

-- ============================================================
-- SECTION 18 — RECRUITMENT
-- ============================================================

-- 18.01  JobTitle  (recruiters can create new ones inline)
IF OBJECT_ID('dbo.JobTitle','U') IS NOT NULL DROP TABLE dbo.JobTitle;
GO
CREATE TABLE dbo.JobTitle (
    JobTitleNo   INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_JobTitle PRIMARY KEY,
    TitleName    NVARCHAR(100) NOT NULL,
    Status       TINYINT      NOT NULL CONSTRAINT DF_JT_Status DEFAULT 1,
    CreatedByID  INT          NULL,
    CreatedAt    DATETIME2(0) NOT NULL CONSTRAINT DF_JT_CA DEFAULT GETDATE(),
    CONSTRAINT UQ_JT_Name   UNIQUE (TitleName),
    CONSTRAINT CK_JT_Status CHECK (Status IN (0,1))
);
GO

-- 18.02  Job / JobOpportunity
IF OBJECT_ID('dbo.Job','U') IS NOT NULL DROP TABLE dbo.Job;
GO
CREATE TABLE dbo.Job (
    JobNo                   INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Job PRIMARY KEY,
    JobTitleNo              INT           NOT NULL,
    DepartmentNo            INT           NULL,
    Location                NVARCHAR(200) NULL,
    JobType                 NVARCHAR(40)  NULL,   -- Full Time / Part Time / Contract / Internship
    ExperienceRequiredYears DECIMAL(4,1)  NULL,
    SalaryRangeMin          DECIMAL(12,2) NULL,
    SalaryRangeMax          DECIMAL(12,2) NULL,
    JobDescription          NVARCHAR(MAX) NULL,
    KeyResponsibilities     NVARCHAR(MAX) NULL,
    RequiredQualifications  NVARCHAR(MAX) NULL,
    Skills                  NVARCHAR(MAX) NULL,   -- comma-separated pills
    PostedDate              DATE          NULL,
    ExpiryDate              DATE          NULL,
    JobStatus               VARCHAR(15)   NOT NULL CONSTRAINT DF_Job_Status DEFAULT 'Draft',
    CreatedByID             INT           NULL,
    CreatedAt               DATETIME2(0)  NOT NULL CONSTRAINT DF_Job_CA DEFAULT GETDATE(),
    UpdatedAt               DATETIME2(0)  NULL,
    CONSTRAINT CK_Job_Status  CHECK (JobStatus IN ('Draft','Active','Inactive','Approved','Expired')),
    CONSTRAINT CK_Job_Sal     CHECK (SalaryRangeMax IS NULL OR SalaryRangeMax >= SalaryRangeMin),
    CONSTRAINT FK_Job_Title   FOREIGN KEY (JobTitleNo)   REFERENCES dbo.JobTitle   (JobTitleNo),
    CONSTRAINT FK_Job_Dept    FOREIGN KEY (DepartmentNo) REFERENCES dbo.Department (DepartmentNo),
    CONSTRAINT FK_Job_Creator FOREIGN KEY (CreatedByID)  REFERENCES dbo.Users      (UserNo)
);
GO
CREATE NONCLUSTERED INDEX IX_Job_Status ON dbo.Job (JobStatus, PostedDate DESC);
GO

-- 18.03  Applicant / Candidate
IF OBJECT_ID('dbo.Applicant','U') IS NOT NULL DROP TABLE dbo.Applicant;
GO
CREATE TABLE dbo.Applicant (
    ApplicantNo      INT           NOT NULL IDENTITY(1,1) CONSTRAINT PK_Applicant PRIMARY KEY,
    JobNo            INT           NOT NULL,
    FullName         NVARCHAR(100) NOT NULL,
    EmailAddress     NVARCHAR(150) NOT NULL,
    PhoneNumber      VARCHAR(15)   NULL,
    ExperienceYears  DECIMAL(4,1)  NULL,
    CoverLetter      NVARCHAR(MAX) NULL,
    ApplicantStatus  VARCHAR(20)   NOT NULL CONSTRAINT DF_App_Status DEFAULT 'New',
    ReadStatus       VARCHAR(10)   NOT NULL CONSTRAINT DF_App_Read   DEFAULT 'Unread',
    StatusRemarks    NVARCHAR(300) NULL,
    AppliedAt        DATETIME2(0)  NOT NULL CONSTRAINT DF_App_AppliedAt DEFAULT GETDATE(),
    UpdatedAt        DATETIME2(0)  NULL,
    CONSTRAINT CK_App_Status CHECK (ApplicantStatus IN ('New','Pending Review','Shortlisted','Rejected','Stall','Invited','Past Interview','Offer Accepted')),
    CONSTRAINT CK_App_Read   CHECK (ReadStatus IN ('Read','Unread')),
    CONSTRAINT FK_App_Job    FOREIGN KEY (JobNo) REFERENCES dbo.Job (JobNo)
);
GO
CREATE NONCLUSTERED INDEX IX_App_Job    ON dbo.Applicant (JobNo, ApplicantStatus);
CREATE NONCLUSTERED INDEX IX_App_Status ON dbo.Applicant (ApplicantStatus);
GO

-- 18.04  ShortlistRecord
IF OBJECT_ID('dbo.ShortlistRecord','U') IS NOT NULL DROP TABLE dbo.ShortlistRecord;
GO
CREATE TABLE dbo.ShortlistRecord (
    ShortlistNo         INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Shortlist PRIMARY KEY,
    ApplicantNo         INT          NOT NULL,
    ShortlistedByID     INT          NOT NULL,
    ShortlistDate       DATETIME2(0) NOT NULL CONSTRAINT DF_SR_Date DEFAULT GETDATE(),
    EvaluationNotes     NVARCHAR(MAX) NULL,
    NextInterviewRound  NVARCHAR(60) NULL,   -- e.g. "Round 1 Screening"
    ScheduledDate       DATE         NULL,
    ScheduledTime       TIME(0)      NULL,
    NotificationMethod  VARCHAR(10)  NULL,   -- Email / SMS / Both
    AssignedHRID        INT          NULL,
    CONSTRAINT CK_SR_NotiMethod CHECK (NotificationMethod IS NULL OR NotificationMethod IN ('Email','SMS','Both')),
    CONSTRAINT FK_SR_Applicant  FOREIGN KEY (ApplicantNo)    REFERENCES dbo.Applicant (ApplicantNo),
    CONSTRAINT FK_SR_ShortBy    FOREIGN KEY (ShortlistedByID) REFERENCES dbo.Users    (UserNo),
    CONSTRAINT FK_SR_HR         FOREIGN KEY (AssignedHRID)    REFERENCES dbo.Users    (UserNo)
);
GO

-- 18.05  RejectionRecord
IF OBJECT_ID('dbo.RejectionRecord','U') IS NOT NULL DROP TABLE dbo.RejectionRecord;
GO
CREATE TABLE dbo.RejectionRecord (
    RejectionNo              INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Rejection PRIMARY KEY,
    ApplicantNo              INT          NOT NULL,
    PrimaryRejectionReason   NVARCHAR(60) NOT NULL,
    OtherReason              NVARCHAR(300) NULL,
    DetailedFeedback         NVARCHAR(MAX) NOT NULL,
    Strengths                NVARCHAR(500) NULL,
    SuggestionForImprovement NVARCHAR(500) NULL,
    RejectionDate            DATETIME2(0) NOT NULL CONSTRAINT DF_RR_Date DEFAULT GETDATE(),
    NotificationMethod       VARCHAR(10)  NULL,
    PhoneNumber              VARCHAR(15)  NULL,
    RejectedByID             INT          NOT NULL,
    InternalRemarks          NVARCHAR(500) NULL,
    ConsiderForFuture        BIT          NOT NULL CONSTRAINT DF_RR_CFF DEFAULT 0,
    AddToTalentPool          BIT          NOT NULL CONSTRAINT DF_RR_ATP DEFAULT 0,
    ReasonForFurtherConsideration NVARCHAR(500) NULL,
    CONSTRAINT CK_RR_Reason  CHECK (PrimaryRejectionReason IN ('Poor Interview Performance','Insufficient Experience','Qualification Mismatch','Salary Expectation','Other')),
    CONSTRAINT CK_RR_Other   CHECK (PrimaryRejectionReason <> 'Other' OR OtherReason IS NOT NULL),
    CONSTRAINT FK_RR_App     FOREIGN KEY (ApplicantNo)  REFERENCES dbo.Applicant (ApplicantNo),
    CONSTRAINT FK_RR_RejBy   FOREIGN KEY (RejectedByID) REFERENCES dbo.Users     (UserNo)
);
GO

-- 18.06  StallRecord
IF OBJECT_ID('dbo.StallRecord','U') IS NOT NULL DROP TABLE dbo.StallRecord;
GO
CREATE TABLE dbo.StallRecord (
    StallNo          INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_Stall PRIMARY KEY,
    ApplicantNo      INT          NOT NULL,
    PreviousStatus   VARCHAR(20)  NOT NULL,
    StallRemarks     NVARCHAR(500) NOT NULL,
    StalledByID      INT          NOT NULL,
    StallDateTime    DATETIME2(0) NOT NULL CONSTRAINT DF_Stall_DT DEFAULT GETDATE(),
    Rating           TINYINT      NOT NULL,   -- 1–5
    InterviewNotes   NVARCHAR(MAX) NULL,
    StrengthsAndSkills NVARCHAR(500) NULL,
    AreasForImprovement NVARCHAR(500) NULL,
    CONSTRAINT CK_Stall_Rating CHECK (Rating BETWEEN 1 AND 5),
    CONSTRAINT FK_Stall_App    FOREIGN KEY (ApplicantNo) REFERENCES dbo.Applicant (ApplicantNo),
    CONSTRAINT FK_Stall_By     FOREIGN KEY (StalledByID) REFERENCES dbo.Users     (UserNo)
);
GO

-- 18.07  InterviewSchedule
IF OBJECT_ID('dbo.InterviewSchedule','U') IS NOT NULL DROP TABLE dbo.InterviewSchedule;
GO
CREATE TABLE dbo.InterviewSchedule (
    InterviewScheduleNo  INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_IntSch PRIMARY KEY,
    ApplicantNo          INT          NOT NULL,
    JobNo                INT          NOT NULL,
    InterviewRound       NVARCHAR(60) NOT NULL,   -- "Round 1 Screening" …
    ScheduledDate        DATE         NOT NULL,
    ScheduledTime        TIME(0)      NOT NULL,
    InterviewerID        INT          NULL,
    Location             NVARCHAR(200) NULL,
    MeetingLink          NVARCHAR(500) NULL,
    InvitationMessage    NVARCHAR(MAX) NULL,
    NotificationMethod   VARCHAR(10)  NULL,
    InterviewStatus      VARCHAR(20)  NOT NULL CONSTRAINT DF_IS_Status DEFAULT 'Scheduled',
    ConfirmationStatus   VARCHAR(50)  NULL,
    CreatedAt            DATETIME2(0) NOT NULL CONSTRAINT DF_IS_CA DEFAULT GETDATE(),
    UpdatedAt            DATETIME2(0) NULL,
    CONSTRAINT CK_IS_Status CHECK (InterviewStatus IN ('Scheduled','Confirmed','Rescheduled','Cancelled','Past Interview')),
    CONSTRAINT FK_IS_App      FOREIGN KEY (ApplicantNo)   REFERENCES dbo.Applicant (ApplicantNo),
    CONSTRAINT FK_IS_Job      FOREIGN KEY (JobNo)         REFERENCES dbo.Job       (JobNo),
    CONSTRAINT FK_IS_Iview    FOREIGN KEY (InterviewerID) REFERENCES dbo.Users     (UserNo)
);
GO
CREATE NONCLUSTERED INDEX IX_IS_App ON dbo.InterviewSchedule (ApplicantNo, ScheduledDate DESC);
GO

-- 18.08  InterviewRoundHistory
IF OBJECT_ID('dbo.InterviewRoundHistory','U') IS NOT NULL DROP TABLE dbo.InterviewRoundHistory;
GO
CREATE TABLE dbo.InterviewRoundHistory (
    RoundHistNo         INT          NOT NULL IDENTITY(1,1) CONSTRAINT PK_IRH PRIMARY KEY,
    InterviewScheduleNo INT          NOT NULL,
    RoundDate           DATE         NOT NULL,
    Outcome             VARCHAR(10)  NOT NULL,   -- 'Passed' | 'Failed'
