-- ------------------------------------------------------------
-- 22.01  Generic CreatedAt / UpdatedAt trigger factory
-- Rather than repeating the pattern, one trigger per table.
-- ------------------------------------------------------------

-- dbo.Employee — timestamps
IF OBJECT_ID('dbo.TR_Employee_Timestamps','TR') IS NOT NULL DROP TRIGGER dbo.TR_Employee_Timestamps;
GO
CREATE TRIGGER dbo.TR_Employee_Timestamps
ON dbo.Employee
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS (SELECT 1 FROM inserted)
    BEGIN
        -- On INSERT CreatedAt is set by DEFAULT; on UPDATE only UpdatedAt changes.
        UPDATE e
        SET    e.UpdatedAt = GETDATE()
        FROM   dbo.Employee e
        INNER JOIN inserted i ON e.EmployeeNo = i.EmployeeNo;
    END
END;
GO

