-- ------------------------------------------------------------
-- 22.02  AUDIT TRIGGER — dbo.Employee
-- Captures INSERT / UPDATE / DELETE into audit.AuditLog.
-- OldValue / NewValue stored as JSON-like key=value strings
-- (SQL Server 2016+ supports FOR JSON; simpler concat used here
--  for broad compatibility; switch to FOR JSON PATH in 2016+).
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.TR_Employee_Audit','TR') IS NOT NULL DROP TRIGGER dbo.TR_Employee_Audit;
GO
CREATE TRIGGER dbo.TR_Employee_Audit
ON dbo.Employee
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Action CHAR(1);

    IF EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted)
        SET @Action = 'U';
    ELSE IF EXISTS(SELECT 1 FROM inserted)
        SET @Action = 'I';
    ELSE
        SET @Action = 'D';

    -- For INSERT: OldValue = NULL, NewValue = inserted row summary
    -- For DELETE: OldValue = deleted row summary, NewValue = NULL
    -- For UPDATE: both populated

    IF @Action = 'I'
    BEGIN
        INSERT INTO audit.AuditLog (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Employee',
            CAST(i.EmployeeNo AS NVARCHAR(50)),
            'I',
            NULL,
            N'EmployeeCode=' + ISNULL(i.EmployeeCode,'') +
            N'; Name=' + ISNULL(i.FirstName,'') + N' ' + ISNULL(i.LastName,'') +
            N'; Status=' + ISNULL(i.EmployeeStatus,'') +
            N'; DateOfJoining=' + ISNULL(CONVERT(NVARCHAR,i.DateOfJoining,105),''),
            SYSDATETIME(),
            N'Employee Management'
        FROM inserted i;
    END
    ELSE IF @Action = 'D'
    BEGIN
        INSERT INTO audit.AuditLog (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Employee',
            CAST(d.EmployeeNo AS NVARCHAR(50)),
            'D',
            N'EmployeeCode=' + ISNULL(d.EmployeeCode,'') +
            N'; Name=' + ISNULL(d.FirstName,'') + N' ' + ISNULL(d.LastName,'') +
            N'; Status=' + ISNULL(d.EmployeeStatus,''),
            NULL,
            SYSDATETIME(),
            N'Employee Management'
        FROM deleted d;
    END
    ELSE  -- UPDATE
    BEGIN
        INSERT INTO audit.AuditLog (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Employee',
            CAST(i.EmployeeNo AS NVARCHAR(50)),
            'U',
            N'Status=' + ISNULL(d.EmployeeStatus,'') +
            N'; Designation=' + CAST(ISNULL(d.DesignationNo,0) AS NVARCHAR) +
            N'; Department=' + CAST(ISNULL(d.DepartmentNo,0) AS NVARCHAR),
            N'Status=' + ISNULL(i.EmployeeStatus,'') +
            N'; Designation=' + CAST(ISNULL(i.DesignationNo,0) AS NVARCHAR) +
            N'; Department=' + CAST(ISNULL(i.DepartmentNo,0) AS NVARCHAR),
            SYSDATETIME(),
            N'Employee Management'
        FROM inserted i
        INNER JOIN deleted d ON i.EmployeeNo = d.EmployeeNo;
    END
END;
GO

-- ------------------------------------------------------------
-- 22.03  AUDIT TRIGGER — dbo.Users
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.TR_Users_Audit','TR') IS NOT NULL DROP TRIGGER dbo.TR_Users_Audit;
GO
CREATE TRIGGER dbo.TR_Users_Audit
ON dbo.Users
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
