    DECLARE @Action CHAR(1);
    IF EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) SET @Action = 'U';
    ELSE IF EXISTS(SELECT 1 FROM inserted) SET @Action = 'I';
    ELSE SET @Action = 'D';

    IF @Action IN ('I','U')
        INSERT INTO audit.AuditLog (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedAt, AppModule)
        SELECT 'dbo','Users', CAST(i.UserNo AS NVARCHAR(50)), @Action,
            CASE WHEN @Action='U' THEN N'IsActive=' + CAST(d.IsActive AS NVARCHAR) + N'; RoleNo=' + CAST(d.RoleNo AS NVARCHAR) ELSE NULL END,
            N'Username=' + ISNULL(i.Username,'') + N'; Email=' + ISNULL(i.Email,'') + N'; RoleNo=' + CAST(i.RoleNo AS NVARCHAR) + N'; IsActive=' + CAST(i.IsActive AS NVARCHAR),
            SYSDATETIME(), N'User Management'
        FROM inserted i LEFT JOIN deleted d ON i.UserNo = d.UserNo;
    ELSE
        INSERT INTO audit.AuditLog (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedAt, AppModule)
        SELECT 'dbo','Users', CAST(d.UserNo AS NVARCHAR(50)), 'D',
            N'Username=' + ISNULL(d.Username,''), NULL, SYSDATETIME(), N'User Management'
        FROM deleted d;
END;
GO

