-- ============================================================
-- SECTION 23 — STORED PROCEDURES
-- Naming convention: usp_<Table>_<Verb>
-- All procs use TRY/CATCH with explicit transaction control.
-- ============================================================

-- ============================================================
-- 23.A  USERS
-- ============================================================

-- ------------------------------------------------------------
-- usp_Users_Insert
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Users_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_Users_Insert;
GO
CREATE PROCEDURE dbo.usp_Users_Insert
    @Username       NVARCHAR(60),
    @Email          NVARCHAR(150),
    @PasswordHash   NVARCHAR(256),
    @PasswordSalt   NVARCHAR(100) = NULL,
    @RoleNo         INT,
    @EmployeeNo     INT           = NULL,
    @CreatedBy      INT           = NULL,
    @NewUserNo      INT           OUTPUT
AS
/*
  Purpose : Create a new user account.
  Returns : @NewUserNo of the inserted row.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Validate role exists and is active
        IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleNo = @RoleNo AND Status = 1)
            THROW 50001, 'Invalid or inactive RoleNo.', 1;

        -- Validate email uniqueness (also covered by UQ constraint, but friendly message here)
        IF EXISTS (SELECT 1 FROM dbo.Users WHERE Email = @Email)
            THROW 50002, 'Email address already registered.', 1;

        INSERT INTO dbo.Users (Username, Email, PasswordHash, PasswordSalt, RoleNo, EmployeeNo, CreatedBy)
        VALUES (@Username, @Email, @PasswordHash, @PasswordSalt, @RoleNo, @EmployeeNo, @CreatedBy);

        SET @NewUserNo = SCOPE_IDENTITY();

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Users_Update
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Users_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_Users_Update;
GO
CREATE PROCEDURE dbo.usp_Users_Update
    @UserNo         INT,
    @RoleNo         INT           = NULL,
    @IsActive       BIT           = NULL,
    @IsLocked       BIT           = NULL,
    @LockReason     NVARCHAR(200) = NULL,
    @PasswordHash   NVARCHAR(256) = NULL,
    @PasswordSalt   NVARCHAR(100) = NULL
AS
/* Purpose : Partial-update a user record; only supplied (non-NULL) columns change. */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Users WHERE UserNo = @UserNo)
            THROW 50003, 'UserNo not found.', 1;

        UPDATE dbo.Users
        SET
            RoleNo        = ISNULL(@RoleNo,       RoleNo),
            IsActive      = ISNULL(@IsActive,      IsActive),
            IsLocked      = ISNULL(@IsLocked,      IsLocked),
            LockReason    = CASE WHEN @LockReason IS NOT NULL THEN @LockReason ELSE LockReason END,
            PasswordHash  = ISNULL(@PasswordHash,  PasswordHash),
            PasswordSalt  = ISNULL(@PasswordSalt,  PasswordSalt),
            FailedLoginCount = CASE WHEN @IsLocked = 0 THEN 0 ELSE FailedLoginCount END
        WHERE UserNo = @UserNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Users_Delete  (soft-delete — sets IsActive = 0)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Users_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_Users_Delete;
GO
CREATE PROCEDURE dbo.usp_Users_Delete
    @UserNo INT
AS
/* Purpose : Soft-delete a user account.  Hard-deletes are not permitted. */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Users WHERE UserNo = @UserNo)
            THROW 50003, 'UserNo not found.', 1;
        UPDATE dbo.Users SET IsActive = 0 WHERE UserNo = @UserNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Users_GetByID
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Users_GetByID','P') IS NOT NULL DROP PROCEDURE dbo.usp_Users_GetByID;
GO
CREATE PROCEDURE dbo.usp_Users_GetByID
    @UserNo INT
AS
/* Purpose : Fetch single user with role name. */
BEGIN
    SET NOCOUNT ON;
    SELECT
        u.UserNo, u.UserGUID, u.Username, u.Email,
        u.RoleNo, r.RoleName, r.RoleCode,
        u.EmployeeNo, u.IsActive, u.IsEmailVerified,
        u.LastLoginAt, u.IsLocked, u.LockReason,
        u.CreatedAt, u.UpdatedAt
    FROM dbo.Users u
    INNER JOIN dbo.Roles r ON r.RoleNo = u.RoleNo
    WHERE u.UserNo = @UserNo;
END;
GO

-- ------------------------------------------------------------
-- usp_Users_List  (paged)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Users_List','P') IS NOT NULL DROP PROCEDURE dbo.usp_Users_List;
GO
CREATE PROCEDURE dbo.usp_Users_List
    @RoleNo     INT           = NULL,
    @IsActive   BIT           = NULL,
    @SearchTerm NVARCHAR(100) = NULL,   -- partial match on Username or Email
    @SortColumn NVARCHAR(30)  = 'CreatedAt',
    @SortDir    VARCHAR(4)    = 'DESC',
    @PageNumber INT           = 1,
    @PageSize   INT           = 20,
    @TotalCount INT           OUTPUT
AS
/* Purpose : Flexible paged listing of users with optional filters. */
BEGIN
    SET NOCOUNT ON;

    -- Validate sort inputs to prevent SQL injection
    IF @SortColumn NOT IN ('UserNo','Username','Email','CreatedAt','LastLoginAt')
        SET @SortColumn = 'CreatedAt';
    IF @SortDir NOT IN ('ASC','DESC')
        SET @SortDir = 'DESC';

    -- Count first
    SELECT @TotalCount = COUNT(*)
    FROM dbo.Users u
    WHERE (@RoleNo    IS NULL OR u.RoleNo   = @RoleNo)
      AND (@IsActive  IS NULL OR u.IsActive = @IsActive)
      AND (@SearchTerm IS NULL OR u.Username LIKE '%' + @SearchTerm + '%' OR u.Email LIKE '%' + @SearchTerm + '%');

    -- Paged result — dynamic ORDER BY via CASE
    SELECT
        u.UserNo, u.Username, u.Email,
        r.RoleName, u.IsActive, u.LastLoginAt, u.CreatedAt
    FROM dbo.Users u
    INNER JOIN dbo.Roles r ON r.RoleNo = u.RoleNo
    WHERE (@RoleNo    IS NULL OR u.RoleNo   = @RoleNo)
      AND (@IsActive  IS NULL OR u.IsActive = @IsActive)
      AND (@SearchTerm IS NULL OR u.Username LIKE '%' + @SearchTerm + '%' OR u.Email LIKE '%' + @SearchTerm + '%')
    ORDER BY
        CASE WHEN @SortColumn='Username'    AND @SortDir='ASC'  THEN u.Username    END ASC,
        CASE WHEN @SortColumn='Username'    AND @SortDir='DESC' THEN u.Username    END DESC,
        CASE WHEN @SortColumn='Email'       AND @SortDir='ASC'  THEN u.Email       END ASC,
        CASE WHEN @SortColumn='Email'       AND @SortDir='DESC' THEN u.Email       END DESC,
        CASE WHEN @SortColumn='LastLoginAt' AND @SortDir='ASC'  THEN u.LastLoginAt END ASC,
        CASE WHEN @SortColumn='LastLoginAt' AND @SortDir='DESC' THEN u.LastLoginAt END DESC,
        CASE WHEN @SortColumn='CreatedAt'   AND @SortDir='ASC'  THEN u.CreatedAt   END ASC,
        CASE WHEN @SortColumn='CreatedAt'   AND @SortDir='DESC' THEN u.CreatedAt   END DESC,
        u.UserNo ASC   -- tie-breaker
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO

