IF OBJECT_ID('dbo.usp_Roles_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_Roles_Update;
GO
CREATE PROCEDURE dbo.usp_Roles_Update
    @RoleNo      INT,
    @RoleName    NVARCHAR(60)  = NULL,
    @Description NVARCHAR(300) = NULL,
    @Status      TINYINT       = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleNo = @RoleNo)
            THROW 50011, 'RoleNo not found.', 1;
        IF EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleNo = @RoleNo AND IsSystemRole = 1) AND @Status = 0
            THROW 50012, 'System roles cannot be deactivated.', 1;
        UPDATE dbo.Roles
        SET RoleName    = ISNULL(@RoleName,    RoleName),
            Description = ISNULL(@Description, Description),
            Status      = ISNULL(@Status,      Status),
            UpdatedAt   = GETDATE()
        WHERE RoleNo = @RoleNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_Roles_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_Roles_Delete;
GO
CREATE PROCEDURE dbo.usp_Roles_Delete
    @RoleNo INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleNo = @RoleNo AND IsSystemRole = 1)
            THROW 50013, 'Cannot delete a system role.', 1;
        IF EXISTS (SELECT 1 FROM dbo.Users WHERE RoleNo = @RoleNo AND IsActive = 1)
            THROW 50014, 'Role has active users — reassign before deleting.', 1;
        UPDATE dbo.Roles SET Status = 0, UpdatedAt = GETDATE() WHERE RoleNo = @RoleNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
