CREATE PROCEDURE dbo.usp_Documents_Insert
    @CategoryNo      INT,
    @EmployeeNo      INT           = NULL,
    @DocumentTitle   NVARCHAR(200),
    @DocumentCode    VARCHAR(50)   = NULL,
    @FileURL         NVARCHAR(1000),
    @FileType        VARCHAR(10),
    @FileSizeKB      INT           = NULL,
    @IssuedBy        NVARCHAR(100) = NULL,
    @IssuedDate      DATE          = NULL,
    @ExpiryDate      DATE          = NULL,
    @ReferenceNumber NVARCHAR(100) = NULL,
    @UploadedByID    INT           = NULL,
    @NewDocumentNo   INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @FileSizeKB > 5120
            THROW 50030, 'File size exceeds 5 MB limit.', 1;
        IF @FileType NOT IN ('PDF','JPG','PNG','JPEG')
            THROW 50031, 'Invalid file type. Allowed: PDF, JPG, PNG, JPEG.', 1;
        INSERT INTO dbo.Documents
            (CategoryNo, EmployeeNo, DocumentTitle, DocumentCode, FileURL, FileType,
             FileSizeKB, IssuedBy, IssuedDate, ExpiryDate, ReferenceNumber, UploadedByID)
        VALUES
            (@CategoryNo, @EmployeeNo, @DocumentTitle, @DocumentCode, @FileURL, @FileType,
             @FileSizeKB, @IssuedBy, @IssuedDate, @ExpiryDate, @ReferenceNumber, @UploadedByID);
        SET @NewDocumentNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

