    SET NOCOUNT ON;
    SELECT @TotalCount = COUNT(*) FROM dbo.Documents
    WHERE (@EmployeeNo         IS NULL OR EmployeeNo         = @EmployeeNo)
      AND (@CategoryNo         IS NULL OR CategoryNo         = @CategoryNo)
      AND (@VerificationStatus IS NULL OR VerificationStatus = @VerificationStatus)
      AND (@IsActive           IS NULL OR IsActive           = @IsActive);

    SELECT d.DocumentNo, d.DocumentTitle, d.FileType, d.FileSizeKB,
           d.VerificationStatus, d.CreatedAt, c.CategoryName
    FROM dbo.Documents d
    INNER JOIN dbo.Categories c ON c.CategoryNo = d.CategoryNo
    WHERE (@EmployeeNo         IS NULL OR d.EmployeeNo         = @EmployeeNo)
      AND (@CategoryNo         IS NULL OR d.CategoryNo         = @CategoryNo)
      AND (@VerificationStatus IS NULL OR d.VerificationStatus = @VerificationStatus)
      AND (@IsActive           IS NULL OR d.IsActive           = @IsActive)
    ORDER BY d.CreatedAt DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
