IF OBJECT_ID('dbo.usp_Employee_GetByID','P') IS NOT NULL DROP PROCEDURE dbo.usp_Employee_GetByID;
GO
CREATE PROCEDURE dbo.usp_Employee_GetByID @EmployeeNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        e.*,
        d.DepartmentName, des.DesignationName,
        g.GradeName, div.DivisionName,
        gnd.GenderName, bg.BloodGroup,
        ms.MaritalStatus AS MaritalStatusName,
        nat.NationalityName,
        CONCAT(mgr.FirstName,' ',mgr.LastName) AS ReportingManagerName
    FROM dbo.Employee e
    LEFT JOIN dbo.Department  d   ON d.DepartmentNo  = e.DepartmentNo
    LEFT JOIN dbo.Designation des ON des.DesignationNo= e.DesignationNo
    LEFT JOIN dbo.Grade       g   ON g.GradeNo        = e.GradeNo
    LEFT JOIN dbo.Division    div ON div.DivisionNo   = e.DivisionNo
    LEFT JOIN dbo.Gender      gnd ON gnd.GenderNo     = e.GenderNo
    LEFT JOIN dbo.BloodGroup  bg  ON bg.BloodGroupNo  = e.BloodGroupNo
    LEFT JOIN dbo.MaritalStatus ms ON ms.MaritalStatusNo = e.MaritalStatusNo
    LEFT JOIN dbo.Nationality nat ON nat.NationalityNo = e.NationalityNo
    LEFT JOIN dbo.Employee    mgr ON mgr.EmployeeNo   = e.ReportingManagerNo
    WHERE e.EmployeeNo = @EmployeeNo;
END;
GO

-- ------------------------------------------------------------
-- usp_Employee_Search  — flexible multi-filter search
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Employee_Search','P') IS NOT NULL DROP PROCEDURE dbo.usp_Employee_Search;
GO
CREATE PROCEDURE dbo.usp_Employee_Search
    @SearchTerm     NVARCHAR(100) = NULL,   -- name, code, email, mobile
    @DepartmentNo   INT           = NULL,
    @DesignationNo  INT           = NULL,
    @GradeNo        INT           = NULL,
    @DivisionNo     INT           = NULL,
    @GenderNo       TINYINT       = NULL,
    @EmployeeStatus VARCHAR(10)   = NULL,
    @DOJFrom        DATE          = NULL,
    @DOJTo          DATE          = NULL,
    @PageNumber     INT           = 1,
    @PageSize       INT           = 20,
    @SortColumn     NVARCHAR(30)  = 'DateOfJoining',
    @SortDir        VARCHAR(4)    = 'DESC',
    @TotalCount     INT           OUTPUT
AS
/* Purpose : Flexible employee search with optional filters and pagination.
             Used by the Employee Details Report and the employee roster. */
BEGIN
    SET NOCOUNT ON;

    IF @SortColumn NOT IN ('EmployeeCode','FirstName','DateOfJoining','EmployeeStatus')
        SET @SortColumn = 'DateOfJoining';
    IF @SortDir NOT IN ('ASC','DESC') SET @SortDir = 'DESC';

    SELECT @TotalCount = COUNT(*)
    FROM dbo.Employee e
    WHERE (@SearchTerm    IS NULL OR e.EmployeeCode LIKE '%'+@SearchTerm+'%'
                                  OR e.FirstName     LIKE '%'+@SearchTerm+'%'
                                  OR e.LastName      LIKE '%'+@SearchTerm+'%'
                                  OR e.OfficialEmail LIKE '%'+@SearchTerm+'%'
                                  OR e.OfficialMobile LIKE '%'+@SearchTerm+'%')
      AND (@DepartmentNo  IS NULL OR e.DepartmentNo  = @DepartmentNo)
      AND (@DesignationNo IS NULL OR e.DesignationNo = @DesignationNo)
      AND (@GradeNo       IS NULL OR e.GradeNo       = @GradeNo)
      AND (@DivisionNo    IS NULL OR e.DivisionNo    = @DivisionNo)
      AND (@GenderNo      IS NULL OR e.GenderNo      = @GenderNo)
      AND (@EmployeeStatus IS NULL OR e.EmployeeStatus = @EmployeeStatus)
      AND (@DOJFrom       IS NULL OR e.DateOfJoining >= @DOJFrom)
      AND (@DOJTo         IS NULL OR e.DateOfJoining <= @DOJTo);

    SELECT
        e.EmployeeNo, e.EmployeeCode, e.FirstName, e.LastName,
        e.DateOfJoining, e.EmployeeStatus, e.OfficialEmail, e.OfficialMobile,
        d.DepartmentName, des.DesignationName, g.GradeName, div.DivisionName,
        gnd.GenderName
    FROM dbo.Employee e
    LEFT JOIN dbo.Department  d   ON d.DepartmentNo   = e.DepartmentNo
    LEFT JOIN dbo.Designation des ON des.DesignationNo = e.DesignationNo
    LEFT JOIN dbo.Grade       g   ON g.GradeNo         = e.GradeNo
    LEFT JOIN dbo.Division    div ON div.DivisionNo    = e.DivisionNo
    LEFT JOIN dbo.Gender      gnd ON gnd.GenderNo      = e.GenderNo
    WHERE (@SearchTerm    IS NULL OR e.EmployeeCode LIKE '%'+@SearchTerm+'%'
                                  OR e.FirstName     LIKE '%'+@SearchTerm+'%'
                                  OR e.LastName      LIKE '%'+@SearchTerm+'%'
                                  OR e.OfficialEmail LIKE '%'+@SearchTerm+'%'
                                  OR e.OfficialMobile LIKE '%'+@SearchTerm+'%')
      AND (@DepartmentNo  IS NULL OR e.DepartmentNo  = @DepartmentNo)
      AND (@DesignationNo IS NULL OR e.DesignationNo = @DesignationNo)
      AND (@GradeNo       IS NULL OR e.GradeNo       = @GradeNo)
      AND (@DivisionNo    IS NULL OR e.DivisionNo    = @DivisionNo)
      AND (@GenderNo      IS NULL OR e.GenderNo      = @GenderNo)
      AND (@EmployeeStatus IS NULL OR e.EmployeeStatus = @EmployeeStatus)
      AND (@DOJFrom       IS NULL OR e.DateOfJoining >= @DOJFrom)
      AND (@DOJTo         IS NULL OR e.DateOfJoining <= @DOJTo)
    ORDER BY
        CASE WHEN @SortColumn='EmployeeCode'   AND @SortDir='ASC'  THEN e.EmployeeCode   END ASC,
        CASE WHEN @SortColumn='EmployeeCode'   AND @SortDir='DESC' THEN e.EmployeeCode   END DESC,
        CASE WHEN @SortColumn='FirstName'      AND @SortDir='ASC'  THEN e.FirstName      END ASC,
        CASE WHEN @SortColumn='FirstName'      AND @SortDir='DESC' THEN e.FirstName      END DESC,
        CASE WHEN @SortColumn='DateOfJoining'  AND @SortDir='ASC'  THEN e.DateOfJoining  END ASC,
        CASE WHEN @SortColumn='DateOfJoining'  AND @SortDir='DESC' THEN e.DateOfJoining  END DESC,
        CASE WHEN @SortColumn='EmployeeStatus' AND @SortDir='ASC'  THEN e.EmployeeStatus END ASC,
        CASE WHEN @SortColumn='EmployeeStatus' AND @SortDir='DESC' THEN e.EmployeeStatus END DESC,
        e.EmployeeNo ASC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

-- ============================================================
-- 23.F  LEAVE APPLICATION
-- ============================================================

IF OBJECT_ID('dbo.usp_LeaveApp_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_LeaveApp_Insert;
GO
CREATE PROCEDURE dbo.usp_LeaveApp_Insert
    @EmployeeNo   INT,
    @LeaveTypeNo  INT,
    @FromDate     DATE,
    @ToDate       DATE,
    @Days         DECIMAL(5,1),
    @Reason       NVARCHAR(500) = NULL,
    @NewLeaveAppNo INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF @ToDate < @FromDate
            THROW 50050, 'ToDate must be >= FromDate.', 1;
        IF @Days <= 0
            THROW 50051, 'Days must be greater than zero.', 1;

        -- Check balance availability
        DECLARE @FY SMALLINT = YEAR(@FromDate);
        DECLARE @Balance DECIMAL(5,1);
        SELECT @Balance = Entitled - Used
        FROM dbo.LeaveBalance
        WHERE EmployeeNo = @EmployeeNo AND LeaveTypeNo = @LeaveTypeNo AND FiscalYear = @FY;

        IF @Balance IS NULL OR @Balance < @Days
            THROW 50052, 'Insufficient leave balance.', 1;

        -- Check for HR verification threshold
        DECLARE @HRThreshold DECIMAL(5,1);
        SELECT @HRThreshold = HRVerificationThresholdDays FROM dbo.LeaveType WHERE LeaveTypeNo = @LeaveTypeNo;

        INSERT INTO dbo.LeaveApplication
            (EmployeeNo, LeaveTypeNo, FromDate, ToDate, Days, Reason, NeedsHRVerification)
        VALUES
            (@EmployeeNo, @LeaveTypeNo, @FromDate, @ToDate, @Days, @Reason,
             CASE WHEN @HRThreshold IS NOT NULL AND @Days > @HRThreshold THEN 1 ELSE 0 END);

        SET @NewLeaveAppNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_LeaveApp_Approve','P') IS NOT NULL DROP PROCEDURE dbo.usp_LeaveApp_Approve;
GO
CREATE PROCEDURE dbo.usp_LeaveApp_Approve
    @LeaveAppNo      INT,
    @ApprovedById    INT,
    @ManagerComment  NVARCHAR(500) = NULL
AS
/* Purpose : Approve a leave application and deduct the balance. */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @EmpNo INT, @LTTypeNo INT, @Days DECIMAL(5,1), @FY SMALLINT, @CurrentStatus VARCHAR(10);
        SELECT @EmpNo = EmployeeNo, @LTTypeNo = LeaveTypeNo, @Days = Days,
               @FY = YEAR(FromDate), @CurrentStatus = LeaveStatus
        FROM dbo.LeaveApplication WHERE LeaveAppNo = @LeaveAppNo;

        IF @CurrentStatus <> 'Pending'
            THROW 50060, 'Only Pending applications can be approved.', 1;

        UPDATE dbo.LeaveApplication
        SET LeaveStatus = 'Approved', @ApprovedById  = @ApprovedById ,
            ApprovalDate = GETDATE(), ManagerComment = @ManagerComment
        WHERE LeaveAppNo = @LeaveAppNo;

        -- Deduct from balance
        UPDATE dbo.LeaveBalance
        SET Used = Used + @Days
        WHERE EmployeeNo = @EmpNo AND LeaveTypeNo = @LTTypeNo AND FiscalYear = @FY;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_LeaveApp_Reject','P') IS NOT NULL DROP PROCEDURE dbo.usp_LeaveApp_Reject;
GO
CREATE PROCEDURE dbo.usp_LeaveApp_Reject
    @LeaveAppNo     INT,
    @ApprovedById   INT,
    @ManagerComment NVARCHAR(500)   -- mandatory on reject
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF @ManagerComment IS NULL OR LEN(LTRIM(@ManagerComment)) = 0
            THROW 50061, 'Manager comment is mandatory when rejecting a leave application.', 1;

        UPDATE dbo.LeaveApplication
        SET LeaveStatus = 'Rejected', ApprovedByID = @ApprovedByID,
            ApprovalDate = GETDATE(), ManagerComment = @ManagerComment
        WHERE LeaveAppNo = @LeaveAppNo AND LeaveStatus = 'Pending';

        IF @@ROWCOUNT = 0
            THROW 50062, 'Application not found or not in Pending status.', 1;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ============================================================
-- 23.G  AUDIT LOG — query procs (writes handled by triggers)
-- ============================================================

IF OBJECT_ID('dbo.usp_AuditLog_GetByEntity','P') IS NOT NULL DROP PROCEDURE dbo.usp_AuditLog_GetByEntity;
GO
CREATE PROCEDURE dbo.usp_AuditLog_GetByEntity
    @TableName  NVARCHAR(100),
    @EntityID   NVARCHAR(50),
    @PageNumber INT = 1,
    @PageSize   INT = 50,
    @TotalCount INT OUTPUT
AS
/* Purpose : Retrieve full audit history for a specific record. */
BEGIN
    SET NOCOUNT ON;
    SELECT @TotalCount = COUNT(*) FROM audit.AuditLog
    WHERE TableName = @TableName AND EntityID = @EntityID;

    SELECT AuditLogNo, Action, OldValue, NewValue,
           ChangedByUserId, ChangedByUsername, ChangedAt, AppModule, ChangeReason
    FROM audit.AuditLog
    WHERE TableName = @TableName AND EntityID = @EntityID
    ORDER BY ChangedAt DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

IF OBJECT_ID('dbo.usp_AuditLog_Search','P') IS NOT NULL DROP PROCEDURE dbo.usp_AuditLog_Search;
GO
CREATE PROCEDURE dbo.usp_AuditLog_Search
    @TableName      NVARCHAR(100) = NULL,
    @Action         CHAR(1)       = NULL,   -- I / U / D
    @UserNo         INT           = NULL,
    @FromDate       DATETIME2(0)  = NULL,
    @ToDate         DATETIME2(0)  = NULL,
    @AppModule      NVARCHAR(100) = NULL,
    @PageNumber     INT           = 1,
    @PageSize       INT           = 50,
    @TotalCount     INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @TotalCount = COUNT(*) FROM audit.AuditLog
    WHERE (@TableName IS NULL OR TableName = @TableName)
      AND (@Action    IS NULL OR Action    = @Action)
      AND (@UserNo    IS NULL OR ChangedByUserID = @UserNo)
      AND (@FromDate  IS NULL OR ChangedAt >= @FromDate)
      AND (@ToDate    IS NULL OR ChangedAt <= @ToDate)
      AND (@AppModule IS NULL OR AppModule = @AppModule);

    SELECT AuditLogNo, SchemaName, TableName, EntityID, Action,
           OldValue, NewValue, ChangedByUserID, ChangedByUsername,
           ChangedAt, IPAddress, AppModule
    FROM audit.AuditLog
    WHERE (@TableName IS NULL OR TableName = @TableName)
      AND (@Action    IS NULL OR Action    = @Action)
      AND (@UserNo    IS NULL OR ChangedByUserID = @UserNo)
      AND (@FromDate  IS NULL OR ChangedAt >= @FromDate)
      AND (@ToDate    IS NULL OR ChangedAt <= @ToDate)
      AND (@AppModule IS NULL OR AppModule = @AppModule)
    ORDER BY ChangedAt DESC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

-- ============================================================
-- 23.H  LOAN & ADVANCE
-- ============================================================

IF OBJECT_ID('dbo.usp_LoanVoucher_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_LoanVoucher_Insert;
GO
CREATE PROCEDURE dbo.usp_LoanVoucher_Insert
    @EmployeeNo          INT,
    @AppliedFor          VARCHAR(10),
    @AmountAppliedForINR DECIMAL(12,2),
    @PurposeJSON         NVARCHAR(500) = NULL,
    @CreatedByID         INT           = NULL,
    @NewVoucherNo        INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF @AppliedFor NOT IN ('Loan','Advance')
            THROW 50070, 'AppliedFor must be Loan or Advance.', 1;
        IF @AmountAppliedForINR <= 0
            THROW 50071, 'Amount must be greater than zero.', 1;

        -- Generate reference number: format Gxx-Gxx-N
        DECLARE @RefNo VARCHAR(20) = 'G' + RIGHT('0'+CAST(@EmployeeNo AS VARCHAR),3)
                                   + '-G' + RIGHT('0'+CAST(@EmployeeNo AS VARCHAR),3)
                                   + '-' + CAST(ISNULL((SELECT COUNT(*)+1 FROM dbo.LoanAdvanceVoucher WHERE EmployeeNo=@EmployeeNo),1) AS VARCHAR);

        INSERT INTO dbo.LoanAdvanceVoucher
            (ReferenceNo, EmployeeNo, AppliedFor, AmountAppliedForINR, PurposeJSON)
        VALUES
            (@RefNo, @EmployeeNo, @AppliedFor, @AmountAppliedForINR, @PurposeJSON);

        SET @NewVoucherNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_LoanVoucher_Approve','P') IS NOT NULL DROP PROCEDURE dbo.usp_LoanVoucher_Approve;
GO
CREATE PROCEDURE dbo.usp_LoanVoucher_Approve
    @VoucherNo           INT,
    @ApprovalLevel       TINYINT,
    @ApproverID          INT,
    @Decision            VARCHAR(20),
    @RemarksAndConditions NVARCHAR(500) = NULL,
    @MonthlyInstalment   INT           = NULL   -- set on Level 3 final approval
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF @Decision = 'Reject' AND (@RemarksAndConditions IS NULL OR LEN(@RemarksAndConditions) = 0)
            THROW 50072, 'Remarks are mandatory when rejecting a loan/advance.', 1;

        INSERT INTO dbo.LoanApprovalAction
            (VoucherNo, ApprovalLevel, ApproverId, Decision, RemarksAndConditions)
        VALUES
            (@VoucherNo, @ApprovalLevel, @ApproverId , @Decision, @RemarksAndConditions);

        -- Update voucher status based on decision and level
        IF @Decision = 'Reject'
            UPDATE dbo.LoanAdvanceVoucher SET VoucherStatus = 'Rejected', UpdatedAt = GETDATE() WHERE VoucherNo = @VoucherNo;
        ELSE IF @Decision = 'Approve' AND @ApprovalLevel = 3
        BEGIN
            UPDATE dbo.LoanAdvanceVoucher
            SET VoucherStatus = 'Approved',
                MonthlyInstalment = ISNULL(@MonthlyInstalment, MonthlyInstalment),
                TotalInstalmentAmount = CASE WHEN @MonthlyInstalment IS NOT NULL THEN AmountAppliedForINR ELSE TotalInstalmentAmount END,
                OutstandingAmount = AmountAppliedForINR,
                UpdatedAt = GETDATE()
            WHERE VoucherNo = @VoucherNo;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

