        BEGIN TRANSACTION;
        INSERT INTO dbo.Job (JobTitleNo, DepartmentNo, Location, JobType,
            ExperienceRequiredYears, SalaryRangeMin, SalaryRangeMax,
            JobDescription, CreatedByID, PostedDate)
        VALUES (@JobTitleNo, @DepartmentNo, @Location, @JobType,
            @ExperienceRequiredYears, @SalaryRangeMin, @SalaryRangeMax,
