IF OBJECT_ID('dbo.usp_Applicant_UpdateStatus','P') IS NOT NULL DROP PROCEDURE dbo.usp_Applicant_UpdateStatus;
GO
CREATE PROCEDURE dbo.usp_Applicant_UpdateStatus
    @ApplicantNo     INT,
    @NewStatus       VARCHAR(20),
    @StatusRemarks   NVARCHAR(300) = NULL
AS
/* Purpose : Central status-transition proc for applicant pipeline.
             Business rule: only valid forward transitions are allowed. */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @CurrentStatus VARCHAR(20);
        SELECT @CurrentStatus = ApplicantStatus FROM dbo.Applicant WHERE ApplicantNo = @ApplicantNo;

        IF @CurrentStatus IS NULL
            THROW 50080, 'ApplicantNo not found.', 1;

        -- Enforce allowed transitions
        IF @NewStatus = 'Shortlisted'   AND @CurrentStatus NOT IN ('New','Pending Review')  THROW 50081,'Invalid status transition.',1;
        IF @NewStatus = 'Rejected'      AND @CurrentStatus IN ('Offer Accepted')            THROW 50081,'Invalid status transition.',1;
        IF @NewStatus = 'Offer Accepted' AND @CurrentStatus <> 'Invited'                    THROW 50081,'Invalid status transition.',1;

        UPDATE dbo.Applicant
        SET ApplicantStatus = @NewStatus,
            StatusRemarks   = ISNULL(@StatusRemarks, StatusRemarks),
            ReadStatus      = 'Read',
            UpdatedAt       = GETDATE()
        WHERE ApplicantNo = @ApplicantNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Applicant_Search — paged applicant list with filters
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Applicant_Search','P') IS NOT NULL DROP PROCEDURE dbo.usp_Applicant_Search;
GO
CREATE PROCEDURE dbo.usp_Applicant_Search
    @JobNo          INT           = NULL,
    @Status         VARCHAR(20)   = NULL,
    @ReadStatus     VARCHAR(10)   = NULL,
    @SearchTerm     NVARCHAR(100) = NULL,   -- name / email
    @AppliedFrom    DATETIME2(0)  = NULL,
    @AppliedTo      DATETIME2(0)  = NULL,
    @SortColumn     NVARCHAR(30)  = 'AppliedAt',
    @SortDir        VARCHAR(4)    = 'DESC',
    @PageNumber     INT           = 1,
    @PageSize       INT           = 20,
    @TotalCount     INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    IF @SortColumn NOT IN ('FullName','AppliedAt','ApplicantStatus') SET @SortColumn='AppliedAt';
    IF @SortDir NOT IN ('ASC','DESC') SET @SortDir='DESC';

    SELECT @TotalCount = COUNT(*)
    FROM dbo.Applicant a
    WHERE (@JobNo      IS NULL OR a.JobNo           = @JobNo)
      AND (@Status     IS NULL OR a.ApplicantStatus = @Status)
      AND (@ReadStatus IS NULL OR a.ReadStatus      = @ReadStatus)
      AND (@SearchTerm IS NULL OR a.FullName LIKE '%'+@SearchTerm+'%' OR a.EmailAddress LIKE '%'+@SearchTerm+'%')
      AND (@AppliedFrom IS NULL OR a.AppliedAt >= @AppliedFrom)
      AND (@AppliedTo   IS NULL OR a.AppliedAt <= @AppliedTo);

    SELECT a.ApplicantNo, a.FullName, a.EmailAddress, a.PhoneNumber,
           a.ExperienceYears, a.ApplicantStatus, a.ReadStatus, a.AppliedAt,
           jt.TitleName AS JobTitle, j.Location
    FROM dbo.Applicant a
    INNER JOIN dbo.Job      j  ON j.JobNo      = a.JobNo
    INNER JOIN dbo.JobTitle jt ON jt.JobTitleNo = j.JobTitleNo
    WHERE (@JobNo      IS NULL OR a.JobNo           = @JobNo)
      AND (@Status     IS NULL OR a.ApplicantStatus = @Status)
      AND (@ReadStatus IS NULL OR a.ReadStatus      = @ReadStatus)
      AND (@SearchTerm IS NULL OR a.FullName LIKE '%'+@SearchTerm+'%' OR a.EmailAddress LIKE '%'+@SearchTerm+'%')
      AND (@AppliedFrom IS NULL OR a.AppliedAt >= @AppliedFrom)
      AND (@AppliedTo   IS NULL OR a.AppliedAt <= @AppliedTo)
    ORDER BY
        CASE WHEN @SortColumn='FullName'        AND @SortDir='ASC'  THEN a.FullName        END ASC,
        CASE WHEN @SortColumn='FullName'        AND @SortDir='DESC' THEN a.FullName        END DESC,
        CASE WHEN @SortColumn='ApplicantStatus' AND @SortDir='ASC'  THEN a.ApplicantStatus END ASC,
        CASE WHEN @SortColumn='ApplicantStatus' AND @SortDir='DESC' THEN a.ApplicantStatus END DESC,
        CASE WHEN @SortColumn='AppliedAt'       AND @SortDir='ASC'  THEN a.AppliedAt       END ASC,
        CASE WHEN @SortColumn='AppliedAt'       AND @SortDir='DESC' THEN a.AppliedAt       END DESC,
        a.ApplicantNo ASC
    OFFSET (@PageNumber-1)*@PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END;
GO

PRINT 'All stored procedures created successfully.';
