-- ============================================================
-- SECTION 24 — REPORTING VIEWS  (rpt schema)
-- ============================================================

-- ------------------------------------------------------------
-- rpt.vw_EmployeeMaster — full employee snapshot (for reports)
-- ------------------------------------------------------------
IF OBJECT_ID('rpt.vw_EmployeeMaster','V') IS NOT NULL DROP VIEW rpt.vw_EmployeeMaster;
GO
CREATE VIEW rpt.vw_EmployeeMaster
AS
SELECT
    e.EmployeeNo,
    e.EmployeeCode,
    e.FirstName + ' ' + e.LastName                          AS FullName,
    e.DateOfBirth,
    e.DateOfJoining,
    e.EmployeeStatus,
    e.PANNumber,
    e.OfficialEmail,
    e.OfficialMobile,
    d.DepartmentName,
    des.DesignationName,
    g.GradeName,
    div.DivisionName,
    gnd.GenderName,
    bg.BloodGroup,
    ms.MaritalStatus                                         AS MaritalStatusName,
    nat.NationalityName,
    rel.ReligionName,
    CONCAT(mgr.FirstName,' ',mgr.LastName)                  AS ReportingManager,
    e.ExcludeFromPayroll,
    e.CreatedAt                                              AS RecordCreatedAt
FROM dbo.Employee e
LEFT JOIN dbo.Department   d   ON d.DepartmentNo   = e.DepartmentNo
LEFT JOIN dbo.Designation  des ON des.DesignationNo = e.DesignationNo
LEFT JOIN dbo.Grade        g   ON g.GradeNo         = e.GradeNo
LEFT JOIN dbo.Division     div ON div.DivisionNo    = e.DivisionNo
LEFT JOIN dbo.Gender       gnd ON gnd.GenderNo      = e.GenderNo
LEFT JOIN dbo.BloodGroup   bg  ON bg.BloodGroupNo   = e.BloodGroupNo
LEFT JOIN dbo.MaritalStatus ms ON ms.MaritalStatusNo= e.MaritalStatusNo
LEFT JOIN dbo.Nationality  nat ON nat.NationalityNo = e.NationalityNo
LEFT JOIN dbo.Religion     rel ON rel.ReligionNo    = e.ReligionNo
LEFT JOIN dbo.Employee     mgr ON mgr.EmployeeNo    = e.ReportingManagerNo;
GO

-- ------------------------------------------------------------
-- rpt.vw_LeaveBalance — employee-wise leave balance summary
-- ------------------------------------------------------------
IF OBJECT_ID('rpt.vw_LeaveBalance','V') IS NOT NULL DROP VIEW rpt.vw_LeaveBalance;
GO
CREATE VIEW rpt.vw_LeaveBalance
AS
SELECT
    lb.LeaveBalanceNo,
    lb.FiscalYear,
    e.EmployeeCode,
    e.FirstName + ' ' + e.LastName AS FullName,
    d.DepartmentName,
    lt.LeaveName,
    lt.LeaveCode,
    lb.Entitled,
    lb.Used,
    lb.CarriedForward,
    lb.Entitled - lb.Used           AS Available,
    lb.Encashed,
    lb.Lapsed
FROM dbo.LeaveBalance lb
INNER JOIN dbo.Employee  e  ON e.EmployeeNo  = lb.EmployeeNo
INNER JOIN dbo.LeaveType lt ON lt.LeaveTypeNo= lb.LeaveTypeNo
LEFT JOIN  dbo.Department d  ON d.DepartmentNo = e.DepartmentNo;
GO

-- ------------------------------------------------------------
-- rpt.vw_AttendanceSummary — monthly per-employee summary
-- ------------------------------------------------------------
IF OBJECT_ID('rpt.vw_AttendanceSummary','V') IS NOT NULL DROP VIEW rpt.vw_AttendanceSummary;
GO
CREATE VIEW rpt.vw_AttendanceSummary
AS
SELECT
    ar.EmployeeNo,
    e.EmployeeCode,
    e.FirstName + ' ' + e.LastName AS FullName,
    d.DepartmentName,
    YEAR(ar.AttendanceDate)                                                  AS AttYear,
    MONTH(ar.AttendanceDate)                                                 AS AttMonth,
    COUNT(*)                                                                 AS TotalDays,
    SUM(CASE WHEN ar.AttendanceStatus='Present'    THEN 1 ELSE 0 END)       AS PresentDays,
    SUM(CASE WHEN ar.AttendanceStatus='Half Day'   THEN 1 ELSE 0 END)       AS HalfDays,
    SUM(CASE WHEN ar.AttendanceStatus='Absent'     THEN 1 ELSE 0 END)       AS AbsentDays,
    SUM(CASE WHEN ar.IsLate = 1                    THEN 1 ELSE 0 END)       AS LateDays,
    SUM(ISNULL(ar.OvertimeMinutes,0))                                        AS TotalOvertimeMins,
    CAST(
        100.0 * SUM(CASE WHEN ar.AttendanceStatus IN ('Present','Half Day') THEN 1.0
                         WHEN ar.AttendanceStatus='Half Day' THEN 0.5 ELSE 0 END)
        / NULLIF(COUNT(*),0) AS DECIMAL(5,2))                               AS AttendancePct
FROM dbo.AttendanceRecord ar
INNER JOIN dbo.Employee   e ON e.EmployeeNo  = ar.EmployeeNo
LEFT JOIN  dbo.Department d ON d.DepartmentNo= e.DepartmentNo
GROUP BY ar.EmployeeNo, e.EmployeeCode, e.FirstName, e.LastName,
         d.DepartmentName, YEAR(ar.AttendanceDate), MONTH(ar.AttendanceDate);
GO

-- ------------------------------------------------------------
-- rpt.vw_LoanAdvanceSummary
-- ------------------------------------------------------------
IF OBJECT_ID('rpt.vw_LoanAdvanceSummary','V') IS NOT NULL DROP VIEW rpt.vw_LoanAdvanceSummary;
GO
CREATE VIEW rpt.vw_LoanAdvanceSummary
AS
SELECT
    v.VoucherNo,
    v.ReferenceNo,
    e.EmployeeCode,
    e.FirstName + ' ' + e.LastName   AS FullName,
    d.DepartmentName,
    v.AppliedFor,
    v.AmountAppliedForINR,
    v.MonthlyInstalment,
    v.VoucherStatus,
    v.OutstandingAmount,
    ISNULL(
        (SELECT SUM(AmountPaidINR) FROM dbo.LoanClearanceRecord WHERE VoucherNo=v.VoucherNo),
        0)                           AS TotalAmountPaid,
    v.CreatedAt                      AS ApplicationDate
FROM dbo.LoanAdvanceVoucher v
INNER JOIN dbo.Employee   e ON e.EmployeeNo  = v.EmployeeNo
LEFT JOIN  dbo.Department d ON d.DepartmentNo= e.DepartmentNo;
GO

PRINT 'Reporting views created.';
GO

-- ============================================================
-- SECTION : LinkAllowancesDeductionWithGrade
-- Purpose : Maps which Allowances/Deductions apply to a given
--           State + Grade combination, along with the
--           calculation method, amount/percentage, and whether
--           the component should be prorated on present days.
--           Corresponds to the "Link Allowance/Deduction with
--           Grade" screen in System Settings.
-- ============================================================

-- ============================================================
-- TABLE : dbo.LinkAllowancesDeductionWithGrade
-- ============================================================
IF OBJECT_ID('dbo.LinkAllowancesDeductionWithGrade','U') IS NOT NULL
    DROP TABLE dbo.LinkAllowancesDeductionWithGrade;
GO

CREATE TABLE dbo.LinkAllowancesDeductionWithGrade (
    -- ----------------------------------------------------------
    -- Primary Key — surrogate IDENTITY key
    -- ----------------------------------------------------------
    LinkADGradeNo           INT           NOT NULL IDENTITY(1,1)
        CONSTRAINT PK_LinkADGrade PRIMARY KEY CLUSTERED,

    -- ----------------------------------------------------------
    -- State reference (nullable — NULL means applies to ALL states)
    -- Drives the "Choose State" dropdown on the listing screen.
    -- ----------------------------------------------------------
    StateNo                 SMALLINT      NOT NULL,
    -- FK to dbo.State.StateNo; e.g. Andhra Pradesh

    -- ----------------------------------------------------------
    -- Grade reference — which salary grade this row belongs to.
    -- Drives the "Choose Grade" dropdown on the listing screen.
    -- ----------------------------------------------------------
    GradeNo                 INT           NOT NULL,
    -- FK to dbo.Grade.GradeNo; e.g. Grade 1

    -- ----------------------------------------------------------
    -- Allowance / Deduction component being linked.
    -- ----------------------------------------------------------
    AllowanceDeductionNo    INT           NOT NULL,
    -- FK to dbo.AllowanceDeduction.AllowanceDeductionNo
    -- e.g. EPF, ESI, HRA, CA, TDS DED …

    -- ----------------------------------------------------------
    -- Calculation basis — how the amount is derived.
    -- Shown in the "Calculation on" column and modal dropdown.
    -- Allowed values mirror the scope: Percentage On Amount,
    -- Percentage On Basic, Percentage On Gross, Fixed Amount.
    -- ----------------------------------------------------------
    CalculationOn           VARCHAR(30)   NOT NULL,
    -- 'Percentage On Amount' | 'Percentage On Basic' |
    -- 'Percentage On Gross'  | 'Fixed Amount'

    -- ----------------------------------------------------------
    -- SelectType — whether the component value is expressed as
    -- a percentage or a flat rupee value.  Drives the radio
    -- button in the "Add Allowances/Deduction" modal.
    -- ----------------------------------------------------------
    SelectType              VARCHAR(10)   NOT NULL
        CONSTRAINT DF_LinkADG_SelectType DEFAULT 'Percentage',
    -- 'Percentage' | 'Value'

    -- ----------------------------------------------------------
    -- PercentageValue — active when SelectType = 'Percentage'.
    -- Stored as a decimal; e.g. 30.00 means 30 %.
    -- NULL is allowed when SelectType = 'Value'.
    -- ----------------------------------------------------------
    PercentageValue         DECIMAL(6,2)  NULL,
    -- Range 0.00 – 100.00; mandatory when SelectType = 'Percentage'

    -- ----------------------------------------------------------
    -- FixedValue — active when SelectType = 'Value'.
    -- Flat INR amount for the pay component.
    -- NULL is allowed when SelectType = 'Percentage'.
    -- ----------------------------------------------------------
    FixedValue              DECIMAL(12,2) NULL,
    -- Mandatory when SelectType = 'Value'

    -- ----------------------------------------------------------
    -- VaryOnDays — whether the component is prorated on the
    -- number of days an employee was present/paid in the month.
    -- Shown as "Vary on days" column (Yes/No).
    -- ----------------------------------------------------------
    VaryOnDays              BIT           NOT NULL
        CONSTRAINT DF_LinkADG_VaryOnDays DEFAULT 1,
    -- 1 = Yes (prorate)  |  0 = No (always full amount)

    -- ----------------------------------------------------------
    -- DisplayOrder — controls the S.No. sequence on screen.
    -- ----------------------------------------------------------
    DisplayOrder            SMALLINT      NOT NULL
        CONSTRAINT DF_LinkADG_DisplayOrder DEFAULT 99,

    -- ----------------------------------------------------------
    -- Status — 1 = Active, 0 = Inactive (soft-delete pattern)
    -- ----------------------------------------------------------
    Status                  TINYINT       NOT NULL
        CONSTRAINT DF_LinkADG_Status DEFAULT 1,

    -- ----------------------------------------------------------
    -- Audit stamp columns
    -- CreatedAt is set by DEFAULT on INSERT (also enforced by
    -- the TR_LinkADGrade_Timestamps trigger below).
    -- UpdatedAt is set by trigger on every UPDATE.
    -- ----------------------------------------------------------
    CreatedAt               DATETIME2(0)  NOT NULL
        CONSTRAINT DF_LinkADG_CreatedAt DEFAULT GETDATE(),

    UpdatedAt               DATETIME2(0)  NULL,

    CreatedBy               INT           NULL,
    -- FK to dbo.Users.UserNo — who created this mapping

    -- ==========================================================
    -- CONSTRAINTS
    -- ==========================================================

    -- Unique: only one row per State + Grade + Component combo.
    -- Prevents duplicate entries for the same combination.
    CONSTRAINT UQ_LinkADG_StateGradeAD
        UNIQUE (StateNo, GradeNo, AllowanceDeductionNo),

    -- Domain: CalculationOn must be one of the four defined bases.
    CONSTRAINT CK_LinkADG_CalcOn
        CHECK (CalculationOn IN (
            'Percentage On Amount',
            'Percentage On Basic',
            'Percentage On Gross',
            'Fixed Amount'
        )),

    -- Domain: SelectType drives which value column is used.
    CONSTRAINT CK_LinkADG_SelectType
        CHECK (SelectType IN ('Percentage','Value')),

    -- Business rule: when SelectType = 'Percentage',
    -- PercentageValue must be supplied and in range 0–100.
    CONSTRAINT CK_LinkADG_PctRequired
        CHECK (
            SelectType <> 'Percentage'
            OR (PercentageValue IS NOT NULL
                AND PercentageValue >= 0
                AND PercentageValue <= 100)
        ),

    -- Business rule: when SelectType = 'Value',
    -- FixedValue must be supplied and positive.
    CONSTRAINT CK_LinkADG_FixedRequired
        CHECK (
            SelectType <> 'Value'
            OR (FixedValue IS NOT NULL AND FixedValue >= 0)
        ),

    -- Domain: Status must be 0 or 1.
    CONSTRAINT CK_LinkADG_Status
        CHECK (Status IN (0, 1)),

    -- Domain: DisplayOrder must be a positive integer.
    CONSTRAINT CK_LinkADG_DisplayOrder
        CHECK (DisplayOrder > 0),

    -- ==========================================================
    -- FOREIGN KEYS
    -- ==========================================================

    -- State must exist in dbo.State.
    -- SET NULL on DELETE: if a State is deleted, StateNo becomes
    -- NULL so the mapping is preserved but deactivated.
    CONSTRAINT FK_LinkADG_State
        FOREIGN KEY (StateNo)
        REFERENCES dbo.State (StateNo)
        ON DELETE NO ACTION
        ON UPDATE CASCADE,

    -- Grade must exist in dbo.Grade.
    -- CASCADE DELETE: removing a Grade removes its AD mappings.
    CONSTRAINT FK_LinkADG_Grade
        FOREIGN KEY (GradeNo)
        REFERENCES dbo.Grade (GradeNo)
        ON DELETE CASCADE
        ON UPDATE CASCADE,

    -- Allowance/Deduction component must exist.
    -- No cascade — prevents orphan component removal.
    CONSTRAINT FK_LinkADG_AD
        FOREIGN KEY (AllowanceDeductionNo)
        REFERENCES dbo.AllowanceDeduction (AllowanceDeductionNo)
        ON DELETE NO ACTION
        ON UPDATE NO ACTION
);
GO

