-- ============================================================
-- TRIGGER 1 : dbo.TR_LinkADGrade_Timestamps
-- Purpose   : Auto-set UpdatedAt on every UPDATE.
--             CreatedAt is handled by DEFAULT on INSERT, but
--             the trigger ensures it is never overwritten.
-- ============================================================
IF OBJECT_ID('dbo.TR_LinkADGrade_Timestamps','TR') IS NOT NULL
    DROP TRIGGER dbo.TR_LinkADGrade_Timestamps;
GO

CREATE TRIGGER dbo.TR_LinkADGrade_Timestamps
ON dbo.LinkAllowancesDeductionWithGrade
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    -- On INSERT: ensure CreatedAt is never NULL (belt-and-braces
    -- alongside the DEFAULT constraint).
    IF NOT EXISTS (SELECT 1 FROM deleted)   -- INSERT path
    BEGIN
        UPDATE t
        SET    t.CreatedAt = ISNULL(t.CreatedAt, GETDATE())
        FROM   dbo.LinkAllowancesDeductionWithGrade t
        INNER JOIN inserted i ON t.LinkADGradeNo = i.LinkADGradeNo;
    END
    ELSE                                     -- UPDATE path
    BEGIN
        UPDATE t
        SET    t.UpdatedAt = GETDATE()
        FROM   dbo.LinkAllowancesDeductionWithGrade t
        INNER JOIN inserted i ON t.LinkADGradeNo = i.LinkADGradeNo;
    END
END;
GO

-- ============================================================
-- TRIGGER 2 : dbo.TR_LinkADGrade_Audit
-- Purpose   : Write a row to audit.AuditLog for every INSERT,
--             UPDATE, and DELETE on this table.
--             OldValue / NewValue capture the key business
--             columns that can change (CalculationOn,
--             SelectType, PercentageValue, FixedValue,
--             VaryOnDays, Status, DisplayOrder).
-- ============================================================
IF OBJECT_ID('dbo.TR_LinkADGrade_Audit','TR') IS NOT NULL
    DROP TRIGGER dbo.TR_LinkADGrade_Audit;
GO

CREATE TRIGGER dbo.TR_LinkADGrade_Audit
ON dbo.LinkAllowancesDeductionWithGrade
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- Determine action type
    DECLARE @Action CHAR(1);
    IF EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted)
        SET @Action = 'U';          -- UPDATE
    ELSE IF EXISTS (SELECT 1 FROM inserted)
        SET @Action = 'I';          -- INSERT
    ELSE
        SET @Action = 'D';          -- DELETE

    -- Helper: build a readable string representation of a row
    -- Format: StateNo=x; GradeNo=x; ADNO=x; CalcOn=x; Type=x; Pct=x; Fixed=x; VaryOnDays=x; Status=x

    IF @Action = 'I'
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo',
            'LinkAllowancesDeductionWithGrade',
            CAST(i.LinkADGradeNo AS NVARCHAR(50)),
            'I',
            NULL,
            N'StateNo='      + CAST(i.StateNo AS NVARCHAR)
            + N'; GradeNo='  + CAST(i.GradeNo AS NVARCHAR)
            + N'; ADNO='     + CAST(i.AllowanceDeductionNo AS NVARCHAR)
            + N'; CalcOn='   + ISNULL(i.CalculationOn,'')
            + N'; Type='     + ISNULL(i.SelectType,'')
            + N'; Pct='      + ISNULL(CAST(i.PercentageValue AS NVARCHAR),'NULL')
            + N'; Fixed='    + ISNULL(CAST(i.FixedValue    AS NVARCHAR),'NULL')
            + N'; VaryOnDays='+ CAST(i.VaryOnDays AS NVARCHAR)
            + N'; Status='   + CAST(i.Status AS NVARCHAR),
            SYSDATETIME(),
            N'System Settings – Link Allowance/Deduction with Grade'
        FROM inserted i;
    END

    ELSE IF @Action = 'D'
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo',
            'LinkAllowancesDeductionWithGrade',
            CAST(d.LinkADGradeNo AS NVARCHAR(50)),
            'D',
            N'StateNo='      + CAST(d.StateNo AS NVARCHAR)
            + N'; GradeNo='  + CAST(d.GradeNo AS NVARCHAR)
            + N'; ADNO='     + CAST(d.AllowanceDeductionNo AS NVARCHAR)
            + N'; CalcOn='   + ISNULL(d.CalculationOn,'')
            + N'; Type='     + ISNULL(d.SelectType,'')
            + N'; Pct='      + ISNULL(CAST(d.PercentageValue AS NVARCHAR),'NULL')
            + N'; Fixed='    + ISNULL(CAST(d.FixedValue    AS NVARCHAR),'NULL')
            + N'; VaryOnDays='+ CAST(d.VaryOnDays AS NVARCHAR)
            + N'; Status='   + CAST(d.Status AS NVARCHAR),
            NULL,
            SYSDATETIME(),
            N'System Settings – Link Allowance/Deduction with Grade'
        FROM deleted d;
    END

    ELSE  -- UPDATE
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo',
            'LinkAllowancesDeductionWithGrade',
            CAST(i.LinkADGradeNo AS NVARCHAR(50)),
            'U',
            -- OldValue from deleted (before-image)
            N'StateNo='      + CAST(d.StateNo AS NVARCHAR)
            + N'; GradeNo='  + CAST(d.GradeNo AS NVARCHAR)
            + N'; ADNO='     + CAST(d.AllowanceDeductionNo AS NVARCHAR)
            + N'; CalcOn='   + ISNULL(d.CalculationOn,'')
            + N'; Type='     + ISNULL(d.SelectType,'')
            + N'; Pct='      + ISNULL(CAST(d.PercentageValue AS NVARCHAR),'NULL')
            + N'; Fixed='    + ISNULL(CAST(d.FixedValue    AS NVARCHAR),'NULL')
            + N'; VaryOnDays='+ CAST(d.VaryOnDays AS NVARCHAR)
            + N'; Status='   + CAST(d.Status AS NVARCHAR),
            -- NewValue from inserted (after-image)
            N'StateNo='      + CAST(i.StateNo AS NVARCHAR)
            + N'; GradeNo='  + CAST(i.GradeNo AS NVARCHAR)
            + N'; ADNO='     + CAST(i.AllowanceDeductionNo AS NVARCHAR)
            + N'; CalcOn='   + ISNULL(i.CalculationOn,'')
            + N'; Type='     + ISNULL(i.SelectType,'')
            + N'; Pct='      + ISNULL(CAST(i.PercentageValue AS NVARCHAR),'NULL')
            + N'; Fixed='    + ISNULL(CAST(i.FixedValue    AS NVARCHAR),'NULL')
            + N'; VaryOnDays='+ CAST(i.VaryOnDays AS NVARCHAR)
            + N'; Status='   + CAST(i.Status AS NVARCHAR),
            SYSDATETIME(),
            N'System Settings – Link Allowance/Deduction with Grade'
        FROM inserted i
        INNER JOIN deleted d ON i.LinkADGradeNo = d.LinkADGradeNo;
    END
END;
GO

