-- STORED PROCEDURES : LinkAllowancesDeductionWithGrade
-- ============================================================

-- ------------------------------------------------------------
-- usp_LinkADGrade_Insert
-- Purpose : Add a new Allowance/Deduction mapping for a
--           State + Grade combination.
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_Insert','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_Insert;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_Insert
    @StateNo                SMALLINT,
    @GradeNo                INT,
    @AllowanceDeductionNo   INT,
    @CalculationOn          VARCHAR(30),
    @SelectType             VARCHAR(10)   = 'Percentage',
    @PercentageValue        DECIMAL(6,2)  = NULL,
    @FixedValue             DECIMAL(12,2) = NULL,
    @VaryOnDays             BIT           = 1,
    @DisplayOrder           SMALLINT      = 99,
    @CreatedBy              INT           = NULL,
    @NewLinkADGradeNo       INT           OUTPUT
AS
/*
  Purpose : Insert a new row into LinkAllowancesDeductionWithGrade.
  Validates FK existence, domain rules, and uniqueness before INSERT.
  Returns the new surrogate key via @NewLinkADGradeNo OUTPUT.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Validate State
        IF NOT EXISTS (SELECT 1 FROM dbo.State WHERE StateNo = @StateNo AND Status = 1)
            THROW 60001, 'Invalid or inactive StateNo.', 1;

        -- 2. Validate Grade
        IF NOT EXISTS (SELECT 1 FROM dbo.Grade WHERE GradeNo = @GradeNo AND Status = 1)
            THROW 60002, 'Invalid or inactive GradeNo.', 1;

        -- 3. Validate AllowanceDeduction
        IF NOT EXISTS (SELECT 1 FROM dbo.AllowanceDeduction WHERE AllowanceDeductionNo = @AllowanceDeductionNo AND Status = 1)
            THROW 60003, 'Invalid or inactive AllowanceDeductionNo.', 1;

        -- 4. Validate CalculationOn domain
        IF @CalculationOn NOT IN ('Percentage On Amount','Percentage On Basic','Percentage On Gross','Fixed Amount')
            THROW 60004, 'Invalid CalculationOn value.', 1;

        -- 5. Validate SelectType domain
        IF @SelectType NOT IN ('Percentage','Value')
            THROW 60005, 'SelectType must be Percentage or Value.', 1;

        -- 6. Enforce SelectType-dependent value rules
        IF @SelectType = 'Percentage' AND (@PercentageValue IS NULL OR @PercentageValue < 0 OR @PercentageValue > 100)
            THROW 60006, 'PercentageValue must be between 0 and 100 when SelectType is Percentage.', 1;

        IF @SelectType = 'Value' AND (@FixedValue IS NULL OR @FixedValue < 0)
            THROW 60007, 'FixedValue must be >= 0 when SelectType is Value.', 1;

        -- 7. Check uniqueness (friendly message before DB constraint fires)
        IF EXISTS (
            SELECT 1 FROM dbo.LinkAllowancesDeductionWithGrade
            WHERE StateNo = @StateNo
              AND GradeNo = @GradeNo
              AND AllowanceDeductionNo = @AllowanceDeductionNo
        )
            THROW 60008, 'This Allowance/Deduction is already linked to the selected State and Grade.', 1;

        -- 8. Insert
        INSERT INTO dbo.LinkAllowancesDeductionWithGrade
            (StateNo, GradeNo, AllowanceDeductionNo, CalculationOn,
             SelectType, PercentageValue, FixedValue, VaryOnDays,
             DisplayOrder, Status, CreatedBy)
        VALUES
            (@StateNo, @GradeNo, @AllowanceDeductionNo, @CalculationOn,
             @SelectType, @PercentageValue, @FixedValue, @VaryOnDays,
             @DisplayOrder, 1, @CreatedBy);

        SET @NewLinkADGradeNo = SCOPE_IDENTITY();

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_LinkADGrade_Update
-- Purpose : Modify an existing mapping.  Only supplied
--           (non-NULL) columns are changed — partial update.
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_Update','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_Update;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_Update
    @LinkADGradeNo          INT,
    @CalculationOn          VARCHAR(30)   = NULL,
    @SelectType             VARCHAR(10)   = NULL,
    @PercentageValue        DECIMAL(6,2)  = NULL,
    @FixedValue             DECIMAL(12,2) = NULL,
    @VaryOnDays             BIT           = NULL,
    @DisplayOrder           SMALLINT      = NULL,
    @Status                 TINYINT       = NULL
AS
/*
  Purpose : Partial update of a LinkAllowancesDeductionWithGrade row.
  State/Grade/AllowanceDeduction cannot be changed after creation;
  create a new row instead if the combination must change.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        -- Verify record exists
        IF NOT EXISTS (SELECT 1 FROM dbo.LinkAllowancesDeductionWithGrade WHERE LinkADGradeNo = @LinkADGradeNo)
            THROW 60010, 'LinkADGradeNo not found.', 1;

        -- Validate CalculationOn if provided
        IF @CalculationOn IS NOT NULL
           AND @CalculationOn NOT IN ('Percentage On Amount','Percentage On Basic','Percentage On Gross','Fixed Amount')
            THROW 60011, 'Invalid CalculationOn value.', 1;

        -- Validate SelectType if provided
        IF @SelectType IS NOT NULL AND @SelectType NOT IN ('Percentage','Value')
            THROW 60012, 'SelectType must be Percentage or Value.', 1;

        -- Re-validate value rules when SelectType is being changed
        DECLARE @ResolvedType    VARCHAR(10);
        DECLARE @ResolvedPct     DECIMAL(6,2);
        DECLARE @ResolvedFixed   DECIMAL(12,2);

        SELECT @ResolvedType  = ISNULL(@SelectType,      SelectType),
               @ResolvedPct   = ISNULL(@PercentageValue, PercentageValue),
               @ResolvedFixed = ISNULL(@FixedValue,      FixedValue)
        FROM   dbo.LinkAllowancesDeductionWithGrade
        WHERE  LinkADGradeNo = @LinkADGradeNo;

        IF @ResolvedType = 'Percentage' AND (@ResolvedPct IS NULL OR @ResolvedPct < 0 OR @ResolvedPct > 100)
            THROW 60013, 'PercentageValue must be between 0 and 100 when SelectType is Percentage.', 1;

        IF @ResolvedType = 'Value' AND (@ResolvedFixed IS NULL OR @ResolvedFixed < 0)
            THROW 60014, 'FixedValue must be >= 0 when SelectType is Value.', 1;

        -- Apply partial update (only non-NULL parameters change)
        UPDATE dbo.LinkAllowancesDeductionWithGrade
        SET
            CalculationOn    = ISNULL(@CalculationOn,   CalculationOn),
            SelectType       = ISNULL(@SelectType,      SelectType),
            PercentageValue  = ISNULL(@PercentageValue, PercentageValue),
            FixedValue       = ISNULL(@FixedValue,      FixedValue),
            VaryOnDays       = ISNULL(@VaryOnDays,      VaryOnDays),
            DisplayOrder     = ISNULL(@DisplayOrder,    DisplayOrder),
            Status           = ISNULL(@Status,          Status)
            -- UpdatedAt is set by TR_LinkADGrade_Timestamps trigger
        WHERE LinkADGradeNo = @LinkADGradeNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_LinkADGrade_Delete
-- Purpose : Soft-delete — sets Status = 0.
--           Hard-delete is not permitted to preserve audit trail.
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_Delete','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_Delete;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_Delete
    @LinkADGradeNo INT
AS
/*
  Purpose : Soft-delete a State/Grade/AD mapping.
  Sets Status = 0; the row is preserved for audit history.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.LinkAllowancesDeductionWithGrade WHERE LinkADGradeNo = @LinkADGradeNo)
            THROW 60020, 'LinkADGradeNo not found.', 1;

        UPDATE dbo.LinkAllowancesDeductionWithGrade
        SET Status = 0
        WHERE LinkADGradeNo = @LinkADGradeNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_LinkADGrade_GetByID
-- Purpose : Fetch a single mapping row with its related names.
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_GetByID','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_GetByID;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_GetByID
    @LinkADGradeNo INT
AS
/*
  Purpose : Retrieve full detail of a single State/Grade/AD link
            with joined display names for UI read-back.
*/
BEGIN
    SET NOCOUNT ON;

    SELECT
        lk.LinkADGradeNo,
        lk.StateNo,
        st.StateName,
        lk.GradeNo,
        gr.GradeName,
        lk.AllowanceDeductionNo,
        ad.ADName              AS ADName,
        ad.AccountType,        -- A = Allowance, D = Deduction
        lk.CalculationOn,
        lk.SelectType,
        lk.PercentageValue,
        lk.FixedValue,
        lk.VaryOnDays,
        lk.DisplayOrder,
        lk.Status,
        lk.CreatedAt,
        lk.UpdatedAt,
        lk.CreatedBy
    FROM  dbo.LinkAllowancesDeductionWithGrade lk
    INNER JOIN dbo.State               st ON st.StateNo               = lk.StateNo
    INNER JOIN dbo.Grade               gr ON gr.GradeNo               = lk.GradeNo
    INNER JOIN dbo.AllowanceDeduction  ad ON ad.AllowanceDeductionNo  = lk.AllowanceDeductionNo
    WHERE lk.LinkADGradeNo = @LinkADGradeNo;
END;
GO

-- ------------------------------------------------------------
-- usp_LinkADGrade_List
-- Purpose : Paged listing for the "Link Allowance/Deduction
--           with Grade" screen.  Filters by State, Grade, and
--           Status.  Sorted by DisplayOrder then AD name.
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_List','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_List;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_List
    @StateNo        SMALLINT      = NULL,   -- NULL = all states
    @GradeNo        INT           = NULL,   -- NULL = all grades
    @Status         TINYINT       = 1,      -- default Active only; NULL = all
    @PageNumber     INT           = 1,
    @PageSize       INT           = 50,
    @TotalCount     INT           OUTPUT
AS
/*
  Purpose : Return the paginated list of AD mappings that power
            the "Link Allowance/Deduction with Grade" grid.
            Matches the screen: Choose State + Choose Grade dropdowns
            filter the grid; rows ordered by DisplayOrder.
*/
BEGIN
    SET NOCOUNT ON;

    -- Total row count for pagination metadata
    SELECT @TotalCount = COUNT(*)
    FROM   dbo.LinkAllowancesDeductionWithGrade lk
    WHERE  (@StateNo  IS NULL OR lk.StateNo  = @StateNo)
      AND  (@GradeNo  IS NULL OR lk.GradeNo  = @GradeNo)
      AND  (@Status   IS NULL OR lk.Status   = @Status);

    -- Paged result set — mirrors screen columns:
    -- S.No. | Allowances/Deduction | Calculation on | Vary on days
    SELECT
        ROW_NUMBER() OVER (ORDER BY lk.DisplayOrder, ad.ADName) AS SNo,
        lk.LinkADGradeNo,
        lk.StateNo,
        st.StateName,
        lk.GradeNo,
        gr.GradeName,
        lk.AllowanceDeductionNo,
        ad.ADName              AS ADName,
        ad.AccountType,
        lk.CalculationOn,
        lk.SelectType,
        lk.PercentageValue,
        lk.FixedValue,
        CASE lk.VaryOnDays WHEN 1 THEN 'Yes' ELSE 'No' END AS VaryOnDays,
        lk.DisplayOrder,
        lk.Status,
        lk.CreatedAt,
        lk.UpdatedAt
    FROM  dbo.LinkAllowancesDeductionWithGrade lk
    INNER JOIN dbo.State               st ON st.StateNo              = lk.StateNo
    INNER JOIN dbo.Grade               gr ON gr.GradeNo              = lk.GradeNo
    INNER JOIN dbo.AllowanceDeduction  ad ON ad.AllowanceDeductionNo = lk.AllowanceDeductionNo
    WHERE  (@StateNo  IS NULL OR lk.StateNo  = @StateNo)
      AND  (@GradeNo  IS NULL OR lk.GradeNo  = @GradeNo)
      AND  (@Status   IS NULL OR lk.Status   = @Status)
    ORDER BY lk.DisplayOrder, ad.ADName
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO

-- ------------------------------------------------------------
-- usp_LinkADGrade_SetOrder
-- Purpose : Bulk-update DisplayOrder values for a State+Grade
--           set — corresponds to the "Set Order" button on screen.
-- Accepts a JSON array: [{"LinkADGradeNo":1,"DisplayOrder":1}, ...]
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_LinkADGrade_SetOrder','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_LinkADGrade_SetOrder;
GO

CREATE PROCEDURE dbo.usp_LinkADGrade_SetOrder
    @OrderJSON NVARCHAR(MAX)   -- JSON: [{"LinkADGradeNo":n,"DisplayOrder":n}, ...]
AS
/*
  Purpose : Update DisplayOrder for multiple rows in a single
            call — powers the "Set Order" button on the listing
            screen.  Uses OPENJSON (SQL Server 2016+).
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE lk
        SET    lk.DisplayOrder = j.DisplayOrder
        FROM   dbo.LinkAllowancesDeductionWithGrade lk
        INNER JOIN OPENJSON(@OrderJSON)
            WITH (
                LinkADGradeNo INT           '$.LinkADGradeNo',
                DisplayOrder  SMALLINT      '$.DisplayOrder'
            ) j ON j.LinkADGradeNo = lk.LinkADGradeNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

