-- ============================================================
-- SAMPLE DATA : LinkAllowancesDeductionWithGrade
-- Seeds the 10 AD components shown on-screen for
-- Andhra Pradesh + Grade 1 (mirrors the UI screenshot).
-- ============================================================

-- Resolve StateNo for 'ANDHRA PRADESH' and GradeNo for 'Grade 1'
-- Insert only if sample States and Grades exist.
DECLARE @APStateNo  SMALLINT;
DECLARE @Grade1No   INT;

SELECT @APStateNo = StateNo FROM dbo.State WHERE StateName = 'Andhra Pradesh';
SELECT @Grade1No  = GradeNo FROM dbo.Grade  WHERE GradeName = 'GRADE 1';

-- Insert sample data only when both FK rows are present
IF @APStateNo IS NOT NULL AND @Grade1No IS NOT NULL
BEGIN
    -- Resolve AllowanceDeductionNo values
    DECLARE @EPF_No  INT; SELECT @EPF_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'EPF Employee';
    DECLARE @ESI_No  INT; SELECT @ESI_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'ESI Employee';
    DECLARE @HRA_No  INT; SELECT @HRA_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'HRA';
    DECLARE @CA_No   INT; SELECT @CA_No   = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'Conveyance Allowance';
    DECLARE @OA_No   INT; SELECT @OA_No   = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'Other Allowance';
    DECLARE @BA_No   INT; SELECT @BA_No   = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'Bonus Advance';
    DECLARE @CCA_No  INT;
    DECLARE @TDS_No  INT; SELECT @TDS_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'TDS Deduction';
    DECLARE @LWF_No  INT; SELECT @LWF_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'Labour Welfare Fund';
    DECLARE @ARR_No  INT; SELECT @ARR_No  = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'Arrear';

    -- CCA not in base sample data — insert it if missing
    IF NOT EXISTS (SELECT 1 FROM dbo.AllowanceDeduction WHERE ADName = 'CCA')
    BEGIN
        INSERT INTO dbo.AllowanceDeduction (ADName, AccountType, RoundingMode, ForPresentDays, DisplayOrder)
        VALUES ('CCA','A','Normal Rounding',0,11);
    END
    SELECT @CCA_No = AllowanceDeductionNo FROM dbo.AllowanceDeduction WHERE ADName = 'CCA';

    -- Insert mappings (mirrors the 10-row screenshot exactly)
    INSERT INTO dbo.LinkAllowancesDeductionWithGrade
        (StateNo, GradeNo, AllowanceDeductionNo, CalculationOn, SelectType, PercentageValue, FixedValue, VaryOnDays, DisplayOrder)
    SELECT v.StateNo, v.GradeNo, v.ADNO, v.CalcOn, v.SType, v.Pct, v.Fixed, v.VOD, v.DO
    FROM (VALUES
        -- S.No | Component         | CalcOn                  | Type       | Pct   | Fixed | VaryOnDays | Order
        (@APStateNo, @Grade1No, @EPF_No, 'Percentage On Amount', 'Percentage', 12.00, NULL, 1, 1),
        (@APStateNo, @Grade1No, @ESI_No, 'Percentage On Amount', 'Percentage',  0.75, NULL, 0, 2),
        (@APStateNo, @Grade1No, @HRA_No, 'Percentage On Amount', 'Percentage', 40.00, NULL, 1, 3),
        (@APStateNo, @Grade1No, @CA_No,  'Percentage On Amount', 'Percentage', 10.00, NULL, 1, 4),
        (@APStateNo, @Grade1No, @OA_No,  'Percentage On Amount', 'Percentage', 10.00, NULL, 1, 5),
        (@APStateNo, @Grade1No, @BA_No,  'Percentage On Amount', 'Percentage',  8.33, NULL, 1, 6),
        (@APStateNo, @Grade1No, @CCA_No, 'Percentage On Amount', 'Percentage',  5.00, NULL, 0, 7),
        (@APStateNo, @Grade1No, @TDS_No, 'Percentage On Amount', 'Percentage', 10.00, NULL, 1, 8),
        (@APStateNo, @Grade1No, @LWF_No, 'Percentage On Amount', 'Percentage',  0.20, NULL, 1, 9),
        (@APStateNo, @Grade1No, @ARR_No, 'Percentage On Amount', 'Percentage',  0.00, NULL, 1,10)
    ) AS v(StateNo, GradeNo, ADNO, CalcOn, SType, Pct, Fixed, VOD, DO)
    WHERE v.ADNO IS NOT NULL;

    PRINT 'Sample data inserted into LinkAllowancesDeductionWithGrade.';
END
ELSE
    PRINT 'Skipped sample data — Andhra Pradesh or Grade 1 not found in base tables.';
GO

PRINT '==============================================================';
PRINT 'LinkAllowancesDeductionWithGrade block complete.';
PRINT '==============================================================';
GO

-- ============================================================
-- SECTION : Country
-- Purpose : Master table for countries.  Drives the
--           "Country" screen under System Settings (Add Country
--           / Set Order / Edit / Delete).
--           Also acts as a FK target for dbo.State once the
--           State table is altered below to replace the existing
--           Country NVARCHAR column with a proper FK column.
-- ============================================================

-- ============================================================
-- TABLE : dbo.Country
-- ============================================================
IF OBJECT_ID('dbo.Country','U') IS NOT NULL DROP TABLE dbo.Country;
GO

CREATE TABLE dbo.Country (
    -- ----------------------------------------------------------
    -- Primary Key — surrogate IDENTITY integer
    -- CountryNo is the FK target referenced by dbo.State
    -- ----------------------------------------------------------
    CountryNo           INT           NOT NULL IDENTITY(1,1)
        CONSTRAINT PK_Country PRIMARY KEY CLUSTERED,

    -- ----------------------------------------------------------
    -- CountryGUID — alternate GUID key for API / external use
    -- ----------------------------------------------------------
    CountryGUID         UNIQUEIDENTIFIER NOT NULL
        CONSTRAINT DF_Country_GUID DEFAULT NEWID(),

    -- ----------------------------------------------------------
    -- CountryName — full display name shown on screen listing
    -- and in the "Country Name" dropdown of the Add modal.
    -- Mandatory (*) per the UI.
    -- ----------------------------------------------------------
    CountryName         NVARCHAR(100) NOT NULL,

    -- ----------------------------------------------------------
    -- CountryCode — short code shown in the listing column.
    -- Mandatory (*) per the UI (e.g. IND, AUS, USA, ENG, CND).
    -- Max 5 chars to accommodate ISO 3166-1 alpha-3 codes.
    -- ----------------------------------------------------------
    CountryCode         VARCHAR(5)    NOT NULL,

    -- ----------------------------------------------------------
    -- ISO2Code — ISO 3166-1 alpha-2 code (IN, AU, US, GB, CA …)
    -- Stored separately for international integrations.
    -- ----------------------------------------------------------
    ISO2Code            CHAR(2)       NULL,

    -- ----------------------------------------------------------
    -- ISO3Code — ISO 3166-1 alpha-3 code (IND, AUS, USA …)
    -- ----------------------------------------------------------
    ISO3Code            CHAR(3)       NULL,

    -- ----------------------------------------------------------
    -- PhoneCode — international dialling prefix, e.g. +91, +1
    -- ----------------------------------------------------------
    PhoneCode           VARCHAR(6)    NULL,

    -- ----------------------------------------------------------
    -- CurrencyCode — ISO 4217 currency code (INR, AUD, USD …)
    -- ----------------------------------------------------------
    CurrencyCode        VARCHAR(5)    NULL,

    -- ----------------------------------------------------------
    -- Description — optional free-text notes shown on screen.
    -- ----------------------------------------------------------
    Description         NVARCHAR(500) NULL,

    -- ----------------------------------------------------------
    -- DisplayOrder — controls S.No. sequence on the listing and
    -- the drag-and-drop "Set Country Order" modal.
    -- ----------------------------------------------------------
    DisplayOrder        SMALLINT      NOT NULL
        CONSTRAINT DF_Country_DisplayOrder DEFAULT 99,

    -- ----------------------------------------------------------
    -- Status — 1=Active (shown as ACTIVE badge), 0=Inactive.
    -- Mandatory (*) per the UI; defaults to Active.
    -- ----------------------------------------------------------
    Status              TINYINT       NOT NULL
        CONSTRAINT DF_Country_Status DEFAULT 1,

    -- ----------------------------------------------------------
    -- Audit stamp columns
    -- ----------------------------------------------------------
    CreatedAt           DATETIME2(0)  NOT NULL
        CONSTRAINT DF_Country_CreatedAt DEFAULT GETDATE(),

    UpdatedAt           DATETIME2(0)  NULL,

    CreatedBy           INT           NULL,
    -- FK to dbo.Users.UserNo — set by application layer

    -- ==========================================================
    -- CONSTRAINTS
    -- ==========================================================

    -- Alternate unique key: CountryGUID must be unique
    CONSTRAINT UQ_Country_GUID
        UNIQUE (CountryGUID),

    -- CountryCode must be unique across the table
    CONSTRAINT UQ_Country_Code
        UNIQUE (CountryCode),

    -- CountryName must be unique (no duplicate country names)
    CONSTRAINT UQ_Country_Name
        UNIQUE (CountryName),

    -- ISO codes unique when provided
    CONSTRAINT UQ_Country_ISO2
        UNIQUE (ISO2Code),

    CONSTRAINT UQ_Country_ISO3
        UNIQUE (ISO3Code),

    -- Domain: Status is binary
    CONSTRAINT CK_Country_Status
        CHECK (Status IN (0, 1)),

    -- Domain: DisplayOrder must be positive
    CONSTRAINT CK_Country_DisplayOrder
        CHECK (DisplayOrder > 0),

    -- Domain: ISO2Code exactly 2 uppercase letters when provided
    CONSTRAINT CK_Country_ISO2
        CHECK (ISO2Code IS NULL OR ISO2Code LIKE '[A-Z][A-Z]'),

    -- Domain: ISO3Code exactly 3 uppercase letters when provided
    CONSTRAINT CK_Country_ISO3
        CHECK (ISO3Code IS NULL OR ISO3Code LIKE '[A-Z][A-Z][A-Z]'),

    -- FK: CreatedBy references Users
    CONSTRAINT FK_Country_CreatedBy
        FOREIGN KEY (CreatedBy)
        REFERENCES dbo.Users (UserNo)
        ON DELETE SET NULL
        ON UPDATE NO ACTION
);
GO

-- ============================================================
-- NON-CLUSTERED INDEXES
-- ============================================================

-- Status filter (most common listing query: Status=1)
CREATE NONCLUSTERED INDEX IX_Country_Status
    ON dbo.Country (Status, DisplayOrder);
GO

-- CountryName search / typeahead
CREATE NONCLUSTERED INDEX IX_Country_Name
    ON dbo.Country (CountryName);
GO

PRINT 'Table dbo.Country created with all constraints and indexes.';
GO

-- ============================================================
-- POST-SETUP : Wire CountryNo FK on dbo.State, dbo.Division,
--              and dbo.EmployeeAddress now that dbo.Country exists.
-- The CREATE TABLE statements above defined CountryNo as a plain
-- INT NULL (no FK yet because Country didn't exist at that point).
-- Here we add the FK constraint, index, and back-fill seed rows.
-- ============================================================

-- ── dbo.State ───────────────────────────────────────────────
IF NOT EXISTS (
    SELECT 1 FROM sys.foreign_keys
    WHERE name = 'FK_State_Country' AND parent_object_id = OBJECT_ID('dbo.State')
)
BEGIN
    ALTER TABLE dbo.State
        ADD CONSTRAINT FK_State_Country
            FOREIGN KEY (CountryNo) REFERENCES dbo.Country (CountryNo)
            ON DELETE NO ACTION ON UPDATE CASCADE;
    PRINT 'FK_State_Country added to dbo.State.';
END
ELSE
    PRINT 'FK_State_Country already exists — skipping.';
GO

IF NOT EXISTS (
    SELECT 1 FROM sys.indexes
    WHERE object_id = OBJECT_ID('dbo.State') AND name = 'IX_State_CountryNo'
)
    CREATE NONCLUSTERED INDEX IX_State_CountryNo ON dbo.State (CountryNo);
GO

-- Back-fill CountryNo for the original 5 seed rows (StateNo 1-5 = India)
UPDATE dbo.State
SET    CountryNo = (SELECT CountryNo FROM dbo.Country WHERE ISO2Code = 'IN')
WHERE  StateNo IN (1,2,3,4,5)
  AND  CountryNo IS NULL;
GO

PRINT 'dbo.State — FK, index, and back-fill complete.';
GO

-- ── dbo.Division ────────────────────────────────────────────
IF NOT EXISTS (
    SELECT 1 FROM sys.foreign_keys
    WHERE name = 'FK_Div_Country' AND parent_object_id = OBJECT_ID('dbo.Division')
)
BEGIN
    ALTER TABLE dbo.Division
        ADD CONSTRAINT FK_Div_Country
            FOREIGN KEY (CountryNo) REFERENCES dbo.Country (CountryNo)
            ON DELETE NO ACTION ON UPDATE CASCADE;
    PRINT 'FK_Div_Country added to dbo.Division.';
END
ELSE
    PRINT 'FK_Div_Country already exists — skipping.';
GO

IF NOT EXISTS (
    SELECT 1 FROM sys.indexes
    WHERE object_id = OBJECT_ID('dbo.Division') AND name = 'IX_Div_CountryNo'
)
    CREATE NONCLUSTERED INDEX IX_Div_CountryNo ON dbo.Division (CountryNo);
GO

-- Back-fill: derive CountryNo from the linked State row
UPDATE dv
SET    dv.CountryNo = s.CountryNo
FROM   dbo.Division dv
INNER JOIN dbo.State s ON s.StateNo = dv.StateNo
WHERE  dv.CountryNo IS NULL AND s.CountryNo IS NOT NULL;
-- Any remaining rows (no State set) default to India
UPDATE dbo.Division
SET    CountryNo = (SELECT CountryNo FROM dbo.Country WHERE ISO2Code = 'IN')
WHERE  CountryNo IS NULL;
GO

PRINT 'dbo.Division — FK, index, and back-fill complete.';
GO

-- ── dbo.EmployeeAddress ──────────────────────────────────────
IF NOT EXISTS (
    SELECT 1 FROM sys.foreign_keys
    WHERE name = 'FK_EmpAddr_Country' AND parent_object_id = OBJECT_ID('dbo.EmployeeAddress')
)
BEGIN
    ALTER TABLE dbo.EmployeeAddress
        ADD CONSTRAINT FK_EmpAddr_Country
            FOREIGN KEY (CountryNo) REFERENCES dbo.Country (CountryNo)
            ON DELETE NO ACTION ON UPDATE CASCADE;
    PRINT 'FK_EmpAddr_Country added to dbo.EmployeeAddress.';
END
ELSE
    PRINT 'FK_EmpAddr_Country already exists — skipping.';
GO

IF NOT EXISTS (
    SELECT 1 FROM sys.indexes
    WHERE object_id = OBJECT_ID('dbo.EmployeeAddress') AND name = 'IX_EmpAddr_CountryNo'
)
    CREATE NONCLUSTERED INDEX IX_EmpAddr_CountryNo ON dbo.EmployeeAddress (CountryNo);
GO

-- Back-fill: derive CountryNo from linked State row
UPDATE ea
SET    ea.CountryNo = s.CountryNo
FROM   dbo.EmployeeAddress ea
INNER JOIN dbo.State s ON s.StateNo = ea.StateNo
WHERE  ea.CountryNo IS NULL AND s.CountryNo IS NOT NULL;
-- Remaining rows (no State) default to India
UPDATE dbo.EmployeeAddress
SET    CountryNo = (SELECT CountryNo FROM dbo.Country WHERE ISO2Code = 'IN')
WHERE  CountryNo IS NULL;
GO

PRINT 'dbo.EmployeeAddress — FK, index, and back-fill complete.';
GO

-- ============================================================
-- TRIGGER 1 : dbo.TR_Country_Timestamps
-- Purpose   : Auto-set UpdatedAt on UPDATE; guard CreatedAt
--             on INSERT.
-- ============================================================
IF OBJECT_ID('dbo.TR_Country_Timestamps','TR') IS NOT NULL
    DROP TRIGGER dbo.TR_Country_Timestamps;
GO

CREATE TRIGGER dbo.TR_Country_Timestamps
ON dbo.Country
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM deleted)   -- INSERT
    BEGIN
        -- Ensure CreatedAt is never NULL (belt-and-braces)
        UPDATE c
        SET    c.CreatedAt = ISNULL(c.CreatedAt, GETDATE())
        FROM   dbo.Country c
        INNER JOIN inserted i ON c.CountryNo = i.CountryNo;
    END
    ELSE                                     -- UPDATE
    BEGIN
        UPDATE c
        SET    c.UpdatedAt = GETDATE()
        FROM   dbo.Country c
        INNER JOIN inserted i ON c.CountryNo = i.CountryNo;
        -- Note: Country text column has been removed from dbo.State, dbo.Division,
        -- and dbo.EmployeeAddress. All tables now reference dbo.Country via CountryNo FK.
        -- ON UPDATE CASCADE on FK_State_Country/FK_Div_Country/FK_EmpAddr_Country
        -- keeps referential integrity automatically; no text-cascade needed.
    END
END;
GO

-- ============================================================
-- TRIGGER 2 : dbo.TR_Country_Audit
-- Purpose   : Write a row to audit.AuditLog for every
--             INSERT, UPDATE, and DELETE on dbo.Country.
-- ============================================================
IF OBJECT_ID('dbo.TR_Country_Audit','TR') IS NOT NULL
    DROP TRIGGER dbo.TR_Country_Audit;
GO

CREATE TRIGGER dbo.TR_Country_Audit
ON dbo.Country
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Action CHAR(1);
    IF EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted)
        SET @Action = 'U';
    ELSE IF EXISTS (SELECT 1 FROM inserted)
        SET @Action = 'I';
    ELSE
        SET @Action = 'D';

    -- Helper: readable row summary
    -- Format: Name=x; Code=x; ISO2=x; Status=x; Order=x

    IF @Action = 'I'
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Country',
            CAST(i.CountryNo AS NVARCHAR(50)),
            'I',
            NULL,
            N'Name='   + ISNULL(i.CountryName,'')
            + N'; Code='  + ISNULL(i.CountryCode,'')
            + N'; ISO2='  + ISNULL(i.ISO2Code,'')
            + N'; Status='+ CAST(i.Status AS NVARCHAR)
            + N'; Order=' + CAST(i.DisplayOrder AS NVARCHAR),
            SYSDATETIME(),
            N'System Settings – Country'
        FROM inserted i;
    END

    ELSE IF @Action = 'D'
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Country',
            CAST(d.CountryNo AS NVARCHAR(50)),
            'D',
            N'Name='   + ISNULL(d.CountryName,'')
            + N'; Code='  + ISNULL(d.CountryCode,'')
            + N'; ISO2='  + ISNULL(d.ISO2Code,'')
            + N'; Status='+ CAST(d.Status AS NVARCHAR),
            NULL,
            SYSDATETIME(),
            N'System Settings – Country'
        FROM deleted d;
    END

    ELSE  -- UPDATE
    BEGIN
        INSERT INTO audit.AuditLog
            (SchemaName, TableName, EntityID, Action,
             OldValue, NewValue, ChangedAt, AppModule)
        SELECT
            'dbo', 'Country',
            CAST(i.CountryNo AS NVARCHAR(50)),
            'U',
            N'Name='    + ISNULL(d.CountryName,'')
            + N'; Code='   + ISNULL(d.CountryCode,'')
            + N'; Status=' + CAST(d.Status AS NVARCHAR)
            + N'; Order='  + CAST(d.DisplayOrder AS NVARCHAR),
            N'Name='    + ISNULL(i.CountryName,'')
            + N'; Code='   + ISNULL(i.CountryCode,'')
            + N'; Status=' + CAST(i.Status AS NVARCHAR)
            + N'; Order='  + CAST(i.DisplayOrder AS NVARCHAR),
            SYSDATETIME(),
            N'System Settings – Country'
        FROM inserted i
        INNER JOIN deleted d ON i.CountryNo = d.CountryNo;
    END
END;
GO

PRINT 'Triggers TR_Country_Timestamps and TR_Country_Audit created.';
GO

-- ============================================================
-- STORED PROCEDURES : Country
-- ============================================================

-- ------------------------------------------------------------
-- usp_Country_Insert
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_Insert','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_Insert;
GO

CREATE PROCEDURE dbo.usp_Country_Insert
    @CountryName    NVARCHAR(100),
    @CountryCode    VARCHAR(5),
    @ISO2Code       CHAR(2)       = NULL,
    @ISO3Code       CHAR(3)       = NULL,
    @PhoneCode      VARCHAR(6)    = NULL,
    @CurrencyCode   VARCHAR(5)    = NULL,
    @Description    NVARCHAR(500) = NULL,
    @DisplayOrder   SMALLINT      = 99,
    @Status         TINYINT       = 1,
    @CreatedBy      INT           = NULL,
    @NewCountryNo   INT           OUTPUT
AS
/*
  Purpose : Create a new country record.
  Validates uniqueness of CountryName and CountryCode before INSERT.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (SELECT 1 FROM dbo.Country WHERE CountryName = @CountryName)
            THROW 61001, 'CountryName already exists.', 1;

        IF EXISTS (SELECT 1 FROM dbo.Country WHERE CountryCode = @CountryCode)
            THROW 61002, 'CountryCode already exists.', 1;

        IF @ISO2Code IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.Country WHERE ISO2Code = @ISO2Code)
            THROW 61003, 'ISO2Code already exists.', 1;

        IF @Status NOT IN (0,1)
            THROW 61004, 'Status must be 0 (Inactive) or 1 (Active).', 1;

        INSERT INTO dbo.Country
            (CountryName, CountryCode, ISO2Code, ISO3Code, PhoneCode,
             CurrencyCode, Description, DisplayOrder, Status, CreatedBy)
        VALUES
            (@CountryName, @CountryCode, @ISO2Code, @ISO3Code, @PhoneCode,
             @CurrencyCode, @Description, @DisplayOrder, @Status, @CreatedBy);

        SET @NewCountryNo = SCOPE_IDENTITY();

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Country_Update
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_Update','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_Update;
GO

CREATE PROCEDURE dbo.usp_Country_Update
    @CountryNo      INT,
    @CountryName    NVARCHAR(100) = NULL,
    @CountryCode    VARCHAR(5)    = NULL,
    @ISO2Code       CHAR(2)       = NULL,
    @ISO3Code       CHAR(3)       = NULL,
    @PhoneCode      VARCHAR(6)    = NULL,
    @CurrencyCode   VARCHAR(5)    = NULL,
    @Description    NVARCHAR(500) = NULL,
    @DisplayOrder   SMALLINT      = NULL,
    @Status         TINYINT       = NULL
AS
/*
  Purpose : Partial update — only supplied (non-NULL) parameters change.
  The timestamp trigger handles UpdatedAt. ON UPDATE CASCADE on the FK
  constraints (FK_State_Country, FK_Div_Country, FK_EmpAddr_Country)
  keeps all CountryNo references consistent automatically.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo)
            THROW 61010, 'CountryNo not found.', 1;

        IF @CountryName IS NOT NULL AND EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryName = @CountryName AND CountryNo <> @CountryNo)
            THROW 61011, 'CountryName already used by another record.', 1;

        IF @CountryCode IS NOT NULL AND EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryCode = @CountryCode AND CountryNo <> @CountryNo)
            THROW 61012, 'CountryCode already used by another record.', 1;

        UPDATE dbo.Country
        SET
            CountryName  = ISNULL(@CountryName,  CountryName),
            CountryCode  = ISNULL(@CountryCode,  CountryCode),
            ISO2Code     = ISNULL(@ISO2Code,     ISO2Code),
            ISO3Code     = ISNULL(@ISO3Code,     ISO3Code),
            PhoneCode    = ISNULL(@PhoneCode,    PhoneCode),
            CurrencyCode = ISNULL(@CurrencyCode, CurrencyCode),
            Description  = ISNULL(@Description,  Description),
            DisplayOrder = ISNULL(@DisplayOrder, DisplayOrder),
            Status       = ISNULL(@Status,       Status)
            -- UpdatedAt handled by TR_Country_Timestamps trigger
        WHERE CountryNo = @CountryNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Country_Delete  (soft-delete)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_Delete','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_Delete;
GO

CREATE PROCEDURE dbo.usp_Country_Delete
    @CountryNo INT
AS
/*
  Purpose : Soft-delete a country (Status = 0).
  Blocks if active States are linked to this country.
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo)
            THROW 61020, 'CountryNo not found.', 1;

        IF EXISTS (SELECT 1 FROM dbo.State WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 61021, 'Cannot deactivate — active States are linked to this Country.', 1;

        UPDATE dbo.Country SET Status = 0 WHERE CountryNo = @CountryNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ------------------------------------------------------------
-- usp_Country_GetByID
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_GetByID','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_GetByID;
GO

CREATE PROCEDURE dbo.usp_Country_GetByID
    @CountryNo INT
AS
/*  Purpose : Fetch one country with linked state count.  */
BEGIN
    SET NOCOUNT ON;
    SELECT
        c.CountryNo, c.CountryGUID, c.CountryName, c.CountryCode,
        c.ISO2Code, c.ISO3Code, c.PhoneCode, c.CurrencyCode,
        c.Description, c.DisplayOrder, c.Status,
        c.CreatedAt, c.UpdatedAt, c.CreatedBy,
        (SELECT COUNT(*) FROM dbo.State s WHERE s.CountryNo = c.CountryNo) AS StateCount
    FROM dbo.Country c
    WHERE c.CountryNo = @CountryNo;
END;
GO

-- ------------------------------------------------------------
-- usp_Country_List  (paged listing — powers the grid screen)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_List','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_List;
GO

CREATE PROCEDURE dbo.usp_Country_List
    @Status       TINYINT       = 1,      -- 1=Active, 0=Inactive, NULL=all
    @SearchTerm   NVARCHAR(100) = NULL,   -- partial match on CountryName or CountryCode
    @PageNumber   INT           = 1,
    @PageSize     INT           = 50,
    @TotalCount   INT           OUTPUT
AS
/*
  Purpose : Paged, searchable listing that backs the Country grid.
            Ordered by DisplayOrder then CountryName — matches the
            drag-and-drop Set Order modal sequence.
*/
BEGIN
    SET NOCOUNT ON;

    SELECT @TotalCount = COUNT(*)
    FROM   dbo.Country
    WHERE  (@Status     IS NULL OR Status     = @Status)
      AND  (@SearchTerm IS NULL
            OR CountryName LIKE '%' + @SearchTerm + '%'
            OR CountryCode LIKE '%' + @SearchTerm + '%');

    SELECT
        ROW_NUMBER() OVER (ORDER BY DisplayOrder, CountryName) AS SNo,
        CountryNo, CountryName, CountryCode, ISO2Code, ISO3Code,
        PhoneCode, CurrencyCode, Description, DisplayOrder, Status,
        CreatedAt, UpdatedAt
    FROM  dbo.Country
    WHERE (@Status     IS NULL OR Status     = @Status)
      AND (@SearchTerm IS NULL
           OR CountryName LIKE '%' + @SearchTerm + '%'
           OR CountryCode LIKE '%' + @SearchTerm + '%')
    ORDER BY DisplayOrder, CountryName
    OFFSET (@PageNumber - 1) * @PageSize ROWS
    FETCH NEXT @PageSize ROWS ONLY;
END;
GO

-- ------------------------------------------------------------
-- usp_Country_SetOrder  (powers "Set Country Order" modal)
-- ------------------------------------------------------------
IF OBJECT_ID('dbo.usp_Country_SetOrder','P') IS NOT NULL
    DROP PROCEDURE dbo.usp_Country_SetOrder;
GO

CREATE PROCEDURE dbo.usp_Country_SetOrder
    @OrderJSON NVARCHAR(MAX)
    -- JSON array: [{"CountryNo":1,"DisplayOrder":1}, ...]
AS
/*
  Purpose : Bulk-update DisplayOrder from the drag-and-drop
            "Set Country Order" modal (Save button).
*/
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE c
        SET    c.DisplayOrder = j.DisplayOrder
        FROM   dbo.Country c
        INNER JOIN OPENJSON(@OrderJSON)
            WITH (
                CountryNo    INT      '$.CountryNo',
                DisplayOrder SMALLINT '$.DisplayOrder'
            ) j ON j.CountryNo = c.CountryNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

