-- ============================================================
-- SECTION : Stored Procedures — dbo.State
-- ============================================================

-- ── usp_State_Insert ─────────────────────────────────────────
IF OBJECT_ID('dbo.usp_State_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_State_Insert;
GO
CREATE PROCEDURE dbo.usp_State_Insert
    @StateNo          SMALLINT,
    @StateName        NVARCHAR(80),
    @StateCodeDisplay VARCHAR(10),
    @StateCodeSystem  VARCHAR(10),
    @CountryNo        INT,
    @Description      NVARCHAR(200) = NULL,
    @Status           TINYINT       = 1,
    @CreatedBy        INT           = NULL
AS
/*  Purpose : Insert a new State row.  CountryNo is now a proper FK.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (SELECT 1 FROM dbo.State WHERE StateNo = @StateNo)
            THROW 60001, 'StateNo already exists.', 1;
        IF EXISTS (SELECT 1 FROM dbo.State WHERE StateCodeSystem = @StateCodeSystem)
            THROW 60002, 'StateCodeSystem already used by another record.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 60003, 'CountryNo not found or inactive.', 1;

        INSERT INTO dbo.State
            (StateNo, StateName, StateCodeDisplay, StateCodeSystem, CountryNo, Description, Status)
        VALUES
            (@StateNo, @StateName, @StateCodeDisplay, @StateCodeSystem, @CountryNo, @Description, @Status);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_State_Update ─────────────────────────────────────────
IF OBJECT_ID('dbo.usp_State_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_State_Update;
GO
CREATE PROCEDURE dbo.usp_State_Update
    @StateNo          SMALLINT,
    @StateName        NVARCHAR(80)  = NULL,
    @StateCodeDisplay VARCHAR(10)   = NULL,
    @StateCodeSystem  VARCHAR(10)   = NULL,
    @CountryNo        INT           = NULL,
    @Description      NVARCHAR(200) = NULL,
    @Status           TINYINT       = NULL
AS
/*  Purpose : Partial update — only non-NULL parameters are applied.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.State WHERE StateNo = @StateNo)
            THROW 60010, 'StateNo not found.', 1;
        IF @StateCodeSystem IS NOT NULL AND EXISTS (
            SELECT 1 FROM dbo.State WHERE StateCodeSystem = @StateCodeSystem AND StateNo <> @StateNo)
            THROW 60011, 'StateCodeSystem already used by another record.', 1;
        IF @CountryNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 60012, 'CountryNo not found or inactive.', 1;

        UPDATE dbo.State
        SET StateName        = ISNULL(@StateName,        StateName),
            StateCodeDisplay = ISNULL(@StateCodeDisplay, StateCodeDisplay),
            StateCodeSystem  = ISNULL(@StateCodeSystem,  StateCodeSystem),
            CountryNo        = ISNULL(@CountryNo,        CountryNo),
            Description      = ISNULL(@Description,      Description),
            Status           = ISNULL(@Status,           Status)
        WHERE StateNo = @StateNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_State_Delete ─────────────────────────────────────────
IF OBJECT_ID('dbo.usp_State_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_State_Delete;
GO
CREATE PROCEDURE dbo.usp_State_Delete
    @StateNo SMALLINT
AS
/*  Purpose : Soft-delete.  Blocks if active Cities are linked.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.State WHERE StateNo = @StateNo)
            THROW 60020, 'StateNo not found.', 1;
        IF EXISTS (
            SELECT 1 FROM dbo.City WHERE StateNo = @StateNo AND Status = 1)
            THROW 60021, 'Cannot deactivate — active Cities are linked to this State.', 1;

        UPDATE dbo.State SET Status = 0 WHERE StateNo = @StateNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_State_GetByID ─────────────────────────────────────────
IF OBJECT_ID('dbo.usp_State_GetByID','P') IS NOT NULL DROP PROCEDURE dbo.usp_State_GetByID;
GO
CREATE PROCEDURE dbo.usp_State_GetByID
    @StateNo SMALLINT
AS
/*  Purpose : Return a single State row with Country name joined.  */
BEGIN
    SET NOCOUNT ON;
    SELECT s.StateNo, s.StateName, s.StateCodeDisplay, s.StateCodeSystem,
           s.CountryNo, c.CountryName, c.CountryCode,
           s.Description, s.Status
    FROM   dbo.State s
    LEFT JOIN dbo.Country c ON c.CountryNo = s.CountryNo
    WHERE  s.StateNo = @StateNo;
END;
GO

-- ── usp_State_List ────────────────────────────────────────────
IF OBJECT_ID('dbo.usp_State_List','P') IS NOT NULL DROP PROCEDURE dbo.usp_State_List;
GO
CREATE PROCEDURE dbo.usp_State_List
    @CountryNo   INT           = NULL,   -- filter by country
    @Status      TINYINT       = NULL,   -- 1=Active, 0=Inactive, NULL=all
    @SearchTerm  NVARCHAR(100) = NULL,   -- partial name / code search
    @PageNo      INT           = 1,
    @PageSize    INT           = 20,
    @TotalCount  INT           OUTPUT
AS
/*  Purpose : Paged, filterable list of States with Country name.  */
BEGIN
    SET NOCOUNT ON;

    SELECT @TotalCount = COUNT(*)
    FROM   dbo.State s
    WHERE  (@CountryNo  IS NULL OR s.CountryNo        = @CountryNo)
      AND  (@Status     IS NULL OR s.Status            = @Status)
      AND  (@SearchTerm IS NULL OR s.StateName   LIKE '%' + @SearchTerm + '%'
                                OR s.StateCodeDisplay  LIKE '%' + @SearchTerm + '%');

    SELECT s.StateNo, s.StateName, s.StateCodeDisplay, s.StateCodeSystem,
           s.CountryNo, c.CountryName, c.CountryCode,
           s.Description, s.Status
    FROM   dbo.State s
    LEFT JOIN dbo.Country c ON c.CountryNo = s.CountryNo
    WHERE  (@CountryNo  IS NULL OR s.CountryNo        = @CountryNo)
      AND  (@Status     IS NULL OR s.Status            = @Status)
      AND  (@SearchTerm IS NULL OR s.StateName   LIKE '%' + @SearchTerm + '%'
                                OR s.StateCodeDisplay  LIKE '%' + @SearchTerm + '%')
    ORDER BY c.CountryName, s.StateName
    OFFSET (@PageNo - 1) * @PageSize ROWS
    FETCH  NEXT @PageSize ROWS ONLY;
END;
GO

PRINT 'Stored procedures for State created successfully.';
GO

-- ============================================================
-- SECTION : Stored Procedures — dbo.Division
-- ============================================================

-- ── usp_Division_Insert ──────────────────────────────────────
IF OBJECT_ID('dbo.usp_Division_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_Division_Insert;
GO
CREATE PROCEDURE dbo.usp_Division_Insert
    @DivisionName      NVARCHAR(100),
    @DivisionShortName VARCHAR(5),
    @OfficeLocation    NVARCHAR(200) = NULL,
    @OfficeAddress     NVARCHAR(500) = NULL,
    @CityNo            SMALLINT      = NULL,
    @StateNo           SMALLINT      = NULL,
    @CountryNo         INT           = NULL,
    @InChargeCode      VARCHAR(20)   = NULL,
    @Status            TINYINT       = 1,
    @CreatedBy         INT           = NULL,
    @NewDivisionNo     INT           OUTPUT
AS
/*  Purpose : Insert a new Division/office-location row.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (SELECT 1 FROM dbo.Division WHERE DivisionShortName = @DivisionShortName)
            THROW 61501, 'DivisionShortName already exists.', 1;
        IF @CountryNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 61502, 'CountryNo not found or inactive.', 1;

        INSERT INTO dbo.Division
            (DivisionName, DivisionShortName, OfficeLocation, OfficeAddress,
             CityNo, StateNo, CountryNo, InChargeCode, Status, CreatedAt)
        VALUES
            (@DivisionName, @DivisionShortName, @OfficeLocation, @OfficeAddress,
             @CityNo, @StateNo, @CountryNo, @InChargeCode, @Status, GETDATE());

        SET @NewDivisionNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_Division_Update ──────────────────────────────────────
IF OBJECT_ID('dbo.usp_Division_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_Division_Update;
GO
CREATE PROCEDURE dbo.usp_Division_Update
    @DivisionNo        INT,
    @DivisionName      NVARCHAR(100) = NULL,
    @DivisionShortName VARCHAR(5)    = NULL,
    @OfficeLocation    NVARCHAR(200) = NULL,
    @OfficeAddress     NVARCHAR(500) = NULL,
    @CityNo            SMALLINT      = NULL,
    @StateNo           SMALLINT      = NULL,
    @CountryNo         INT           = NULL,
    @InChargeCode      VARCHAR(20)   = NULL,
    @Status            TINYINT       = NULL
AS
/*  Purpose : Partial update of Division.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Division WHERE DivisionNo = @DivisionNo)
            THROW 61510, 'DivisionNo not found.', 1;
        IF @DivisionShortName IS NOT NULL AND EXISTS (
            SELECT 1 FROM dbo.Division WHERE DivisionShortName = @DivisionShortName AND DivisionNo <> @DivisionNo)
            THROW 61511, 'DivisionShortName already used by another record.', 1;
        IF @CountryNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 61512, 'CountryNo not found or inactive.', 1;

        UPDATE dbo.Division
        SET DivisionName      = ISNULL(@DivisionName,      DivisionName),
            DivisionShortName = ISNULL(@DivisionShortName, DivisionShortName),
            OfficeLocation    = ISNULL(@OfficeLocation,    OfficeLocation),
            OfficeAddress     = ISNULL(@OfficeAddress,     OfficeAddress),
            CityNo            = ISNULL(@CityNo,            CityNo),
            StateNo           = ISNULL(@StateNo,           StateNo),
            CountryNo         = ISNULL(@CountryNo,         CountryNo),
            InChargeCode      = ISNULL(@InChargeCode,      InChargeCode),
            Status            = ISNULL(@Status,            Status),
            UpdatedAt         = GETDATE()
        WHERE DivisionNo = @DivisionNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_Division_Delete ──────────────────────────────────────
IF OBJECT_ID('dbo.usp_Division_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_Division_Delete;
GO
CREATE PROCEDURE dbo.usp_Division_Delete
    @DivisionNo INT
AS
/*  Purpose : Soft-delete.  Blocks if active Employees are assigned.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Division WHERE DivisionNo = @DivisionNo)
            THROW 61520, 'DivisionNo not found.', 1;
        IF EXISTS (
            SELECT 1 FROM dbo.Employee WHERE DivisionNo = @DivisionNo AND Status = 1)
            THROW 61521, 'Cannot deactivate — active Employees are assigned to this Division.', 1;

        UPDATE dbo.Division SET Status = 0 WHERE DivisionNo = @DivisionNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_Division_GetByID ─────────────────────────────────────
IF OBJECT_ID('dbo.usp_Division_GetByID','P') IS NOT NULL DROP PROCEDURE dbo.usp_Division_GetByID;
GO
CREATE PROCEDURE dbo.usp_Division_GetByID
    @DivisionNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT dv.DivisionNo, dv.DivisionName, dv.DivisionShortName,
           dv.OfficeLocation, dv.OfficeAddress,
           dv.CityNo,    ci.CityName,
           dv.StateNo,   s.StateName,
           dv.CountryNo, co.CountryName, co.CountryCode,
           dv.InChargeHeadNo, dv.InChargeCode, dv.Status,
           dv.CreatedAt, dv.UpdatedAt
    FROM   dbo.Division dv
    LEFT JOIN dbo.City    ci ON ci.CityNo    = dv.CityNo
    LEFT JOIN dbo.State   s  ON s.StateNo    = dv.StateNo
    LEFT JOIN dbo.Country co ON co.CountryNo = dv.CountryNo
    WHERE  dv.DivisionNo = @DivisionNo;
END;
GO

-- ── usp_Division_List ────────────────────────────────────────
IF OBJECT_ID('dbo.usp_Division_List','P') IS NOT NULL DROP PROCEDURE dbo.usp_Division_List;
GO
CREATE PROCEDURE dbo.usp_Division_List
    @CountryNo   INT           = NULL,
    @StateNo     SMALLINT      = NULL,
    @Status      TINYINT       = NULL,
    @SearchTerm  NVARCHAR(100) = NULL,
    @PageNo      INT           = 1,
    @PageSize    INT           = 20,
    @TotalCount  INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT @TotalCount = COUNT(*)
    FROM   dbo.Division dv
    WHERE  (@CountryNo  IS NULL OR dv.CountryNo = @CountryNo)
      AND  (@StateNo    IS NULL OR dv.StateNo   = @StateNo)
      AND  (@Status     IS NULL OR dv.Status    = @Status)
      AND  (@SearchTerm IS NULL OR dv.DivisionName      LIKE '%' + @SearchTerm + '%'
                                OR dv.DivisionShortName LIKE '%' + @SearchTerm + '%'
                                OR dv.OfficeLocation    LIKE '%' + @SearchTerm + '%');

    SELECT dv.DivisionNo, dv.DivisionName, dv.DivisionShortName,
           dv.OfficeLocation, dv.OfficeAddress,
           dv.CityNo,    ci.CityName,
           dv.StateNo,   s.StateName,
           dv.CountryNo, co.CountryName, co.CountryCode,
           dv.InChargeHeadNo, dv.InChargeCode, dv.Status,
           dv.CreatedAt, dv.UpdatedAt
    FROM   dbo.Division dv
    LEFT JOIN dbo.City    ci ON ci.CityNo    = dv.CityNo
    LEFT JOIN dbo.State   s  ON s.StateNo    = dv.StateNo
    LEFT JOIN dbo.Country co ON co.CountryNo = dv.CountryNo
    WHERE  (@CountryNo  IS NULL OR dv.CountryNo = @CountryNo)
      AND  (@StateNo    IS NULL OR dv.StateNo   = @StateNo)
      AND  (@Status     IS NULL OR dv.Status    = @Status)
      AND  (@SearchTerm IS NULL OR dv.DivisionName      LIKE '%' + @SearchTerm + '%'
                                OR dv.DivisionShortName LIKE '%' + @SearchTerm + '%'
                                OR dv.OfficeLocation    LIKE '%' + @SearchTerm + '%')
    ORDER BY co.CountryName, s.StateName, dv.DivisionName
    OFFSET (@PageNo - 1) * @PageSize ROWS
    FETCH  NEXT @PageSize ROWS ONLY;
END;
GO

