-- ── usp_EmpAddr_Upsert ───────────────────────────────────────
-- Handles both INSERT (new address) and UPDATE (edit existing).
IF OBJECT_ID('dbo.usp_EmpAddr_Upsert','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpAddr_Upsert;
GO
CREATE PROCEDURE dbo.usp_EmpAddr_Upsert
    @EmployeeNo  INT,
    @AddressType VARCHAR(10),   -- 'Permanent' | 'Local'
    @AddressLine1 NVARCHAR(200),
    @AddressLine2 NVARCHAR(200) = NULL,
    @CityNo      SMALLINT       = NULL,
    @StateNo     SMALLINT       = NULL,
    @CountryNo   INT            = NULL,
    @Pincode     VARCHAR(10)    = NULL,
    @AddressNo   INT            OUTPUT   -- returns existing or new AddressNo
AS
/*  Purpose : Insert or update an employee address row.
              One Permanent + one Local address allowed per employee.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeNo = @EmployeeNo)
            THROW 62001, 'EmployeeNo not found.', 1;
        IF @AddressType NOT IN ('Permanent','Local')
            THROW 62002, 'AddressType must be Permanent or Local.', 1;
        IF @CountryNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.Country WHERE CountryNo = @CountryNo AND Status = 1)
            THROW 62003, 'CountryNo not found or inactive.', 1;

        IF EXISTS (
            SELECT 1 FROM dbo.EmployeeAddress
            WHERE EmployeeNo = @EmployeeNo AND AddressType = @AddressType
        )
        BEGIN
            -- UPDATE path
            UPDATE dbo.EmployeeAddress
            SET AddressLine1 = @AddressLine1,
                AddressLine2 = ISNULL(@AddressLine2, AddressLine2),
                CityNo       = ISNULL(@CityNo,       CityNo),
                StateNo      = ISNULL(@StateNo,      StateNo),
                CountryNo    = ISNULL(@CountryNo,    CountryNo),
                Pincode      = ISNULL(@Pincode,      Pincode),
                UpdatedAt    = GETDATE()
            WHERE EmployeeNo = @EmployeeNo AND AddressType = @AddressType;

            SELECT @AddressNo = AddressNo
            FROM   dbo.EmployeeAddress
            WHERE  EmployeeNo = @EmployeeNo AND AddressType = @AddressType;
        END
        ELSE
        BEGIN
            -- INSERT path
            INSERT INTO dbo.EmployeeAddress
                (EmployeeNo, AddressType, AddressLine1, AddressLine2,
                 CityNo, StateNo, CountryNo, Pincode, CreatedAt)
            VALUES
                (@EmployeeNo, @AddressType, @AddressLine1, @AddressLine2,
                 @CityNo, @StateNo, @CountryNo, @Pincode, GETDATE());

            SET @AddressNo = SCOPE_IDENTITY();
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_EmpAddr_Delete ───────────────────────────────────────
IF OBJECT_ID('dbo.usp_EmpAddr_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpAddr_Delete;
GO
CREATE PROCEDURE dbo.usp_EmpAddr_Delete
    @AddressNo INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.EmployeeAddress WHERE AddressNo = @AddressNo)
            THROW 62020, 'AddressNo not found.', 1;
        DELETE FROM dbo.EmployeeAddress WHERE AddressNo = @AddressNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

-- ── usp_EmpAddr_GetByEmployee ─────────────────────────────────
IF OBJECT_ID('dbo.usp_EmpAddr_GetByEmployee','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpAddr_GetByEmployee;
GO
CREATE PROCEDURE dbo.usp_EmpAddr_GetByEmployee
    @EmployeeNo INT
AS
/*  Purpose : Return all address rows for an employee with full location names.  */
BEGIN
    SET NOCOUNT ON;
    SELECT ea.AddressNo, ea.EmployeeNo, ea.AddressType,
           ea.AddressLine1, ea.AddressLine2,
           ea.CityNo,    ci.CityName,
           ea.StateNo,   s.StateName,
           ea.CountryNo, co.CountryName, co.CountryCode, co.PhoneCode,
           ea.Pincode,
           ea.CreatedAt, ea.UpdatedAt
    FROM   dbo.EmployeeAddress ea
    LEFT JOIN dbo.City    ci ON ci.CityNo    = ea.CityNo
    LEFT JOIN dbo.State   s  ON s.StateNo    = ea.StateNo
    LEFT JOIN dbo.Country co ON co.CountryNo = ea.CountryNo
    WHERE  ea.EmployeeNo = @EmployeeNo
    ORDER BY ea.AddressType;
END;
GO

