-- ============================================================
-- 1. NEW TABLE : dbo.SubDepartment
-- Screen       : Personal Details → Sub-Department dropdown
--                (filtered by selected Department)
-- ============================================================
IF OBJECT_ID('dbo.SubDepartment','U') IS NOT NULL DROP TABLE dbo.SubDepartment;
GO
CREATE TABLE dbo.SubDepartment (
    SubDepartmentNo      INT           NOT NULL IDENTITY(1,1)
        CONSTRAINT PK_SubDept PRIMARY KEY CLUSTERED,
    DepartmentNo         INT           NOT NULL,
    SubDepartmentName    NVARCHAR(100) NOT NULL,
    SubDepartmentCode    VARCHAR(10)   NOT NULL,
    Description          NVARCHAR(300) NULL,
    DisplayOrder         SMALLINT      NOT NULL CONSTRAINT DF_SubDept_Ord     DEFAULT 99,
    Status               TINYINT       NOT NULL CONSTRAINT DF_SubDept_Status  DEFAULT 1,
    CreatedAt            DATETIME2(0)  NOT NULL CONSTRAINT DF_SubDept_CA      DEFAULT GETDATE(),
    UpdatedAt            DATETIME2(0)  NULL,
    CreatedBy            INT           NULL,
    CONSTRAINT UQ_SubDept_Code   UNIQUE (DepartmentNo, SubDepartmentCode),
    CONSTRAINT CK_SubDept_Status CHECK (Status IN (0,1)),
    CONSTRAINT FK_SubDept_Dept   FOREIGN KEY (DepartmentNo) REFERENCES dbo.Department (DepartmentNo) ON DELETE CASCADE ON UPDATE CASCADE
);
GO
CREATE NONCLUSTERED INDEX IX_SubDept_Dept ON dbo.SubDepartment (DepartmentNo);
GO
PRINT 'Table dbo.SubDepartment created.';
GO

-- Wire Employee.SubDepartmentNo → SubDepartment (was a plain INT comment before)
IF NOT EXISTS (
    SELECT 1 FROM sys.foreign_keys
    WHERE name = 'FK_Emp_SubDept' AND parent_object_id = OBJECT_ID('dbo.Employee')
)
    ALTER TABLE dbo.Employee
        ADD CONSTRAINT FK_Emp_SubDept
            FOREIGN KEY (SubDepartmentNo) REFERENCES dbo.SubDepartment (SubDepartmentNo)
            ON DELETE SET NULL ON UPDATE CASCADE;
GO

