-- Screen       : PF/ESI Details tab
-- ============================================================
IF OBJECT_ID('dbo.EmployeePFESI','U') IS NOT NULL DROP TABLE dbo.EmployeePFESI;
GO
CREATE TABLE dbo.EmployeePFESI (
    PFESINo              INT           NOT NULL IDENTITY(1,1)
        CONSTRAINT PK_EmpPFESI PRIMARY KEY CLUSTERED,
    EmployeeNo           INT           NOT NULL,

    -- PF section (shown when PF Scheme Applicable checkbox is ticked)
    PFApplicable         BIT           NOT NULL CONSTRAINT DF_PFESI_PFApp     DEFAULT 0,
    PFJoinDate           DATE          NULL,
    PFScheme             VARCHAR(10)   NULL,   -- 'Govt' | 'Company'
    PFNumber             VARCHAR(30)   NULL,
    UANNumber            VARCHAR(12)   NULL,   -- 12-digit Universal Account Number
    EPFAccountNo         INT           NULL,   -- FK to AllowanceDeduction (deduction account)

    -- ESI section (shown when ESI Scheme Applicable checkbox is ticked)
    ESIApplicable        BIT           NOT NULL CONSTRAINT DF_PFESI_ESIApp    DEFAULT 0,
    ESINumber            VARCHAR(17)   NULL,   -- 17-digit ESI number
    ESIAccountNo         INT           NULL,   -- FK to AllowanceDeduction (ESI account)

    CreatedAt            DATETIME2(0)  NOT NULL CONSTRAINT DF_PFESI_CA        DEFAULT GETDATE(),
    UpdatedAt            DATETIME2(0)  NULL,

    CONSTRAINT UQ_PFESI_Emp      UNIQUE (EmployeeNo),   -- one row per employee
    CONSTRAINT CK_PFESI_Scheme   CHECK (PFScheme IS NULL OR PFScheme IN ('Govt','Company')),
    CONSTRAINT CK_PFESI_UAN      CHECK (UANNumber IS NULL OR UANNumber LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]'),
    CONSTRAINT FK_PFESI_Emp      FOREIGN KEY (EmployeeNo)   REFERENCES dbo.Employee          (EmployeeNo) ON DELETE CASCADE,
    CONSTRAINT FK_PFESI_EPFAcct  FOREIGN KEY (EPFAccountNo) REFERENCES dbo.AllowanceDeduction(AllowanceDeductionNo) ON DELETE SET NULL,
    CONSTRAINT FK_PFESI_ESIAcct  FOREIGN KEY (ESIAccountNo) REFERENCES dbo.AllowanceDeduction(AllowanceDeductionNo) ON DELETE NO ACTION
);
GO
CREATE NONCLUSTERED INDEX IX_PFESI_Emp ON dbo.EmployeePFESI (EmployeeNo);
GO
