-- ============================================================
-- 8. TRIGGERS — dbo.SubDepartment & dbo.EmployeePFESI
-- ============================================================

-- TR_SubDept_Timestamps
IF OBJECT_ID('dbo.TR_SubDept_Timestamps','TR') IS NOT NULL DROP TRIGGER dbo.TR_SubDept_Timestamps;
GO
CREATE TRIGGER dbo.TR_SubDept_Timestamps
ON dbo.SubDepartment
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
        UPDATE s SET s.CreatedAt = ISNULL(s.CreatedAt, GETDATE())
        FROM dbo.SubDepartment s INNER JOIN inserted i ON s.SubDepartmentNo = i.SubDepartmentNo;
    ELSE
        UPDATE s SET s.UpdatedAt = GETDATE()
        FROM dbo.SubDepartment s INNER JOIN inserted i ON s.SubDepartmentNo = i.SubDepartmentNo;
END;
GO

-- TR_SubDept_Audit
IF OBJECT_ID('dbo.TR_SubDept_Audit','TR') IS NOT NULL DROP TRIGGER dbo.TR_SubDept_Audit;
GO
CREATE TRIGGER dbo.TR_SubDept_Audit
ON dbo.SubDepartment
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @action CHAR(1) =
        CASE WHEN EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) THEN 'U'
             WHEN EXISTS(SELECT 1 FROM inserted) THEN 'I'
             ELSE 'D' END;
    INSERT INTO audit.AuditLog
        (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedByUserID, ChangedAt)
    SELECT 'dbo','SubDepartment',
        CAST(COALESCE(i.SubDepartmentNo, d.SubDepartmentNo) AS NVARCHAR(50)), @action,
        CASE WHEN d.SubDepartmentNo IS NOT NULL
             THEN 'SubDepartmentName=' + ISNULL(d.SubDepartmentName,'') + '; Status=' + CAST(d.Status AS VARCHAR)
             ELSE NULL END,
        CASE WHEN i.SubDepartmentNo IS NOT NULL
             THEN 'SubDepartmentName=' + ISNULL(i.SubDepartmentName,'') + '; Status=' + CAST(i.Status AS VARCHAR)
             ELSE NULL END,
        ISNULL(i.CreatedBy, d.CreatedBy),
        GETDATE()
    FROM inserted i FULL OUTER JOIN deleted d ON i.SubDepartmentNo = d.SubDepartmentNo;
END;
GO

-- TR_PFESI_Timestamps
IF OBJECT_ID('dbo.TR_PFESI_Timestamps','TR') IS NOT NULL DROP TRIGGER dbo.TR_PFESI_Timestamps;
GO
CREATE TRIGGER dbo.TR_PFESI_Timestamps
ON dbo.EmployeePFESI
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM deleted)
        UPDATE p SET p.CreatedAt = ISNULL(p.CreatedAt, GETDATE())
        FROM dbo.EmployeePFESI p INNER JOIN inserted i ON p.PFESINo = i.PFESINo;
    ELSE
        UPDATE p SET p.UpdatedAt = GETDATE()
        FROM dbo.EmployeePFESI p INNER JOIN inserted i ON p.PFESINo = i.PFESINo;
END;
GO

-- TR_PFESI_Audit
IF OBJECT_ID('dbo.TR_PFESI_Audit','TR') IS NOT NULL DROP TRIGGER dbo.TR_PFESI_Audit;
GO
CREATE TRIGGER dbo.TR_PFESI_Audit
ON dbo.EmployeePFESI
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @action CHAR(1) =
        CASE WHEN EXISTS(SELECT 1 FROM inserted) AND EXISTS(SELECT 1 FROM deleted) THEN 'U'
             WHEN EXISTS(SELECT 1 FROM inserted) THEN 'I'
             ELSE 'D' END;
    INSERT INTO audit.AuditLog
        (SchemaName, TableName, EntityID, Action, OldValue, NewValue, ChangedByUserID, ChangedAt)
    SELECT 'dbo','EmployeePFESI',
        CAST(COALESCE(i.EmployeeNo, d.EmployeeNo) AS NVARCHAR(50)), @action,
        CASE WHEN d.PFESINo IS NOT NULL
             THEN 'PFApplicable=' + CAST(d.PFApplicable AS VARCHAR) + '; PFNumber=' + ISNULL(d.PFNumber,'') +
                  '; UANNumber=' + ISNULL(d.UANNumber,'') + '; ESIApplicable=' + CAST(d.ESIApplicable AS VARCHAR) +
                  '; ESINumber=' + ISNULL(d.ESINumber,'')
             ELSE NULL END,
        CASE WHEN i.PFESINo IS NOT NULL
             THEN 'PFApplicable=' + CAST(i.PFApplicable AS VARCHAR) + '; PFNumber=' + ISNULL(i.PFNumber,'') +
                  '; UANNumber=' + ISNULL(i.UANNumber,'') + '; ESIApplicable=' + CAST(i.ESIApplicable AS VARCHAR) +
                  '; ESINumber=' + ISNULL(i.ESINumber,'')
             ELSE NULL END,
        NULL, GETDATE()
    FROM inserted i FULL OUTER JOIN deleted d ON i.PFESINo = d.PFESINo;
END;
GO
