-- ============================================================
-- 9. STORED PROCEDURES — dbo.SubDepartment
-- ============================================================

IF OBJECT_ID('dbo.usp_SubDept_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_SubDept_Insert;
GO
CREATE PROCEDURE dbo.usp_SubDept_Insert
    @DepartmentNo      INT,
    @SubDepartmentName NVARCHAR(100),
    @SubDepartmentCode VARCHAR(10),
    @Description       NVARCHAR(300) = NULL,
    @DisplayOrder      SMALLINT      = 99,
    @Status            TINYINT       = 1,
    @CreatedBy         INT           = NULL,
    @NewSubDeptNo      INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Department WHERE DepartmentNo = @DepartmentNo AND Status = 1)
            THROW 63001, 'DepartmentNo not found or inactive.', 1;
        IF EXISTS (SELECT 1 FROM dbo.SubDepartment WHERE DepartmentNo = @DepartmentNo AND SubDepartmentCode = @SubDepartmentCode)
            THROW 63002, 'SubDepartmentCode already exists for this Department.', 1;
        INSERT INTO dbo.SubDepartment
            (DepartmentNo, SubDepartmentName, SubDepartmentCode, Description, DisplayOrder, Status, CreatedBy)
        VALUES
            (@DepartmentNo, @SubDepartmentName, @SubDepartmentCode, @Description, @DisplayOrder, @Status, @CreatedBy);
        SET @NewSubDeptNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_SubDept_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_SubDept_Update;
GO
CREATE PROCEDURE dbo.usp_SubDept_Update
    @SubDepartmentNo   INT,
    @SubDepartmentName NVARCHAR(100) = NULL,
    @SubDepartmentCode VARCHAR(10)   = NULL,
    @Description       NVARCHAR(300) = NULL,
    @DisplayOrder      SMALLINT      = NULL,
    @Status            TINYINT       = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.SubDepartment WHERE SubDepartmentNo = @SubDepartmentNo)
            THROW 63010, 'SubDepartmentNo not found.', 1;
        UPDATE dbo.SubDepartment
        SET SubDepartmentName = ISNULL(@SubDepartmentName, SubDepartmentName),
            SubDepartmentCode = ISNULL(@SubDepartmentCode, SubDepartmentCode),
            Description       = ISNULL(@Description,       Description),
            DisplayOrder      = ISNULL(@DisplayOrder,       DisplayOrder),
            Status            = ISNULL(@Status,             Status)
        WHERE SubDepartmentNo = @SubDepartmentNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_SubDept_Delete','P') IS NOT NULL DROP PROCEDURE dbo.usp_SubDept_Delete;
GO
CREATE PROCEDURE dbo.usp_SubDept_Delete
    @SubDepartmentNo INT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.SubDepartment WHERE SubDepartmentNo = @SubDepartmentNo)
            THROW 63020, 'SubDepartmentNo not found.', 1;
        IF EXISTS (SELECT 1 FROM dbo.Employee WHERE SubDepartmentNo = @SubDepartmentNo AND EmployeeStatus = 'Active')
            THROW 63021, 'Cannot deactivate — active Employees are assigned to this Sub-Department.', 1;
        UPDATE dbo.SubDepartment SET Status = 0 WHERE SubDepartmentNo = @SubDepartmentNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_SubDept_GetByID','P') IS NOT NULL DROP PROCEDURE dbo.usp_SubDept_GetByID;
GO
CREATE PROCEDURE dbo.usp_SubDept_GetByID @SubDepartmentNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT sd.SubDepartmentNo, sd.DepartmentNo, d.DepartmentName, d.DepartmentShortName,
           sd.SubDepartmentName, sd.SubDepartmentCode, sd.Description,
           sd.DisplayOrder, sd.Status, sd.CreatedAt, sd.UpdatedAt
    FROM   dbo.SubDepartment sd
    INNER JOIN dbo.Department d ON d.DepartmentNo = sd.DepartmentNo
    WHERE  sd.SubDepartmentNo = @SubDepartmentNo;
END;
GO

IF OBJECT_ID('dbo.usp_SubDept_List','P') IS NOT NULL DROP PROCEDURE dbo.usp_SubDept_List;
GO
CREATE PROCEDURE dbo.usp_SubDept_List
    @DepartmentNo INT    = NULL,
    @Status       TINYINT = NULL,
    @SearchTerm   NVARCHAR(100) = NULL,
    @PageNo       INT    = 1,
    @PageSize     INT    = 50,
    @TotalCount   INT    OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT @TotalCount = COUNT(*)
    FROM   dbo.SubDepartment sd
    WHERE  (@DepartmentNo IS NULL OR sd.DepartmentNo    = @DepartmentNo)
      AND  (@Status       IS NULL OR sd.Status          = @Status)
      AND  (@SearchTerm   IS NULL OR sd.SubDepartmentName LIKE '%' + @SearchTerm + '%');

    SELECT sd.SubDepartmentNo, sd.DepartmentNo, d.DepartmentName,
           sd.SubDepartmentName, sd.SubDepartmentCode, sd.Description,
           sd.DisplayOrder, sd.Status
    FROM   dbo.SubDepartment sd
    INNER JOIN dbo.Department d ON d.DepartmentNo = sd.DepartmentNo
    WHERE  (@DepartmentNo IS NULL OR sd.DepartmentNo    = @DepartmentNo)
      AND  (@Status       IS NULL OR sd.Status          = @Status)
      AND  (@SearchTerm   IS NULL OR sd.SubDepartmentName LIKE '%' + @SearchTerm + '%')
    ORDER BY d.DepartmentName, sd.DisplayOrder, sd.SubDepartmentName
    OFFSET (@PageNo - 1) * @PageSize ROWS
    FETCH  NEXT @PageSize ROWS ONLY;
END;
GO
PRINT 'Stored procedures for SubDepartment created.';
GO

