IF OBJECT_ID('dbo.usp_EmpPFESI_Upsert','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpPFESI_Upsert;
GO
CREATE PROCEDURE dbo.usp_EmpPFESI_Upsert
    @EmployeeNo       INT,
    @PFApplicable     BIT           = 0,
    @PFJoinDate       DATE          = NULL,
    @PFScheme         VARCHAR(10)   = NULL,
    @PFNumber         VARCHAR(30)   = NULL,
    @UANNumber        VARCHAR(12)   = NULL,
    @EPFAccountNo     INT           = NULL,
    @ESIApplicable    BIT           = 0,
    @ESINumber        VARCHAR(17)   = NULL,
    @ESIAccountNo     INT           = NULL
AS
/*  Purpose : Insert or update PF/ESI details for an employee (one row per employee).  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeNo = @EmployeeNo)
            THROW 64001, 'EmployeeNo not found.', 1;
        IF EXISTS (SELECT 1 FROM dbo.EmployeePFESI WHERE EmployeeNo = @EmployeeNo)
            UPDATE dbo.EmployeePFESI
            SET PFApplicable  = @PFApplicable,
                PFJoinDate    = @PFJoinDate,
                PFScheme      = @PFScheme,
                PFNumber      = ISNULL(@PFNumber,    PFNumber),
                UANNumber     = ISNULL(@UANNumber,   UANNumber),
                EPFAccountNo  = ISNULL(@EPFAccountNo,EPFAccountNo),
                ESIApplicable = @ESIApplicable,
                ESINumber     = ISNULL(@ESINumber,   ESINumber),
                ESIAccountNo  = ISNULL(@ESIAccountNo,ESIAccountNo),
                UpdatedAt     = GETDATE()
            WHERE EmployeeNo  = @EmployeeNo;
        ELSE
            INSERT INTO dbo.EmployeePFESI
                (EmployeeNo, PFApplicable, PFJoinDate, PFScheme, PFNumber, UANNumber, EPFAccountNo,
                 ESIApplicable, ESINumber, ESIAccountNo)
            VALUES
                (@EmployeeNo, @PFApplicable, @PFJoinDate, @PFScheme, @PFNumber, @UANNumber, @EPFAccountNo,
                 @ESIApplicable, @ESINumber, @ESIAccountNo);
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_EmpPFESI_GetByEmployee','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpPFESI_GetByEmployee;
GO
CREATE PROCEDURE dbo.usp_EmpPFESI_GetByEmployee @EmployeeNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT p.PFESINo, p.EmployeeNo,
           p.PFApplicable, p.PFJoinDate, p.PFScheme, p.PFNumber, p.UANNumber,
           p.EPFAccountNo,  epf.ADName AS EPFAccountName,
           p.ESIApplicable, p.ESINumber,
           p.ESIAccountNo,  esi.ADName AS ESIAccountName,
           p.CreatedAt, p.UpdatedAt
    FROM   dbo.EmployeePFESI p
    LEFT JOIN dbo.AllowanceDeduction epf ON epf.AllowanceDeductionNo = p.EPFAccountNo
    LEFT JOIN dbo.AllowanceDeduction esi ON esi.AllowanceDeductionNo = p.ESIAccountNo
    WHERE  p.EmployeeNo = @EmployeeNo;
END;
GO
