-- ============================================================

IF OBJECT_ID('dbo.usp_Employee_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_Employee_Insert;
GO
CREATE PROCEDURE dbo.usp_Employee_Insert
    @EmployeeCode       VARCHAR(20),
    @FirstName          NVARCHAR(60),
    @LastName           NVARCHAR(60),
    @DateOfBirth        DATE,
    @DateOfJoining      DATE,
    @GenderNo           TINYINT,
    @BloodGroupNo       TINYINT,
    @MaritalStatusNo    TINYINT,
    @NationalityNo      TINYINT,
    @ReligionNo         TINYINT       = NULL,
    @OtherReligion      NVARCHAR(100) = NULL,
    @FatherHusbandName  NVARCHAR(100),
    @MotherName         NVARCHAR(100),
    @FatherOccupationNo SMALLINT      = NULL,
    @MotherOccupationNo SMALLINT      = NULL,
    @SpouseName         NVARCHAR(100) = NULL,
    @SpouseOccupationNo SMALLINT      = NULL,
    @PANNumber          VARCHAR(10),
    @AadhaarEIDNumber   VARCHAR(12),
    @VoterID            VARCHAR(20)   = NULL,
    @DepartmentNo       INT,
    @SubDepartmentNo    INT           = NULL,
    @DesignationNo      INT,
    @DivisionNo         INT           = NULL,
    @GradeNo            INT           = NULL,
    @ReportingManagerNo INT           = NULL,
    @OfficialMobile     VARCHAR(15)   = NULL,
    @PersonalMobile     VARCHAR(15)   = NULL,
    @OfficialEmail      NVARCHAR(150) = NULL,
    @PersonalEmail      NVARCHAR(150) = NULL,
    @CreatedBy          INT           = NULL,
    @NewEmployeeNo      INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeCode = @EmployeeCode)
            THROW 50040, 'EmployeeCode already exists.', 1;
        IF @DateOfBirth >= CAST(GETDATE() AS DATE)
            THROW 50041, 'Date of Birth cannot be today or in the future.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.Department  WHERE DepartmentNo  = @DepartmentNo  AND Status = 1)
            THROW 50042, 'Invalid or inactive DepartmentNo.', 1;
        IF NOT EXISTS (SELECT 1 FROM dbo.Designation WHERE DesignationNo = @DesignationNo AND Status = 1)
            THROW 50043, 'Invalid or inactive DesignationNo.', 1;
        IF @SubDepartmentNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.SubDepartment WHERE SubDepartmentNo = @SubDepartmentNo AND DepartmentNo = @DepartmentNo AND Status = 1)
            THROW 50044, 'SubDepartmentNo not found or does not belong to the selected Department.', 1;

        INSERT INTO dbo.Employee
            (EmployeeCode, FirstName, LastName, DateOfBirth, DateOfJoining,
             GenderNo, BloodGroupNo, MaritalStatusNo, NationalityNo,
             ReligionNo, OtherReligion,
             FatherHusbandName, MotherName, FatherOccupationNo, MotherOccupationNo,
             SpouseName, SpouseOccupationNo,
             PANNumber, AadhaarEIDNumber, VoterID,
             DepartmentNo, SubDepartmentNo, DesignationNo, DivisionNo, GradeNo, ReportingManagerNo,
             OfficialMobile, PersonalMobile, OfficialEmail, PersonalEmail,
             CreatedBy)
        VALUES
            (@EmployeeCode, @FirstName, @LastName, @DateOfBirth, @DateOfJoining,
             @GenderNo, @BloodGroupNo, @MaritalStatusNo, @NationalityNo,
             @ReligionNo, @OtherReligion,
             @FatherHusbandName, @MotherName, @FatherOccupationNo, @MotherOccupationNo,
             @SpouseName, @SpouseOccupationNo,
             @PANNumber, @AadhaarEIDNumber, @VoterID,
             @DepartmentNo, @SubDepartmentNo, @DesignationNo, @DivisionNo, @GradeNo, @ReportingManagerNo,
             @OfficialMobile, @PersonalMobile, @OfficialEmail, @PersonalEmail,
             @CreatedBy);

        SET @NewEmployeeNo = SCOPE_IDENTITY();

        -- Create default draft wizard record
        IF OBJECT_ID('dbo.OnboardingWizardDraft','U') IS NOT NULL
            INSERT INTO dbo.OnboardingWizardDraft (EmployeeNo, CurrentStep)
            VALUES (@NewEmployeeNo, 1);

        -- Auto-create empty PF/ESI record
        INSERT INTO dbo.EmployeePFESI (EmployeeNo) VALUES (@NewEmployeeNo);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_Employee_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_Employee_Update;
GO
CREATE PROCEDURE dbo.usp_Employee_Update
    @EmployeeNo         INT,
    @FirstName          NVARCHAR(60)  = NULL,
    @LastName           NVARCHAR(60)  = NULL,
    @DateOfBirth        DATE          = NULL,
    @GenderNo           TINYINT       = NULL,
    @BloodGroupNo       TINYINT       = NULL,
    @MaritalStatusNo    TINYINT       = NULL,
    @NationalityNo      TINYINT       = NULL,
    @ReligionNo         TINYINT       = NULL,
    @OtherReligion      NVARCHAR(100) = NULL,
    @FatherHusbandName  NVARCHAR(100) = NULL,
    @MotherName         NVARCHAR(100) = NULL,
    @FatherOccupationNo SMALLINT      = NULL,
    @MotherOccupationNo SMALLINT      = NULL,
    @SpouseName         NVARCHAR(100) = NULL,
    @SpouseOccupationNo SMALLINT      = NULL,
    @VoterID            VARCHAR(20)   = NULL,
    @DepartmentNo       INT           = NULL,
    @SubDepartmentNo    INT           = NULL,
    @DesignationNo      INT           = NULL,
    @DivisionNo         INT           = NULL,
    @GradeNo            INT           = NULL,
    @ReportingManagerNo INT           = NULL,
    @OfficialMobile     VARCHAR(15)   = NULL,
    @PersonalMobile     VARCHAR(15)   = NULL,
    @OfficialEmail      NVARCHAR(150) = NULL,
    @PersonalEmail      NVARCHAR(150) = NULL,
    @EmployeeStatus     VARCHAR(10)   = NULL,
    @ProfilePhoto       NVARCHAR(500) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeNo = @EmployeeNo)
            THROW 50050, 'EmployeeNo not found.', 1;
        IF @SubDepartmentNo IS NOT NULL AND @DepartmentNo IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM dbo.SubDepartment
            WHERE SubDepartmentNo = @SubDepartmentNo AND DepartmentNo = @DepartmentNo AND Status = 1)
            THROW 50051, 'SubDepartmentNo does not belong to the selected Department.', 1;

        UPDATE dbo.Employee
        SET
            FirstName          = ISNULL(@FirstName,          FirstName),
            LastName           = ISNULL(@LastName,           LastName),
            DateOfBirth        = ISNULL(@DateOfBirth,        DateOfBirth),
            GenderNo           = ISNULL(@GenderNo,           GenderNo),
            BloodGroupNo       = ISNULL(@BloodGroupNo,       BloodGroupNo),
            MaritalStatusNo    = ISNULL(@MaritalStatusNo,    MaritalStatusNo),
            NationalityNo      = ISNULL(@NationalityNo,      NationalityNo),
            ReligionNo         = ISNULL(@ReligionNo,         ReligionNo),
            OtherReligion      = ISNULL(@OtherReligion,      OtherReligion),
            FatherHusbandName  = ISNULL(@FatherHusbandName,  FatherHusbandName),
            MotherName         = ISNULL(@MotherName,         MotherName),
            FatherOccupationNo = ISNULL(@FatherOccupationNo, FatherOccupationNo),
            MotherOccupationNo = ISNULL(@MotherOccupationNo, MotherOccupationNo),
            SpouseName         = ISNULL(@SpouseName,         SpouseName),
            SpouseOccupationNo = ISNULL(@SpouseOccupationNo, SpouseOccupationNo),
            VoterID            = ISNULL(@VoterID,            VoterID),
            DepartmentNo       = ISNULL(@DepartmentNo,       DepartmentNo),
            SubDepartmentNo    = ISNULL(@SubDepartmentNo,    SubDepartmentNo),
            DesignationNo      = ISNULL(@DesignationNo,      DesignationNo),
            DivisionNo         = ISNULL(@DivisionNo,         DivisionNo),
            GradeNo            = ISNULL(@GradeNo,            GradeNo),
            ReportingManagerNo = ISNULL(@ReportingManagerNo, ReportingManagerNo),
            OfficialMobile     = ISNULL(@OfficialMobile,     OfficialMobile),
            PersonalMobile     = ISNULL(@PersonalMobile,     PersonalMobile),
            OfficialEmail      = ISNULL(@OfficialEmail,      OfficialEmail),
            PersonalEmail      = ISNULL(@PersonalEmail,      PersonalEmail),
            EmployeeStatus     = ISNULL(@EmployeeStatus,     EmployeeStatus),
            ProfilePhoto       = ISNULL(@ProfilePhoto,       ProfilePhoto)
            -- UpdatedAt handled by trigger
        WHERE EmployeeNo = @EmployeeNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO
PRINT 'usp_Employee_Insert and usp_Employee_Update recreated with all new fields.';
GO

