AS
BEGIN
    SET NOCOUNT ON;
    SELECT ee.EduNo, ee.EmployeeNo,
           ee.QualificationNo, q.QualificationName,
           ee.EducationLevelNo, el.LevelName AS EducationLevelName,
           ee.SpecialisationField, ee.InstituteName, ee.BoardUniversity,
           ee.PassingYear, ee.CGPA, ee.GradeLetter, ee.Percentage,
           ee.CertificationName, ee.CertificationValidTill,
           ee.IsHighestQual, ee.CreatedAt
