-- ============================================================
-- 14. UPDATE usp_EmpBank — add AccountHolderName, salary fields
-- ============================================================

IF OBJECT_ID('dbo.usp_EmpBank_Insert','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpBank_Insert;
GO
CREATE PROCEDURE dbo.usp_EmpBank_Insert
    @EmployeeNo           INT,
    @AccountHolderName    NVARCHAR(150) = NULL,
    @BankName             NVARCHAR(100),
    @AccountNumber        VARCHAR(18),
    @IFSCCode             VARCHAR(11),
    @BranchName           NVARCHAR(100),
    @AccountType          VARCHAR(10)   = 'Saving',
    @TransferSalarySlipBy VARCHAR(20)   = NULL,
    @SalaryFormat         VARCHAR(20)   = NULL,
    @SalaryAccountNo      INT           = NULL,
    @AdvancedAccountNo    INT           = NULL,
    @IsActive             BIT           = 1,
    @NewBankDetailNo      INT           OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeNo = @EmployeeNo)
            THROW 67001, 'EmployeeNo not found.', 1;
        IF EXISTS (SELECT 1 FROM dbo.EmployeeBankDetail WHERE BankName = @BankName AND AccountNumber = @AccountNumber)
            THROW 67002, 'Bank account already exists.', 1;
        INSERT INTO dbo.EmployeeBankDetail
            (EmployeeNo, AccountHolderName, BankName, AccountNumber, IFSCCode, BranchName,
             AccountType, TransferSalarySlipBy, SalaryFormat, SalaryAccountNo, AdvancedAccountNo, IsActive)
        VALUES
            (@EmployeeNo, @AccountHolderName, @BankName, @AccountNumber, @IFSCCode, @BranchName,
             @AccountType, @TransferSalarySlipBy, @SalaryFormat, @SalaryAccountNo, @AdvancedAccountNo, @IsActive);
        SET @NewBankDetailNo = SCOPE_IDENTITY();
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_EmpBank_Update','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpBank_Update;
GO
CREATE PROCEDURE dbo.usp_EmpBank_Update
    @BankDetailNo         INT,
    @AccountHolderName    NVARCHAR(150) = NULL,
    @BankName             NVARCHAR(100) = NULL,
    @AccountNumber        VARCHAR(18)   = NULL,
    @IFSCCode             VARCHAR(11)   = NULL,
    @BranchName           NVARCHAR(100) = NULL,
    @AccountType          VARCHAR(10)   = NULL,
    @TransferSalarySlipBy VARCHAR(20)   = NULL,
    @SalaryFormat         VARCHAR(20)   = NULL,
    @SalaryAccountNo      INT           = NULL,
    @AdvancedAccountNo    INT           = NULL,
    @IsActive             BIT           = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.EmployeeBankDetail WHERE BankDetailNo = @BankDetailNo)
            THROW 67010, 'BankDetailNo not found.', 1;
        UPDATE dbo.EmployeeBankDetail
        SET AccountHolderName    = ISNULL(@AccountHolderName,    AccountHolderName),
            BankName             = ISNULL(@BankName,             BankName),
            AccountNumber        = ISNULL(@AccountNumber,        AccountNumber),
            IFSCCode             = ISNULL(@IFSCCode,             IFSCCode),
            BranchName           = ISNULL(@BranchName,           BranchName),
            AccountType          = ISNULL(@AccountType,          AccountType),
            TransferSalarySlipBy = ISNULL(@TransferSalarySlipBy, TransferSalarySlipBy),
            SalaryFormat         = ISNULL(@SalaryFormat,         SalaryFormat),
            SalaryAccountNo      = ISNULL(@SalaryAccountNo,      SalaryAccountNo),
            AdvancedAccountNo    = ISNULL(@AdvancedAccountNo,    AdvancedAccountNo),
            IsActive             = ISNULL(@IsActive,             IsActive),
            UpdatedAt            = GETDATE()
        WHERE BankDetailNo = @BankDetailNo;
        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION; THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_EmpBank_GetByEmployee','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpBank_GetByEmployee;
GO
CREATE PROCEDURE dbo.usp_EmpBank_GetByEmployee @EmployeeNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT b.BankDetailNo, b.EmployeeNo, b.AccountHolderName,
           b.BankName, b.AccountNumber, b.IFSCCode, b.BranchName, b.AccountType,
           b.TransferSalarySlipBy, b.SalaryFormat,
           b.SalaryAccountNo,   sa.ADName AS SalaryAccountName,
           b.AdvancedAccountNo, aa.ADName AS AdvancedAccountName,
           b.IsActive, b.IsReadOnly, b.CreatedAt, b.UpdatedAt
    FROM   dbo.EmployeeBankDetail b
    LEFT JOIN dbo.AllowanceDeduction sa ON sa.AllowanceDeductionNo = b.SalaryAccountNo
    LEFT JOIN dbo.AllowanceDeduction aa ON aa.AllowanceDeductionNo = b.AdvancedAccountNo
    WHERE  b.EmployeeNo = @EmployeeNo
    ORDER BY b.IsActive DESC, b.CreatedAt DESC;
END;
GO
PRINT 'Stored procedures for EmployeeBankDetail recreated.';
GO

-- ============================================================
-- 15. UPDATE usp_EmpLeaving — add resignation/dismiss fields
-- ============================================================

IF OBJECT_ID('dbo.usp_EmpLeaving_Upsert','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpLeaving_Upsert;
GO
CREATE PROCEDURE dbo.usp_EmpLeaving_Upsert
    @EmployeeNo              INT,
    @LeavingDate             DATE          = NULL,
    @LastWorkingDate         DATE          = NULL,
    @ResignationSubmitDate   DATE          = NULL,
    @FinalSettlementDate     DATE          = NULL,
    @LeavingReasonNo         INT           = NULL,
    @LeavingRemarks          NVARCHAR(500) = NULL,
    @IsDismissed             BIT           = 0,
    @DismissDate             DATE          = NULL,
    @DismissRemarks          NVARCHAR(500) = NULL,
    @SettlementDate          DATE          = NULL,
    @SettlementType          VARCHAR(20)   = NULL,
    @SubmittedByNo           INT           = NULL,
    @LeavingDetailNo         INT           OUTPUT
AS
/*  Purpose : Record leaving/resignation/dismissal details for an employee.
              Updates EmployeeStatus to 'Inactive' automatically.  */
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;
        IF NOT EXISTS (SELECT 1 FROM dbo.Employee WHERE EmployeeNo = @EmployeeNo)
            THROW 68001, 'EmployeeNo not found.', 1;

        IF EXISTS (SELECT 1 FROM dbo.EmployeeLeavingDetail WHERE EmployeeNo = @EmployeeNo)
        BEGIN
            UPDATE dbo.EmployeeLeavingDetail
            SET LeavingDate            = ISNULL(@LeavingDate,           LeavingDate),
                LastWorkingDate        = ISNULL(@LastWorkingDate,       LastWorkingDate),
                ResignationSubmitDate  = ISNULL(@ResignationSubmitDate, ResignationSubmitDate),
                FinalSettlementDate    = ISNULL(@FinalSettlementDate,   FinalSettlementDate),
                LeavingReasonNo        = ISNULL(@LeavingReasonNo,       LeavingReasonNo),
                LeavingRemarks         = ISNULL(@LeavingRemarks,        LeavingRemarks),
                IsDismissed            = ISNULL(@IsDismissed,           IsDismissed),
                DismissDate            = ISNULL(@DismissDate,           DismissDate),
                DismissRemarks         = ISNULL(@DismissRemarks,        DismissRemarks),
                SettlementDate         = ISNULL(@SettlementDate,        SettlementDate),
                SettlementType         = ISNULL(@SettlementType,        SettlementType),
                SubmittedByNo          = ISNULL(@SubmittedByNo,         SubmittedByNo)
            WHERE EmployeeNo = @EmployeeNo;

            SELECT @LeavingDetailNo = LeavingDetailNo FROM dbo.EmployeeLeavingDetail WHERE EmployeeNo = @EmployeeNo;
        END
        ELSE
        BEGIN
            INSERT INTO dbo.EmployeeLeavingDetail
                (EmployeeNo, LeavingDate, LastWorkingDate,
                 ResignationSubmitDate, FinalSettlementDate,
                 LeavingReasonNo, LeavingRemarks,
                 IsDismissed, DismissDate, DismissRemarks, SettlementDate,
                 SettlementType, SubmittedByNo)
            VALUES
                (@EmployeeNo, @LeavingDate, @LastWorkingDate,
                 @ResignationSubmitDate, @FinalSettlementDate,
                 @LeavingReasonNo, @LeavingRemarks,
                 @IsDismissed, @DismissDate, @DismissRemarks, @SettlementDate,
                 @SettlementType, @SubmittedByNo);

            SET @LeavingDetailNo = SCOPE_IDENTITY();
        END

        -- Mark employee as Inactive
        UPDATE dbo.Employee SET EmployeeStatus = 'Inactive' WHERE EmployeeNo = @EmployeeNo;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

IF OBJECT_ID('dbo.usp_EmpLeaving_GetByEmployee','P') IS NOT NULL DROP PROCEDURE dbo.usp_EmpLeaving_GetByEmployee;
GO
CREATE PROCEDURE dbo.usp_EmpLeaving_GetByEmployee @EmployeeNo INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ld.LeavingDetailNo, ld.EmployeeNo,
           ld.LeavingDate, ld.LastWorkingDate,
           ld.ResignationSubmitDate, ld.FinalSettlementDate,
           ld.LeavingReasonNo, lr.ReasonName AS LeavingReasonName,
           ld.LeavingRemarks,
           ld.IsDismissed, ld.DismissDate, ld.DismissRemarks, ld.SettlementDate,
           ld.SettlementType, ld.SubmittedAt, ld.SubmittedByNo
    FROM   dbo.EmployeeLeavingDetail ld
    LEFT JOIN dbo.LeavingReason lr ON lr.LeavingReasonNo = ld.LeavingReasonNo
    WHERE  ld.EmployeeNo = @EmployeeNo;
END;
GO
PRINT 'Stored procedures for EmployeeLeavingDetail recreated.';
GO

